var listaCanais = msg.payload;

if (!Array.isArray(listaCanais) || listaCanais.length < 8) {
    return null;
}

/*
    LINEARIZAÇÃO + FILTRO DIGITAL

    Considerando:
    0    = 0,00 V
    500  = 5,00 V
    1000 = 10,00 V

    Portanto:
    tensão = bruto / 100

    MAPEAMENTO DE CANAIS (atualizado - canais físicos remapeados):
    CH1 = Temp. óleo lubrificante motor BB
    CH2 = Temp. água doce motor BB
    CH3 = Pressão óleo lubrificante motor BB
    CH4 = Rotação (RPM) motor BB
    CH5 = Temp. óleo lubrificante motor BE
    CH6 = Temp. água doce motor BE
    CH7 = Pressão óleo lubrificante motor BE
    CH8 = Rotação (RPM) motor BE
*/

var versaoCodigo = "linearizacao_motor_v4_bb_be";

if (context.get("versaoCodigo") !== versaoCodigo) {
    context.set("amostras", 0);
    context.set("soma", [0, 0, 0, 0, 0, 0, 0, 0]);
    context.set("ema", null);
    context.set("versaoCodigo", versaoCodigo);
}

var canais = [
    {
        nome: "ch1",
        descricao: "Temp Óleo Lub. BB",
        divisor: 100,
        x1: 0,
        y1: 0,
        x2: 10,
        y2: 120,
        unidade: "°C",
        alpha: 0.15,
        deadband: 0.20
    },
    {
        nome: "ch2",
        descricao: "Temp Água Doce BB",
        divisor: 100,
        x1: 0,
        y1: 0,
        x2: 10,
        y2: 120,
        unidade: "°C",
        alpha: 0.15,
        deadband: 0.20
    },
    {
        nome: "ch3",
        descricao: "Pressão Óleo Lub. BB",
        divisor: 100,
        x1: 0,
        y1: 0,
        x2: 10,
        y2: 10,
        unidade: "bar",
        alpha: 0.25,
        deadband: 0.03
    },
    {
        nome: "ch4",
        descricao: "Rotação MCP BB",
        divisor: 100,
        x1: 0,
        y1: 0,
        x2: 10,
        y2: 2000,
        unidade: "RPM",
        alpha: 0.35,
        deadband: 5
    },
    {
        nome: "ch5",
        descricao: "Temp Óleo Lub. BE",
        divisor: 100,
        x1: 0,
        y1: 0,
        x2: 10,
        y2: 120,
        unidade: "°C",
        alpha: 0.15,
        deadband: 0.20
    },
    {
        nome: "ch6",
        descricao: "Temp Água Doce BE",
        divisor: 100,
        x1: 0,
        y1: 0,
        x2: 10,
        y2: 120,
        unidade: "°C",
        alpha: 0.15,
        deadband: 0.20
    },
    {
        nome: "ch7",
        descricao: "Pressão Óleo Lub. BE",
        divisor: 100,
        x1: 0,
        y1: 0,
        x2: 10,
        y2: 10,
        unidade: "bar",
        alpha: 0.25,
        deadband: 0.03
    },
    {
        nome: "ch8",
        descricao: "Rotação MCP BE",
        divisor: 100,
        x1: 0,
        y1: 0,
        x2: 10,
        y2: 2000,
        unidade: "RPM",
        alpha: 0.35,
        deadband: 5
    }
];

function linearizar(valorLido, cfg) {
    var a = (cfg.y2 - cfg.y1) / (cfg.x2 - cfg.x1);
    var b = cfg.y1 - (a * cfg.x1);
    return (a * valorLido) + b;
}

function limitar(valor, minimo, maximo) {
    if (valor < minimo) return minimo;
    if (valor > maximo) return maximo;
    return valor;
}

var amostras = context.get("amostras") || 0;
var soma = context.get("soma") || [0, 0, 0, 0, 0, 0, 0, 0];

// Processa os canais e acumula para média
for (var i = 0; i < 8; i++) {
    var cfg = canais[i];

    var bruto = Number(listaCanais[i]) || 0;
    var tensao = bruto / cfg.divisor;

    var valorLinearizado = linearizar(tensao, cfg);
    var valorLimitado = limitar(valorLinearizado, cfg.y1, cfg.y2);

    global.set(cfg.nome + "_bruto", bruto);
    global.set(cfg.nome + "_tensao", Number(tensao.toFixed(2)));
    global.set(cfg.nome + "_sem_filtro", Number(valorLimitado.toFixed(2)));

    soma[i] += valorLimitado;
}

amostras++;

// Aguarda completar 3 amostras
if (amostras < 3) {
    context.set("amostras", amostras);
    context.set("soma", soma);
    return null;
}

// Calcula a média de 3 amostras
var medias = [];

for (var j = 0; j < 8; j++) {
    medias[j] = soma[j] / 3;
}

// Reseta acumuladores da média
context.set("amostras", 0);
context.set("soma", [0, 0, 0, 0, 0, 0, 0, 0]);

// Aplica filtro EMA
var ema = context.get("ema");

if (!Array.isArray(ema) || ema.length < 8) {
    ema = medias.slice();
}

var filtrados = [];

for (var k = 0; k < 8; k++) {
    var cfgFiltro = canais[k];

    var valorAtual = medias[k];
    var valorAnterior = ema[k];

    // Filtro EMA
    var valorFiltrado = (cfgFiltro.alpha * valorAtual) + ((1 - cfgFiltro.alpha) * valorAnterior);

    // Deadband: se a alteração for pequena, mantém o valor anterior
    if (Math.abs(valorFiltrado - valorAnterior) < cfgFiltro.deadband) {
        valorFiltrado = valorAnterior;
    }

    valorFiltrado = limitar(valorFiltrado, cfgFiltro.y1, cfgFiltro.y2);

    filtrados[k] = Number(valorFiltrado.toFixed(2));
    ema[k] = valorFiltrado;

    global.set("ch" + (k + 1), filtrados[k]);
    global.set("ch" + (k + 1) + "_media3", Number(valorAtual.toFixed(2)));
    global.set("ch" + (k + 1) + "_filtrado", filtrados[k]);
}

context.set("ema", ema);

global.set("ultima_leitura_valida", new Date().toISOString());
global.set("ultima_leitura_ms", Date.now());

// Saídas para os 8 gauges
return [
    { payload: filtrados[0] },
    { payload: filtrados[1] },
    { payload: filtrados[2] },
    { payload: filtrados[3] },
    { payload: filtrados[4] },
    { payload: filtrados[5] },
    { payload: filtrados[6] },
    { payload: filtrados[7] }
];

// FUNÇÃO PARA GRAVAR DADOS DOS MOTORES MCP BB e MCP BE EM CSV
// Fluxo recomendado: Inject periódico -> Function CSV -> File

// =======================
// 1. CONFIGURAÇÕES
// =======================

var separador = ";";

var agoraArquivo = new Date();
var anoArq = agoraArquivo.getFullYear();
var mesArq = doisDigitos(agoraArquivo.getMonth() + 1);
var diaArq = doisDigitos(agoraArquivo.getDate());

msg.filename = "C:\\Dados_Motor\\motor_diesel_" + anoArq + "-" + mesArq + "-" + diaArq + ".csv";

// =======================
// 2. FUNÇÕES AUXILIARES
// =======================

function doisDigitos(n) {
    return n < 10 ? "0" + n : "" + n;
}

function dataHoraAtual() {
    var agora = new Date();
    var ano = agora.getFullYear();
    var mes = doisDigitos(agora.getMonth() + 1);
    var dia = doisDigitos(agora.getDate());
    var hora = doisDigitos(agora.getHours());
    var minuto = doisDigitos(agora.getMinutes());
    var segundo = doisDigitos(agora.getSeconds());
    return ano + "-" + mes + "-" + dia + " " + hora + ":" + minuto + ":" + segundo;
}

function numero(valor, casas) {
    var n = Number(valor);
    if (!isFinite(n)) {
        return "";
    }
    return n.toFixed(casas);
}

function campoTexto(valor) {
    return '"' + String(valor).replace(/"/g, '""') + '"';
}

function juntar(lista) {
    return Array.isArray(lista) ? lista.join(" | ") : "";
}

// =======================
// 3. BUSCA VALORES GLOBAIS (canais já filtrados)
// =======================

var ch1 = global.get("ch1");
var ch2 = global.get("ch2");
var ch3 = global.get("ch3");
var ch4 = global.get("ch4");
var ch5 = global.get("ch5");
var ch6 = global.get("ch6");
var ch7 = global.get("ch7");
var ch8 = global.get("ch8");

if (
    ch1 === undefined && ch2 === undefined && ch3 === undefined && ch4 === undefined &&
    ch5 === undefined && ch6 === undefined && ch7 === undefined && ch8 === undefined
) {
    return null;
}

var diagBB = global.get("diagnostico_mcp_bb") || {};
var diagBE = global.get("diagnostico_mcp_be") || {};
var severidadeGeral = global.get("severidade_geral") || "";

var horimetroBB = global.get("horimetro_mcp_bb_h");
var horimetroBE = global.get("horimetro_mcp_be_h");

var taxaOleoBB = global.get("taxa_temp_oleo_bb_c_min");
var taxaAguaBB = global.get("taxa_temp_agua_bb_c_min");
var taxaPressaoBB = global.get("taxa_pressao_oleo_bb_bar_min");
var taxaRpmBB = global.get("taxa_rpm_bb_rpm_min");

var taxaOleoBE = global.get("taxa_temp_oleo_be_c_min");
var taxaAguaBE = global.get("taxa_temp_agua_be_c_min");
var taxaPressaoBE = global.get("taxa_pressao_oleo_be_bar_min");
var taxaRpmBE = global.get("taxa_rpm_be_rpm_min");

// =======================
// 4. CABEÇALHO
// =======================

var cabecalho = [
    "DataHora",
    "Temp_OL_BB_C", "Temp_Agua_BB_C", "Pressao_OL_BB_bar", "Rotacao_MCP_BB_RPM",
    "Temp_OL_BE_C", "Temp_Agua_BE_C", "Pressao_OL_BE_bar", "Rotacao_MCP_BE_RPM",
    "Estado_BB", "Severidade_BB", "Criticos_BB", "Atencao_Alta_BB", "Atencao_BB", "Avisos_BB", "Informativos_BB",
    "Estado_BE", "Severidade_BE", "Criticos_BE", "Atencao_Alta_BE", "Atencao_BE", "Avisos_BE", "Informativos_BE",
    "Horimetro_BB_h", "Horimetro_BE_h",
    "Taxa_Temp_OL_BB_C_min", "Taxa_Temp_Agua_BB_C_min", "Taxa_Pressao_OL_BB_bar_min", "Taxa_RPM_BB_rpm_min",
    "Taxa_Temp_OL_BE_C_min", "Taxa_Temp_Agua_BE_C_min", "Taxa_Pressao_OL_BE_bar_min", "Taxa_RPM_BE_rpm_min",
    "Severidade_Geral"
].join(separador);

// =======================
// 5. LINHA DE DADOS
// =======================

var linha = [
    campoTexto(dataHoraAtual()),
    numero(ch1, 2), numero(ch2, 2), numero(ch3, 2), numero(ch4, 0),
    numero(ch5, 2), numero(ch6, 2), numero(ch7, 2), numero(ch8, 0),
    campoTexto(diagBB.estado || ""), campoTexto(diagBB.severidade || ""),
    campoTexto(juntar(diagBB.criticos)), campoTexto(juntar(diagBB.atencao_alta)), campoTexto(juntar(diagBB.atencao)),
    campoTexto(juntar(diagBB.avisos)), campoTexto(juntar(diagBB.informativos)),
    campoTexto(diagBE.estado || ""), campoTexto(diagBE.severidade || ""),
    campoTexto(juntar(diagBE.criticos)), campoTexto(juntar(diagBE.atencao_alta)), campoTexto(juntar(diagBE.atencao)),
    campoTexto(juntar(diagBE.avisos)), campoTexto(juntar(diagBE.informativos)),
    numero(horimetroBB, 2), numero(horimetroBE, 2),
    numero(taxaOleoBB, 2), numero(taxaAguaBB, 2), numero(taxaPressaoBB, 3), numero(taxaRpmBB, 0),
    numero(taxaOleoBE, 2), numero(taxaAguaBE, 2), numero(taxaPressaoBE, 3), numero(taxaRpmBE, 0),
    campoTexto(severidadeGeral)
].join(separador);

// =======================
// 6. GRAVA CABEÇALHO POR ARQUIVO
// =======================

var ultimoArquivo = context.get("ultimoArquivo");
var cabecalhoGravado = context.get("cabecalhoGravado") || false;

if (ultimoArquivo !== msg.filename) {
    cabecalhoGravado = false;
    context.set("ultimoArquivo", msg.filename);
}

if (!cabecalhoGravado) {
    msg.payload = cabecalho + "\r\n" + linha + "\r\n";
    context.set("cabecalhoGravado", true);
} else {
    msg.payload = linha + "\r\n";
}

return msg;

// DIAGNÓSTICO OPERACIONAL - MCP BB e MCP BE
// Implementa estados operacionais, hierarquia de severidade e regras de alarme
// com base no documento de referência fornecido (estados, parâmetros de
// segurança, regras de combinação e alarmes de tendência). Os mesmos limites
// são aplicados aos dois motores (BB e BE), por decisão do operador.
//
// PENDÊNCIA: o óleo da redutora não possui mais sensor disponível após o
// remapeamento dos canais (CH4 passou a ser RPM). As regras de redutora do
// documento NÃO são avaliadas; o campo "redutora" é mantido só como indicação
// de pendência, sem dado nem alarme associado.
//
// LIMITES MARCADOS COMO "PROVISÓRIO": o documento de referência não trazia um
// valor numérico explícito para esses casos (taxa de queda de pressão, faixa de
// "rpm estável", oscilação de RPM). Ajustar conforme experiência operacional ou
// documentação do fabricante.

const RPM_PARADO = 200;
const RPM_REGIME_ESTAVEL = 700;
const RPM_FAIXA_DESACELERACAO_MAX = 500;

const PRESS_CRITICA = 3.0;        // bar
const PRESS_MIN_OPERACAO = 4.2;   // bar

const TEMP_OLEO_AQUEC_1 = 30;     // °C
const TEMP_OLEO_AQUEC_2 = 40;     // °C
const TEMP_OLEO_NORMAL_MIN = 66;  // °C
const TEMP_OLEO_NORMAL_MAX = 76;  // °C
const TEMP_OLEO_CRITICO = 85;     // °C

const TEMP_AGUA_CARGA_MIN = 45;   // °C
const TEMP_AGUA_AQUEC_MAX = 65;   // °C
const TEMP_AGUA_NORMAL_MIN = 65;  // °C
const TEMP_AGUA_NORMAL_MAX = 75;  // °C
const TEMP_AGUA_CRITICO = 85;     // °C

const TAXA_AGUA_ATENCAO = 2.0;    // °C/min
const TAXA_OLEO_ATENCAO = 1.5;    // °C/min
const TAXA_PRESSAO_QUEDA_ATENCAO = -0.3; // bar/min (PROVISÓRIO)
const TAXA_RPM_OSCILACAO = 300;   // rpm/min (PROVISÓRIO)
const RPM_ESTAVEL_TOLERANCIA = 50; // rpm/min, define "rpm estável" (PROVISÓRIO)

const NIVEIS = ["NORMAL", "INFORMATIVO", "AVISO", "ATENCAO", "ATENCAO_ALTA", "CRITICO"];

function avaliarMotor(motorNome, rpm, tempOleo, tempAgua, pressOleo, taxaOleo, taxaAgua, taxaPressao, taxaRpm) {
    let msgs = { criticos: [], atencao_alta: [], atencao: [], avisos: [], informativos: [] };
    let nivelMax = 0;

    function add(nivel, lista, texto) {
        msgs[lista].push(texto);
        if (nivel > nivelMax) nivelMax = nivel;
    }

    let rpmValido = isFinite(rpm);
    let motorParado = !rpmValido || rpm < RPM_PARADO;
    let estado;

    if (!rpmValido) {
        estado = "SEM DADOS";
        add(2, "avisos", "Falha de leitura de RPM.");
    } else if (motorParado) {
        estado = "PARADO";
        add(1, "informativos", "Motor parado. Pressão baixa não deve ser tratada como falha neste estado.");
    } else {
        // Classificação da fase operacional (independente dos alarmes abaixo)
        if (isFinite(tempOleo) && tempOleo < TEMP_OLEO_AQUEC_1) {
            estado = "AQUECIMENTO_INICIAL";
        } else if (isFinite(tempOleo) && tempOleo < TEMP_OLEO_AQUEC_2) {
            estado = "AQUECIMENTO_PROGRESSIVO";
        } else if (isFinite(tempOleo) && isFinite(tempAgua) && isFinite(pressOleo) &&
                   tempOleo >= TEMP_OLEO_NORMAL_MIN && tempOleo <= TEMP_OLEO_NORMAL_MAX &&
                   tempAgua >= TEMP_AGUA_NORMAL_MIN && tempAgua <= TEMP_AGUA_NORMAL_MAX &&
                   pressOleo >= PRESS_MIN_OPERACAO) {
            estado = "REGIME_NORMAL";
        } else if (isFinite(tempOleo) && isFinite(tempAgua) &&
                   tempOleo >= TEMP_OLEO_AQUEC_2 && tempAgua >= TEMP_AGUA_CARGA_MIN) {
            estado = "PRONTO_PARA_CARGA";
        } else {
            estado = "EM_FUNCIONAMENTO";
        }

        // ---- CRÍTICO ----
        if (isFinite(pressOleo) && pressOleo < PRESS_CRITICA) {
            let nota = (rpm < RPM_FAIXA_DESACELERACAO_MAX)
                ? " RPM em faixa de desaceleração/marcha lenta — confirmar se é transitório, mas não deixar de verificar."
                : "";
            add(5, "criticos", "Pressão do óleo abaixo de 3 bar com motor em funcionamento. Verificar imediatamente a lubrificação." + nota);
        }
        if (isFinite(pressOleo) && rpm >= RPM_REGIME_ESTAVEL && pressOleo < PRESS_MIN_OPERACAO) {
            add(5, "criticos", "Pressão do óleo abaixo da referência mínima (4,2 bar) em regime de operação estabilizado (RPM ≥ 700). Verificação imediata recomendada.");
        }
        if (isFinite(tempOleo) && isFinite(pressOleo) && tempOleo > TEMP_OLEO_NORMAL_MAX && pressOleo < PRESS_MIN_OPERACAO) {
            add(5, "criticos", "Óleo quente associado a pressão baixa. Verificar lubrificação, viscosidade, bomba e possíveis vazamentos.");
        }
        if (isFinite(tempOleo) && tempOleo > TEMP_OLEO_CRITICO) {
            add(5, "criticos", "Temperatura do óleo em condição crítica (> 85 °C). Reduzir carga e verificar lubrificação/resfriamento.");
        }
        if (isFinite(tempAgua) && tempAgua > TEMP_AGUA_CRITICO) {
            add(5, "criticos", "Temperatura da água doce em condição crítica (> 85 °C). Verificar circulação, bombas e trocadores.");
        }

        // ---- ATENÇÃO ALTA ----
        if (isFinite(tempAgua) && isFinite(tempOleo) && tempAgua > TEMP_AGUA_NORMAL_MAX && tempOleo > TEMP_OLEO_NORMAL_MAX) {
            add(4, "atencao_alta", "Água e óleo acima das faixas normais. Possível deficiência térmica geral.");
        }
        if (isFinite(taxaOleo) && taxaOleo > 0 && isFinite(taxaPressao) && taxaPressao < 0) {
            add(4, "atencao_alta", "Temperatura do óleo subindo enquanto a pressão cai. Possível perda de viscosidade ou deficiência de lubrificação.");
        }

        // ---- ATENÇÃO ----
        if (isFinite(tempOleo) && tempOleo > TEMP_OLEO_NORMAL_MAX) {
            add(3, "atencao", "Temperatura do óleo acima da faixa normal de referência (> 76 °C).");
        }
        if (isFinite(tempAgua) && tempAgua > TEMP_AGUA_NORMAL_MAX) {
            add(3, "atencao", "Temperatura da água doce acima da faixa recomendada (> 75 °C).");
        }
        if (isFinite(pressOleo) && pressOleo >= PRESS_CRITICA && pressOleo < PRESS_MIN_OPERACAO) {
            add(3, "atencao", "Pressão do óleo abaixo da referência mínima operacional de 4,2 bar.");
        }
        if (isFinite(tempAgua) && isFinite(tempOleo) && tempAgua >= TEMP_AGUA_NORMAL_MIN && tempAgua <= TEMP_AGUA_NORMAL_MAX && tempOleo > TEMP_OLEO_NORMAL_MAX) {
            add(3, "atencao", "Água em faixa normal, porém óleo acima da referência. Verificar sistema de lubrificação e o ponto de medição do sensor.");
        }
        if (isFinite(taxaAgua) && taxaAgua > TAXA_AGUA_ATENCAO) {
            add(3, "atencao", "Temperatura da água subindo rapidamente (" + taxaAgua.toFixed(2) + " °C/min).");
        }
        if (isFinite(taxaOleo) && taxaOleo > TAXA_OLEO_ATENCAO) {
            add(3, "atencao", "Temperatura do óleo subindo rapidamente (" + taxaOleo.toFixed(2) + " °C/min).");
        }
        if (isFinite(taxaPressao) && isFinite(taxaRpm) && taxaPressao < TAXA_PRESSAO_QUEDA_ATENCAO && Math.abs(taxaRpm) < RPM_ESTAVEL_TOLERANCIA) {
            add(3, "atencao", "Pressão do óleo em tendência de queda (" + taxaPressao.toFixed(2) + " bar/min) com RPM estável. Possível perda de lubrificação, aquecimento do óleo, desgaste ou vazamento.");
        }
        if (isFinite(taxaAgua) && taxaAgua > 0 && rpm < RPM_FAIXA_DESACELERACAO_MAX) {
            add(3, "atencao", "Temperatura da água subindo mesmo com baixa rotação. Possível falha de circulação/resfriamento.");
        }
        if (isFinite(taxaRpm) && Math.abs(taxaRpm) > TAXA_RPM_OSCILACAO) {
            add(3, "atencao", "Oscilação de rotação detectada (variação de " + taxaRpm.toFixed(0) + " rpm/min). Verificar regime de operação ou sinal do sensor.");
        }

        // ---- AVISO ----
        if (isFinite(tempOleo) && tempOleo < TEMP_OLEO_AQUEC_1) {
            add(2, "avisos", "Óleo lubrificante abaixo de 30 °C. Manter aquecimento e evitar carga.");
        } else if (isFinite(tempOleo) && tempOleo < TEMP_OLEO_AQUEC_2) {
            add(2, "avisos", "Óleo entre 30 °C e 40 °C. Aplicar carga de forma progressiva.");
        }
        if (isFinite(tempAgua) && tempAgua < TEMP_AGUA_CARGA_MIN) {
            add(2, "avisos", "Água de resfriamento abaixo de 45 °C. Evitar carga elevada.");
        }

        // ---- INFORMATIVO ----
        if (isFinite(tempAgua) && tempAgua >= TEMP_AGUA_CARGA_MIN && tempAgua < TEMP_AGUA_AQUEC_MAX) {
            add(1, "informativos", "Água doce ainda em fase de aquecimento.");
        }
    }

    return {
        motor: motorNome,
        estado: estado,
        severidade: NIVEIS[nivelMax],
        rpm: rpm,
        temp_oleo_c: tempOleo,
        temp_agua_c: tempAgua,
        press_oleo_bar: pressOleo,
        taxa_oleo_c_min: taxaOleo,
        taxa_agua_c_min: taxaAgua,
        taxa_pressao_bar_min: taxaPressao,
        taxa_rpm_min: taxaRpm,
        redutora: {
            status: "PENDENTE",
            mensagem: "Sem sensor disponível após o remapeamento dos canais. Monitoramento pendente de novo hardware/canal."
        },
        criticos: msgs.criticos,
        atencao_alta: msgs.atencao_alta,
        atencao: msgs.atencao,
        avisos: msgs.avisos,
        informativos: msgs.informativos
    };
}

