// PROGNÓSTICO - REGRESSÃO LINEAR (TEMPO ATÉ LIMITE)
// Janela deslizante por parâmetro/motor, projeção via mínimos quadrados.
// Disparar com um inject independente (recomendado: a cada 15s).
//
// CALIBRAÇÃO v2 (com base em backtest sobre dados reais de 19-21/06 e 30/06):
// 1) GATE POR ESTADO ATUAL: só projeta quando o valor já está na zona de
//    atenção. Isso elimina o falso alarme massivo observado durante o
//    aquecimento normal de partida fria (24°C -> ~78°C em ~1h tem R² alto,
//    mas é convergência para o regime normal, não tendência de falha).
// 2) TETO DE CONFIANÇA NO ETA: o backtest mostrou que projeções de longo
//    prazo (eta > 60 min) subestimam a urgência real em até ~2,5x. Acima de
//    60 min, o eta_min numérico ainda é calculado (útil para log/CSV), mas
//    é marcado com confianca:"baixa" para o node de Advisory não prometer
//    um horário exato.

const JANELA_MAX = 20;       // nº de amostras na janela (20 x 15s = 5 min)
const R2_MINIMO = 0.55;      // abaixo disso, não há tendência confiável o suficiente
const ETA_MAX_MIN = 240;     // não projeta além de 4h (extrapolação perde sentido)
const ETA_BAIXA_CONFIANCA_MIN = 60; // acima disso, eta numérico é só indicativo

// Limites de referência (mesmos do node de Diagnóstico)
const LIMITES = {
    temp_oleo: { critico: 85, direcao: "subindo" },
    temp_agua: { critico: 85, direcao: "subindo" },
    pressao:   { critico: 3.0, direcao: "descendo", min_operacao: 4.2 }
};

// Gate por estado atual: só entra em "modo prognóstico" quando já está
// na zona de atenção (mesmos limiares do node de Diagnóstico Operacional).
const GATE = {
    temp_oleo: function (v) { return isFinite(v) && v >= 76; },             // TEMP_OLEO_NORMAL_MAX
    temp_agua: function (v) { return isFinite(v) && v >= 75; },             // TEMP_AGUA_NORMAL_MAX
    pressao_critica: function (v) { return isFinite(v) && v < 4.2; },       // já abaixo de PRESS_MIN_OPERACAO
    pressao_min_operacao: function (v) { return isFinite(v) && v < 4.6; }   // aproximando-se de PRESS_MIN_OPERACAO
};

function regressaoLinear(pontos) {
    // pontos: [{t, v}], t em minutos relativos, v = valor
    const n = pontos.length;
    if (n < 4) return null;

    let somaT = 0, somaV = 0, somaTV = 0, somaT2 = 0;
    for (const p of pontos) {
        somaT += p.t;
        somaV += p.v;
        somaTV += p.t * p.v;
        somaT2 += p.t * p.t;
    }

    const mediaT = somaT / n;
    const mediaV = somaV / n;
    const denom = somaT2 - n * mediaT * mediaT;
    if (Math.abs(denom) < 1e-9) return null;

    const slope = (somaTV - n * mediaT * mediaV) / denom;
    const intercept = mediaV - slope * mediaT;

    // R²
    let ssTot = 0, ssRes = 0;
    for (const p of pontos) {
        const pred = slope * p.t + intercept;
        ssRes += Math.pow(p.v - pred, 2);
        ssTot += Math.pow(p.v - mediaV, 2);
    }
    const r2 = ssTot < 1e-9 ? 0 : 1 - (ssRes / ssTot);

    return { slope, intercept, r2 };
}

function atualizarJanela(chaveContexto, valorAtual) {
    if (!isFinite(valorAtual)) return context.get(chaveContexto) || [];

    let janela = context.get(chaveContexto) || [];
    const agora = Date.now();

    janela.push({ t: agora, v: valorAtual });
    if (janela.length > JANELA_MAX) janela.shift();

    context.set(chaveContexto, janela);
    return janela;
}

function projetar(janelaBruta, limiteCfg) {
    if (!limiteCfg || janelaBruta.length < 4) {
        return { eta_min: null, confiavel: false, motivo: "amostras insuficientes" };
    }

    const t0 = janelaBruta[0].t;
    const pontos = janelaBruta.map(p => ({ t: (p.t - t0) / 60000, v: p.v })); // minutos
    const reg = regressaoLinear(pontos);

    if (!reg) {
        return { eta_min: null, confiavel: false, motivo: "regressão indisponível" };
    }

    if (reg.r2 < R2_MINIMO) {
        return { eta_min: null, confiavel: false, motivo: "tendência ruidosa (R²=" + reg.r2.toFixed(2) + ")" };
    }

    const valorAtual = pontos[pontos.length - 1].v;
    const subindo = limiteCfg.direcao === "subindo";

    // Sem tendência relevante na direção de risco
    if (subindo && reg.slope <= 0.001) {
        return { eta_min: null, confiavel: true, motivo: "estável ou em queda" };
    }
    if (!subindo && reg.slope >= -0.001) {
        return { eta_min: null, confiavel: true, motivo: "estável ou em alta" };
    }

    const alvo = limiteCfg.critico;
    const etaMin = (alvo - valorAtual) / reg.slope; // minutos a partir de agora

    if (etaMin < 0 || etaMin > ETA_MAX_MIN) {
        return { eta_min: null, confiavel: true, motivo: "fora da janela de projeção (>4h ou já passou)" };
    }

    return {
        eta_min: Number(etaMin.toFixed(1)),
        confiavel: true,
        confianca: etaMin > ETA_BAIXA_CONFIANCA_MIN ? "baixa" : "alta",
        r2: Number(reg.r2.toFixed(2)),
        taxa_atual: Number(reg.slope.toFixed(4)) // unidade/min
    };
}

function projetarComGate(janela, cfg, gateFn, valorAtual) {
    // Mantém a janela sempre atualizada (já feito antes de chamar esta função),
    // mas só calcula/retorna projeção quando o estado atual já está na zona
    // de atenção. Fora da zona de atenção, não há sentido em prognosticar
    // (ver nota de calibração v2 no topo do arquivo).
    if (!gateFn(valorAtual)) {
        return { eta_min: null, confiavel: true, motivo: "fora da zona de atenção (sem necessidade de prognóstico)" };
    }
    return projetar(janela, cfg);
}

function processarMotor(prefixo, tempOleo, tempAgua, pressao) {
    const jOleo = atualizarJanela("jan_" + prefixo + "_oleo", tempOleo);
    const jAgua = atualizarJanela("jan_" + prefixo + "_agua", tempAgua);
    const jPressao = atualizarJanela("jan_" + prefixo + "_pressao", pressao);

    return {
        temp_oleo: projetarComGate(jOleo, LIMITES.temp_oleo, GATE.temp_oleo, tempOleo),
        temp_agua: projetarComGate(jAgua, LIMITES.temp_agua, GATE.temp_agua, tempAgua),
        pressao_critica: projetarComGate(jPressao, LIMITES.pressao, GATE.pressao_critica, pressao),
        pressao_min_operacao: projetarComGate(
            jPressao,
            { critico: LIMITES.pressao.min_operacao, direcao: "descendo" },
            GATE.pressao_min_operacao,
            pressao
        )
    };
}

const prognosticoBB = processarMotor(
    "bb",
    Number(global.get("ch1")),
    Number(global.get("ch2")),
    Number(global.get("ch3"))
);

const prognosticoBE = processarMotor(
    "be",
    Number(global.get("ch5")),
    Number(global.get("ch6")),
    Number(global.get("ch7"))
);

global.set("prognostico_mcp_bb", prognosticoBB);
global.set("prognostico_mcp_be", prognosticoBE);

msg.payload = {
    timestamp: new Date().toISOString(),
    bb: prognosticoBB,
    be: prognosticoBE
};

return msg;

// GERAÇÃO DE RECOMENDAÇÃO DE MANUTENÇÃO (ADVISORY)
// Cruza Diagnóstico (estado atual) + Prognóstico (tendência) em uma recomendação acionável.
//
// CALIBRAÇÃO v2: o node de Prognóstico agora só projeta quando o estado
// atual já está na zona de atenção (gate), e marca eta_min > 60 min como
// confianca:"baixa" (backtest mostrou subestimação de até ~2,5x em
// projeções de longo prazo). Por isso, eta_min > 60 min nunca promete um
// horário exato — vira "MONITORAR_TENDENCIA" em vez de "PROGRAMAR".

const URGENCIA_ORDEM = ["NORMAL", "MONITORAR", "MONITORAR_TENDENCIA", "URGENTE", "IMEDIATA"];

function classificarUrgenciaPorEta(etaInfo) {
    if (!etaInfo || !etaInfo.confiavel || etaInfo.eta_min === null) return "NORMAL";
    if (etaInfo.eta_min <= 30) return "IMEDIATA";
    if (etaInfo.eta_min <= 60) return "URGENTE";
    return "MONITORAR_TENDENCIA"; // eta_min > 60 min, já gateado pela zona de atenção, mas de baixa confiança numérica
}

function maiorUrgencia(a, b) {
    return URGENCIA_ORDEM.indexOf(a) >= URGENCIA_ORDEM.indexOf(b) ? a : b;
}

function gerarRecomendacaoMotor(nomeMotor, diag, prog) {
    let urgencia = "NORMAL";
    let motivos = [];

    if (diag.severidade === "CRITICO") {
        urgencia = "IMEDIATA";
        motivos.push("Estado atual já é CRÍTICO: " + ((diag.criticos && diag.criticos[0]) || "ver diagnóstico."));
    } else if (diag.severidade === "ATENCAO_ALTA") {
        urgencia = maiorUrgencia(urgencia, "URGENTE");
        motivos.push("Estado atual em ATENÇÃO ALTA.");
    }

    const parametros = [
        { label: "Temp. óleo", info: prog.temp_oleo },
        { label: "Temp. água", info: prog.temp_agua },
        { label: "Pressão (crítica)", info: prog.pressao_critica },
        { label: "Pressão (mín. operação)", info: prog.pressao_min_operacao }
    ];

    for (const p of parametros) {
        if (!p.info) continue;
        const u = classificarUrgenciaPorEta(p.info);
        if (u !== "NORMAL") {
            urgencia = maiorUrgencia(urgencia, u);
            const sufixoConfianca = p.info.confianca === "baixa"
                ? " (horário aproximado, baixa confiança numérica — tendência confirmada, mas pode chegar mais rápido)"
                : "";
            motivos.push(
                p.label + ": projeção de atingir limite em ~" + p.info.eta_min +
                " min (taxa atual " + p.info.taxa_atual + "/min, R²=" + p.info.r2 + ")." + sufixoConfianca
            );
        }
    }

    if (motivos.length === 0) {
        motivos.push("Sem tendência de risco identificada. Operação dentro do esperado.");
    }

    const acaoSugerida = {
        IMEDIATA: "Intervenção imediata — reduzir carga/parar se necessário e inspecionar lubrificação/refrigeração.",
        URGENTE: "Programar inspeção nos próximos 60 minutos. Acompanhar de perto a tendência.",
        MONITORAR_TENDENCIA: "Tendência de aproximação ao limite confirmada, mas sem horário exato confiável. Aumentar frequência de monitoramento e providenciar inspeção na próxima oportunidade segura.",
        MONITORAR: "Sem ação imediata. Manter monitoramento de rotina.",
        NORMAL: "Nenhuma ação requerida."
    }[urgencia];

    return {
        motor: nomeMotor,
        urgencia: urgencia,
        acao_sugerida: acaoSugerida,
        motivos: motivos,
        estado_atual: diag.estado || "",
        severidade_atual: diag.severidade || ""
    };
}

const diagBB = global.get("diagnostico_mcp_bb") || {};
const diagBE = global.get("diagnostico_mcp_be") || {};
const progBB = global.get("prognostico_mcp_bb") || {};
const progBE = global.get("prognostico_mcp_be") || {};

const recBB = gerarRecomendacaoMotor("MCP BB", diagBB, progBB);
const recBE = gerarRecomendacaoMotor("MCP BE", diagBE, progBE);

const urgenciaGeral = maiorUrgencia(recBB.urgencia, recBE.urgencia);

const recomendacaoGeral = {
    timestamp: new Date().toISOString(),
    urgencia_geral: urgenciaGeral,
    bb: recBB,
    be: recBE
};

global.set("recomendacao_manutencao", recomendacaoGeral);

msg.payload = recomendacaoGeral;
return msg;

// GRAVAÇÃO CSV - RECOMENDAÇÕES DE MANUTENÇÃO
// Mesmo padrão do node "Gravação CSV histórico - BB/BE"

function doisDigitos(n) { return n < 10 ? "0" + n : "" + n; }

var agora = new Date();
var nomeArquivo = "C:\\Dados_Motor\\recomendacoes_manutencao_" +
    agora.getFullYear() + "-" + doisDigitos(agora.getMonth() + 1) + "-" + doisDigitos(agora.getDate()) + ".csv";

msg.filename = nomeArquivo;

var rec = msg.payload; // vindo do node "Geração de Recomendação de Manutenção (Advisory)"

function campoTexto(v) { return '"' + String(v).replace(/"/g, '""') + '"'; }

var cabecalho = ["DataHora", "UrgenciaGeral", "Motor", "UrgenciaMotor", "EstadoAtual", "SeveridadeAtual", "AcaoSugerida", "Motivos"].join(";");

function linhaMotor(recObj, motorObj) {
    return [
        campoTexto(recObj.timestamp),
        campoTexto(recObj.urgencia_geral),
        campoTexto(motorObj.motor),
        campoTexto(motorObj.urgencia),
        campoTexto(motorObj.estado_atual),
        campoTexto(motorObj.severidade_atual),
        campoTexto(motorObj.acao_sugerida),
        campoTexto(motorObj.motivos.join(" | "))
    ].join(";");
}

var linhas = linhaMotor(rec, rec.bb) + "\r\n" + linhaMotor(rec, rec.be) + "\r\n";

var ultimoArquivo = context.get("ultimoArquivoRec");
var cabecalhoGravado = context.get("cabecalhoGravadoRec") || false;

if (ultimoArquivo !== msg.filename) {
    cabecalhoGravado = false;
    context.set("ultimoArquivoRec", msg.filename);
}

if (!cabecalhoGravado) {
    msg.payload = cabecalho + "\r\n" + linhas;
    context.set("cabecalhoGravadoRec", true);
} else {
    msg.payload = linhas;
}

return msg;

/* ============================================================
   NEREUS - AQUISIÇÃO, LINEARIZAÇÃO E FILTRO EMA
   Versão v5 - adaptada para leitura Modbus a cada 5 s
   ------------------------------------------------------------
   MUDANÇAS EM RELAÇÃO À v4:
   1) O carimbo de tempo da comunicação passou a ser gravado NA
      ENTRADA da função (toda leitura Modbus válida), e não mais
      só quando o ciclo de média fecha. Antes, com leitura a cada
      5 s e média de 3 amostras, o "ultima_leitura_ms" só era
      atualizado a cada 15 s e o monitor de comunicação acusava
      instabilidade permanente.
   2) AMOSTRAS_MEDIA passou de 3 para 1. Com período de 5 s, a
      média de 3 introduzia 15 s de atraso no gauge. A suavização
      necessária é obtida apenas pelo EMA, com alpha recalibrado.
   3) Alphas reduzidos: em amostragem mais lenta cada amostra pesa
      mais, então alpha menor mantém a mesma constante de tempo.
   4) Contador de leituras válidas para diagnóstico do enlace.

   Se voltar a ler a cada 1 s, use AMOSTRAS_MEDIA = 3 e os alphas
   antigos (0.15 / 0.25 / 0.35).

   MAPEAMENTO DE CANAIS
   CH1 = Temp. óleo lubrificante MCP BB
   CH2 = Temp. água doce MCP BB
   CH3 = Pressão óleo lubrificante MCP BB
   CH4 = Rotação (RPM) MCP BB
   CH5 = Temp. óleo lubrificante MCP BE
   CH6 = Temp. água doce MCP BE
   CH7 = Pressão óleo lubrificante MCP BE
   CH8 = Rotação (RPM) MCP BE
   ============================================================ */

var versaoCodigo = "linearizacao_motor_v5_5s";
var AMOSTRAS_MEDIA = 1;

var listaCanais = msg.payload;

if (!Array.isArray(listaCanais) || listaCanais.length < 8) {
    global.set("modbus_leituras_invalidas", (global.get("modbus_leituras_invalidas") || 0) + 1);
    return null;
}

// -------- carimbo de comunicação: toda leitura válida do escravo --------
global.set("ultima_leitura_ms", Date.now());
global.set("ultima_leitura_valida", new Date().toISOString());
global.set("modbus_leituras_ok", (global.get("modbus_leituras_ok") || 0) + 1);

if (context.get("versaoCodigo") !== versaoCodigo) {
    context.set("amostras", 0);
    context.set("soma", [0, 0, 0, 0, 0, 0, 0, 0]);
    context.set("ema", null);
    context.set("versaoCodigo", versaoCodigo);
}

var canais = [
    { nome: "ch1", descricao: "Temp Óleo Lub. BB",   divisor: 100, x1: 0, y1: 0, x2: 10, y2: 120,  unidade: "°C",  alpha: 0.30, deadband: 0.20 },
    { nome: "ch2", descricao: "Temp Água Doce BB",   divisor: 100, x1: 0, y1: 0, x2: 10, y2: 120,  unidade: "°C",  alpha: 0.30, deadband: 0.20 },
    { nome: "ch3", descricao: "Pressão Óleo Lub. BB",divisor: 100, x1: 0, y1: 0, x2: 10, y2: 10,   unidade: "bar", alpha: 0.40, deadband: 0.03 },
    { nome: "ch4", descricao: "Rotação MCP BB",      divisor: 100, x1: 0, y1: 0, x2: 10, y2: 2000, unidade: "RPM", alpha: 0.55, deadband: 5    },
    { nome: "ch5", descricao: "Temp Óleo Lub. BE",   divisor: 100, x1: 0, y1: 0, x2: 10, y2: 120,  unidade: "°C",  alpha: 0.30, deadband: 0.20 },
    { nome: "ch6", descricao: "Temp Água Doce BE",   divisor: 100, x1: 0, y1: 0, x2: 10, y2: 120,  unidade: "°C",  alpha: 0.30, deadband: 0.20 },
    { nome: "ch7", descricao: "Pressão Óleo Lub. BE",divisor: 100, x1: 0, y1: 0, x2: 10, y2: 10,   unidade: "bar", alpha: 0.40, deadband: 0.03 },
    { nome: "ch8", descricao: "Rotação MCP BE",      divisor: 100, x1: 0, y1: 0, x2: 10, y2: 2000, unidade: "RPM", alpha: 0.55, deadband: 5    }
];

function linearizar(valorLido, cfg) {
    var a = (cfg.y2 - cfg.y1) / (cfg.x2 - cfg.x1);
    var b = cfg.y1 - (a * cfg.x1);
    return (a * valorLido) + b;
}

function limitar(valor, minimo, maximo) {
    if (valor < minimo) return minimo;
    if (valor > maximo) return maximo;
    return valor;
}

var amostras = context.get("amostras") || 0;
var soma = context.get("soma") || [0, 0, 0, 0, 0, 0, 0, 0];

for (var i = 0; i < 8; i++) {
    var cfg = canais[i];

    var bruto = Number(listaCanais[i]) || 0;
    var tensao = bruto / cfg.divisor;

    var valorLinearizado = linearizar(tensao, cfg);
    var valorLimitado = limitar(valorLinearizado, cfg.y1, cfg.y2);

    global.set(cfg.nome + "_bruto", bruto);
    global.set(cfg.nome + "_tensao", Number(tensao.toFixed(2)));
    global.set(cfg.nome + "_sem_filtro", Number(valorLimitado.toFixed(2)));

    soma[i] += valorLimitado;
}

amostras++;

if (amostras < AMOSTRAS_MEDIA) {
    context.set("amostras", amostras);
    context.set("soma", soma);
    return null;
}

var medias = [];
for (var j = 0; j < 8; j++) {
    medias[j] = soma[j] / AMOSTRAS_MEDIA;
}

context.set("amostras", 0);
context.set("soma", [0, 0, 0, 0, 0, 0, 0, 0]);

var ema = context.get("ema");
if (!Array.isArray(ema) || ema.length < 8) {
    ema = medias.slice();
}

var filtrados = [];

for (var k = 0; k < 8; k++) {
    var cfgFiltro = canais[k];

    var valorAtual = medias[k];
    var valorAnterior = ema[k];

    var valorFiltrado = (cfgFiltro.alpha * valorAtual) + ((1 - cfgFiltro.alpha) * valorAnterior);

    if (Math.abs(valorFiltrado - valorAnterior) < cfgFiltro.deadband) {
        valorFiltrado = valorAnterior;
    }

    valorFiltrado = limitar(valorFiltrado, cfgFiltro.y1, cfgFiltro.y2);

    filtrados[k] = Number(valorFiltrado.toFixed(2));
    ema[k] = valorFiltrado;

    global.set("ch" + (k + 1), filtrados[k]);
    global.set("ch" + (k + 1) + "_media", Number(valorAtual.toFixed(2)));
    global.set("ch" + (k + 1) + "_filtrado", filtrados[k]);
}

context.set("ema", ema);

// carimbo do dado processado (usado para saber se o gauge está fresco)
global.set("ultimo_processamento_ms", Date.now());

return [
    { payload: filtrados[0] },
    { payload: filtrados[1] },
    { payload: filtrados[2] },
    { payload: filtrados[3] },
    { payload: filtrados[4] },
    { payload: filtrados[5] },
    { payload: filtrados[6] },
    { payload: filtrados[7] }
];

/* Registro de falhas do nó Modbus (segunda saída).
   Alimenta os contadores mostrados no card de comunicação. */

let n = (global.get("modbus_erros") || 0) + 1;
global.set("modbus_erros", n);

let texto = "";
if (msg && msg.error && msg.error.message) {
    texto = String(msg.error.message);
} else if (msg && typeof msg.payload === "string") {
    texto = msg.payload;
} else if (msg && msg.payload) {
    texto = JSON.stringify(msg.payload).slice(0, 160);
} else {
    texto = "falha sem descrição";
}

global.set("modbus_ultimo_erro", new Date().toLocaleTimeString("pt-BR") + " · " + texto);
global.set("modbus_ultimo_erro_ms", Date.now());

node.status({ fill: "red", shape: "ring", text: "erros: " + n });

return null;

/* ============================================================
   NEREUS - SUPERVISÃO DO ENLACE MODBUS
   Versão v2
   ------------------------------------------------------------
   Os limiares agora derivam do período de leitura configurado no
   nó Modbus. Com PERIODO_LEITURA_S = 5:
       NORMAL     : até 12 s sem leitura  (2 ciclos + folga)
       INSTAVEL   : de 12 s até 22 s      (4 ciclos + folga)
       FALHA      : acima de 22 s

   Se alterar o "Poll Rate" do nó Modbus, altere apenas a
   constante PERIODO_LEITURA_S abaixo.

   Histerese: o status só muda depois de CICLOS_CONFIRMACAO
   avaliações consecutivas no mesmo estado. Isso evita o efeito
   de pisca-pisca no alarme visual quando o tempo fica na
   fronteira entre duas faixas.
   ============================================================ */

const PERIODO_LEITURA_S = 5;
const CICLOS_CONFIRMACAO = 2;

const TOL_NORMAL = (PERIODO_LEITURA_S * 2) + 2;
const TOL_INSTAVEL = (PERIODO_LEITURA_S * 4) + 2;

let ultima = global.get("ultima_leitura_ms");
let agora = Date.now();

let statusBruto = "SEM DADOS";
let nivel = 3;               // 0 normal | 1 instável | 2 falha | 3 sem dados
let segundosSemLeitura = null;

if (ultima !== undefined && ultima !== null) {
    segundosSemLeitura = (agora - ultima) / 1000;

    if (segundosSemLeitura <= TOL_NORMAL) {
        statusBruto = "COMUNICAÇÃO NORMAL";
        nivel = 0;
    } else if (segundosSemLeitura <= TOL_INSTAVEL) {
        statusBruto = "COMUNICAÇÃO INSTÁVEL";
        nivel = 1;
    } else {
        statusBruto = "FALHA DE COMUNICAÇÃO";
        nivel = 2;
    }
}

// -------- histerese --------
let statusConfirmado = context.get("statusConfirmado") || statusBruto;
let nivelConfirmado = context.get("nivelConfirmado");
if (nivelConfirmado === undefined) nivelConfirmado = nivel;

let candidato = context.get("candidato");
let contagem = context.get("contagem") || 0;

if (statusBruto === statusConfirmado) {
    candidato = null;
    contagem = 0;
} else if (statusBruto === candidato) {
    contagem++;
    if (contagem >= CICLOS_CONFIRMACAO) {
        statusConfirmado = statusBruto;
        nivelConfirmado = nivel;
        candidato = null;
        contagem = 0;
    }
} else {
    candidato = statusBruto;
    contagem = 1;
}

context.set("statusConfirmado", statusConfirmado);
context.set("nivelConfirmado", nivelConfirmado);
context.set("candidato", candidato);
context.set("contagem", contagem);

// -------- marca de início e fim de indisponibilidade --------
let inicioFalha = context.get("inicioFalha") || null;
if (nivelConfirmado >= 1 && inicioFalha === null) {
    inicioFalha = agora;
} else if (nivelConfirmado === 0) {
    inicioFalha = null;
}
context.set("inicioFalha", inicioFalha);

let ocorrencias = context.get("ocorrencias") || 0;
if (nivelConfirmado >= 1 && context.get("nivelAnterior") === 0) {
    ocorrencias++;
}
context.set("ocorrencias", ocorrencias);
context.set("nivelAnterior", nivelConfirmado);

let payload = {
    status_comunicacao: statusConfirmado,
    nivel: nivelConfirmado,
    alarme: nivelConfirmado >= 1,
    segundos_sem_leitura: segundosSemLeitura !== null ? Number(segundosSemLeitura.toFixed(1)) : null,
    ultima_leitura: global.get("ultima_leitura_valida") || "—",
    periodo_esperado_s: PERIODO_LEITURA_S,
    limite_normal_s: TOL_NORMAL,
    limite_instavel_s: TOL_INSTAVEL,
    leituras_ok: global.get("modbus_leituras_ok") || 0,
    erros_modbus: global.get("modbus_erros") || 0,
    ultimo_erro: global.get("modbus_ultimo_erro") || "—",
    ocorrencias_hoje: ocorrencias,
    indisponivel_ha_s: inicioFalha ? Number(((agora - inicioFalha) / 1000).toFixed(0)) : 0,
    porta: "COM4 · 9600 8N1 · escravo 1"
};

global.set("status_comunicacao", payload);

msg.payload = payload;
return msg;

// TAXA DE VARIAÇÃO - TÉRMICA, PRESSÃO E RPM - MCP BB e MCP BE
// Resultado em unidade/min (°C/min, bar/min, rpm/min)

let agora = Date.now();

let tempOleoBB = Number(global.get("ch1"));
let tempAguaBB = Number(global.get("ch2"));
let pressaoBB  = Number(global.get("ch3"));
let rpmBB      = Number(global.get("ch4"));

let tempOleoBE = Number(global.get("ch5"));
let tempAguaBE = Number(global.get("ch6"));
let pressaoBE  = Number(global.get("ch7"));
let rpmBE      = Number(global.get("ch8"));

let anterior = context.get("anterior") || {};
let tempoAnterior = context.get("tempoAnterior");

let saida = {
    timestamp: new Date().toISOString(),
    taxa_temp_oleo_bb_c_min: 0,
    taxa_temp_agua_bb_c_min: 0,
    taxa_pressao_oleo_bb_bar_min: 0,
    taxa_rpm_bb_rpm_min: 0,
    taxa_temp_oleo_be_c_min: 0,
    taxa_temp_agua_be_c_min: 0,
    taxa_pressao_oleo_be_bar_min: 0,
    taxa_rpm_be_rpm_min: 0
};

if (tempoAnterior !== undefined) {
    let deltaMin = (agora - tempoAnterior) / 60000;

    if (deltaMin > 0 && deltaMin < 5) {
        if (isFinite(tempOleoBB) && isFinite(anterior.tempOleoBB)) {
            saida.taxa_temp_oleo_bb_c_min = Number(((tempOleoBB - anterior.tempOleoBB) / deltaMin).toFixed(2));
        }
        if (isFinite(tempAguaBB) && isFinite(anterior.tempAguaBB)) {
            saida.taxa_temp_agua_bb_c_min = Number(((tempAguaBB - anterior.tempAguaBB) / deltaMin).toFixed(2));
        }
        if (isFinite(pressaoBB) && isFinite(anterior.pressaoBB)) {
            saida.taxa_pressao_oleo_bb_bar_min = Number(((pressaoBB - anterior.pressaoBB) / deltaMin).toFixed(3));
        }
        if (isFinite(rpmBB) && isFinite(anterior.rpmBB)) {
            saida.taxa_rpm_bb_rpm_min = Number(((rpmBB - anterior.rpmBB) / deltaMin).toFixed(0));
        }

        if (isFinite(tempOleoBE) && isFinite(anterior.tempOleoBE)) {
            saida.taxa_temp_oleo_be_c_min = Number(((tempOleoBE - anterior.tempOleoBE) / deltaMin).toFixed(2));
        }
        if (isFinite(tempAguaBE) && isFinite(anterior.tempAguaBE)) {
            saida.taxa_temp_agua_be_c_min = Number(((tempAguaBE - anterior.tempAguaBE) / deltaMin).toFixed(2));
        }
        if (isFinite(pressaoBE) && isFinite(anterior.pressaoBE)) {
            saida.taxa_pressao_oleo_be_bar_min = Number(((pressaoBE - anterior.pressaoBE) / deltaMin).toFixed(3));
        }
        if (isFinite(rpmBE) && isFinite(anterior.rpmBE)) {
            saida.taxa_rpm_be_rpm_min = Number(((rpmBE - anterior.rpmBE) / deltaMin).toFixed(0));
        }
    }
}

context.set("anterior", {
    tempOleoBB: tempOleoBB, tempAguaBB: tempAguaBB, pressaoBB: pressaoBB, rpmBB: rpmBB,
    tempOleoBE: tempOleoBE, tempAguaBE: tempAguaBE, pressaoBE: pressaoBE, rpmBE: rpmBE
});

context.set("tempoAnterior", agora);

global.set("taxa_temp_oleo_bb_c_min", saida.taxa_temp_oleo_bb_c_min);
global.set("taxa_temp_agua_bb_c_min", saida.taxa_temp_agua_bb_c_min);
global.set("taxa_pressao_oleo_bb_bar_min", saida.taxa_pressao_oleo_bb_bar_min);
global.set("taxa_rpm_bb_rpm_min", saida.taxa_rpm_bb_rpm_min);

global.set("taxa_temp_oleo_be_c_min", saida.taxa_temp_oleo_be_c_min);
global.set("taxa_temp_agua_be_c_min", saida.taxa_temp_agua_be_c_min);
global.set("taxa_pressao_oleo_be_bar_min", saida.taxa_pressao_oleo_be_bar_min);
global.set("taxa_rpm_be_rpm_min", saida.taxa_rpm_be_rpm_min);

msg.payload = saida;
return msg;

/* HORÍMETRO - MCP BB (CH4) e MCP BE (CH8), com base em RPM >= 200

   OBSERVAÇÃO: o acumulado fica no context em memória e zera a cada
   deploy ou reinício do Node-RED. Para que o horímetro sirva de base
   ao controle de manutenção (horas desde a última troca de óleo),
   é preciso habilitar contextStorage no settings.js e trocar
   context.set(x, y) por context.set(x, y, "file"). Ver o guia de
   instalação que acompanha esta versão. */

const RPM_PARADO = 200;

let rpmBB = Number(global.get("ch4"));
let rpmBE = Number(global.get("ch8"));

let motorBBLigado = isFinite(rpmBB) && rpmBB >= RPM_PARADO;
let motorBELigado = isFinite(rpmBE) && rpmBE >= RPM_PARADO;

let agora = Date.now();
let ultimoTempo = context.get("ultimoTempo");

let segundosBB = context.get("segundosBB") || 0;
let segundosBE = context.get("segundosBE") || 0;

if (ultimoTempo !== undefined) {
    let deltaSegundos = (agora - ultimoTempo) / 1000;

    if (deltaSegundos > 0 && deltaSegundos < 60) {
        if (motorBBLigado) { segundosBB += deltaSegundos; }
        if (motorBELigado) { segundosBE += deltaSegundos; }
    }
}

context.set("ultimoTempo", agora);
context.set("segundosBB", segundosBB);
context.set("segundosBE", segundosBE);

let horasBB = Number((segundosBB / 3600).toFixed(2));
let horasBE = Number((segundosBE / 3600).toFixed(2));

global.set("horimetro_mcp_bb_h", horasBB);
global.set("horimetro_mcp_be_h", horasBE);

msg.payload = { bb_horas: horasBB, be_horas: horasBE };
msg.topic = "Horímetro MCP BB / MCP BE";

return msg;

/* ============================================================
   NEREUS - DIAGNÓSTICO OPERACIONAL MCP BB e MCP BE
   Versão v3
   ------------------------------------------------------------
   NOVIDADES DA v3:
   1) O estado do enlace Modbus entra no payload e no banner. Se a
      comunicação cair, os gauges continuam mostrando o último
      valor lido: o diagnóstico passa a marcar DADOS OBSOLETOS e
      eleva a severidade geral para ATENCAO, em vez de declarar
      normalidade sobre número congelado.
   2) Lista SENSORES_INOPERANTES: canais reconhecidamente com
      defeito podem ser excluídos das regras de alarme, evitando
      alarme crítico permanente que dessensibiliza o operador.
      Deixe a lista vazia enquanto o sensor não for confirmado
      como defeituoso — excluir sensor bom mascara falha real.

   PENDÊNCIA MANTIDA: óleo da redutora sem canal disponível.
   ============================================================ */

// Para suprimir as regras de um canal defeituoso, inclua o nome
// na lista. Exemplo, com o transdutor de pressão do BE em pane:
// const SENSORES_INOPERANTES = ["ch7"];
const SENSORES_INOPERANTES = [];

const RPM_PARADO = 200;
const RPM_REGIME_ESTAVEL = 700;
const RPM_FAIXA_DESACELERACAO_MAX = 500;

const PRESS_CRITICA = 3.0;        // bar
const PRESS_MIN_OPERACAO = 4.2;   // bar

const TEMP_OLEO_AQUEC_1 = 30;     // °C
const TEMP_OLEO_AQUEC_2 = 40;     // °C
const TEMP_OLEO_NORMAL_MIN = 66;  // °C
const TEMP_OLEO_NORMAL_MAX = 76;  // °C
const TEMP_OLEO_CRITICO = 85;     // °C

const TEMP_AGUA_CARGA_MIN = 45;   // °C
const TEMP_AGUA_AQUEC_MAX = 65;   // °C
const TEMP_AGUA_NORMAL_MIN = 65;  // °C
const TEMP_AGUA_NORMAL_MAX = 75;  // °C
const TEMP_AGUA_CRITICO = 85;     // °C

const TAXA_AGUA_ATENCAO = 2.0;    // °C/min
const TAXA_OLEO_ATENCAO = 1.5;    // °C/min
const TAXA_PRESSAO_QUEDA_ATENCAO = -0.3; // bar/min (PROVISÓRIO)
const TAXA_RPM_OSCILACAO = 300;   // rpm/min (PROVISÓRIO)
const RPM_ESTAVEL_TOLERANCIA = 50; // rpm/min (PROVISÓRIO)

const NIVEIS = ["NORMAL", "INFORMATIVO", "AVISO", "ATENCAO", "ATENCAO_ALTA", "CRITICO"];

function avaliarMotor(motorNome, canalPressao, rpm, tempOleo, tempAgua, pressOleo,
                      taxaOleo, taxaAgua, taxaPressao, taxaRpm) {

    let msgs = { criticos: [], atencao_alta: [], atencao: [], avisos: [], informativos: [] };
    let nivelMax = 0;

    // Canal de pressão marcado como inoperante: neutraliza as regras
    // que dependem dele, mas registra a pendência de forma visível.
    let pressaoValida = SENSORES_INOPERANTES.indexOf(canalPressao) === -1;
    if (!pressaoValida) {
        pressOleo = NaN;
        taxaPressao = NaN;
    }

    function add(nivel, lista, texto) {
        msgs[lista].push(texto);
        if (nivel > nivelMax) nivelMax = nivel;
    }

    let rpmValido = isFinite(rpm);
    let motorParado = !rpmValido || rpm < RPM_PARADO;
    let estado;

    if (!rpmValido) {
        estado = "SEM DADOS";
        add(2, "avisos", "Falha de leitura de RPM.");
    } else if (motorParado) {
        estado = "PARADO";
        add(1, "informativos", "Motor parado. Pressão baixa não deve ser tratada como falha neste estado.");
    } else {
        if (isFinite(tempOleo) && tempOleo < TEMP_OLEO_AQUEC_1) {
            estado = "AQUECIMENTO_INICIAL";
        } else if (isFinite(tempOleo) && tempOleo < TEMP_OLEO_AQUEC_2) {
            estado = "AQUECIMENTO_PROGRESSIVO";
        } else if (isFinite(tempOleo) && isFinite(tempAgua) && isFinite(pressOleo) &&
                   tempOleo >= TEMP_OLEO_NORMAL_MIN && tempOleo <= TEMP_OLEO_NORMAL_MAX &&
                   tempAgua >= TEMP_AGUA_NORMAL_MIN && tempAgua <= TEMP_AGUA_NORMAL_MAX &&
                   pressOleo >= PRESS_MIN_OPERACAO) {
            estado = "REGIME_NORMAL";
        } else if (isFinite(tempOleo) && isFinite(tempAgua) &&
                   tempOleo >= TEMP_OLEO_AQUEC_2 && tempAgua >= TEMP_AGUA_CARGA_MIN) {
            estado = "PRONTO_PARA_CARGA";
        } else {
            estado = "EM_FUNCIONAMENTO";
        }

        // ---- CRÍTICO ----
        if (isFinite(pressOleo) && pressOleo < PRESS_CRITICA) {
            let nota = (rpm < RPM_FAIXA_DESACELERACAO_MAX)
                ? " RPM em faixa de desaceleração/marcha lenta — confirmar se é transitório, mas não deixar de verificar."
                : "";
            add(5, "criticos", "Pressão do óleo abaixo de 3 bar com motor em funcionamento. Verificar imediatamente a lubrificação." + nota);
        }
        if (isFinite(pressOleo) && rpm >= RPM_REGIME_ESTAVEL && pressOleo < PRESS_MIN_OPERACAO) {
            add(5, "criticos", "Pressão do óleo abaixo da referência mínima (4,2 bar) em regime de operação estabilizado (RPM ≥ 700). Verificação imediata recomendada.");
        }
        if (isFinite(tempOleo) && isFinite(pressOleo) && tempOleo > TEMP_OLEO_NORMAL_MAX && pressOleo < PRESS_MIN_OPERACAO) {
            add(5, "criticos", "Óleo quente associado a pressão baixa. Verificar lubrificação, viscosidade, bomba e possíveis vazamentos.");
        }
        if (isFinite(tempOleo) && tempOleo > TEMP_OLEO_CRITICO) {
            add(5, "criticos", "Temperatura do óleo em condição crítica (> 85 °C). Reduzir carga e verificar lubrificação/resfriamento.");
        }
        if (isFinite(tempAgua) && tempAgua > TEMP_AGUA_CRITICO) {
            add(5, "criticos", "Temperatura da água doce em condição crítica (> 85 °C). Verificar circulação, bombas e trocadores.");
        }

        // ---- ATENÇÃO ALTA ----
        if (isFinite(tempAgua) && isFinite(tempOleo) && tempAgua > TEMP_AGUA_NORMAL_MAX && tempOleo > TEMP_OLEO_NORMAL_MAX) {
            add(4, "atencao_alta", "Água e óleo acima das faixas normais. Possível deficiência térmica geral.");
        }
        if (isFinite(taxaOleo) && taxaOleo > 0 && isFinite(taxaPressao) && taxaPressao < 0) {
            add(4, "atencao_alta", "Temperatura do óleo subindo enquanto a pressão cai. Possível perda de viscosidade ou deficiência de lubrificação.");
        }

        // ---- ATENÇÃO ----
        if (isFinite(tempOleo) && tempOleo > TEMP_OLEO_NORMAL_MAX) {
            add(3, "atencao", "Temperatura do óleo acima da faixa normal de referência (> 76 °C).");
        }
        if (isFinite(tempAgua) && tempAgua > TEMP_AGUA_NORMAL_MAX) {
            add(3, "atencao", "Temperatura da água doce acima da faixa recomendada (> 75 °C).");
        }
        if (isFinite(pressOleo) && pressOleo >= PRESS_CRITICA && pressOleo < PRESS_MIN_OPERACAO) {
            add(3, "atencao", "Pressão do óleo abaixo da referência mínima operacional de 4,2 bar.");
        }
        if (isFinite(tempAgua) && isFinite(tempOleo) && tempAgua >= TEMP_AGUA_NORMAL_MIN && tempAgua <= TEMP_AGUA_NORMAL_MAX && tempOleo > TEMP_OLEO_NORMAL_MAX) {
            add(3, "atencao", "Água em faixa normal, porém óleo acima da referência. Verificar sistema de lubrificação e o ponto de medição do sensor.");
        }
        if (isFinite(taxaAgua) && taxaAgua > TAXA_AGUA_ATENCAO) {
            add(3, "atencao", "Temperatura da água subindo rapidamente (" + taxaAgua.toFixed(2) + " °C/min).");
        }
        if (isFinite(taxaOleo) && taxaOleo > TAXA_OLEO_ATENCAO) {
            add(3, "atencao", "Temperatura do óleo subindo rapidamente (" + taxaOleo.toFixed(2) + " °C/min).");
        }
        if (isFinite(taxaPressao) && isFinite(taxaRpm) && taxaPressao < TAXA_PRESSAO_QUEDA_ATENCAO && Math.abs(taxaRpm) < RPM_ESTAVEL_TOLERANCIA) {
            add(3, "atencao", "Pressão do óleo em tendência de queda (" + taxaPressao.toFixed(2) + " bar/min) com RPM estável. Possível perda de lubrificação, aquecimento do óleo, desgaste ou vazamento.");
        }
        if (isFinite(taxaAgua) && taxaAgua > 0 && rpm < RPM_FAIXA_DESACELERACAO_MAX) {
            add(3, "atencao", "Temperatura da água subindo mesmo com baixa rotação. Possível falha de circulação/resfriamento.");
        }
        if (isFinite(taxaRpm) && Math.abs(taxaRpm) > TAXA_RPM_OSCILACAO) {
            add(3, "atencao", "Oscilação de rotação detectada (variação de " + taxaRpm.toFixed(0) + " rpm/min). Verificar regime de operação ou sinal do sensor.");
        }

        // ---- AVISO ----
        if (isFinite(tempOleo) && tempOleo < TEMP_OLEO_AQUEC_1) {
            add(2, "avisos", "Óleo lubrificante abaixo de 30 °C. Manter aquecimento e evitar carga.");
        } else if (isFinite(tempOleo) && tempOleo < TEMP_OLEO_AQUEC_2) {
            add(2, "avisos", "Óleo entre 30 °C e 40 °C. Aplicar carga de forma progressiva.");
        }
        if (isFinite(tempAgua) && tempAgua < TEMP_AGUA_CARGA_MIN) {
            add(2, "avisos", "Água de resfriamento abaixo de 45 °C. Evitar carga elevada.");
        }

        // ---- INFORMATIVO ----
        if (isFinite(tempAgua) && tempAgua >= TEMP_AGUA_CARGA_MIN && tempAgua < TEMP_AGUA_AQUEC_MAX) {
            add(1, "informativos", "Água doce ainda em fase de aquecimento.");
        }
    }

    if (!pressaoValida) {
        add(2, "avisos", "Sensor de pressão do óleo marcado como inoperante. Regras de pressão suspensas até substituição do transdutor. Acompanhar por indicador local.");
    }

    return {
        motor: motorNome,
        estado: estado,
        severidade: NIVEIS[nivelMax],
        rpm: rpm,
        temp_oleo_c: tempOleo,
        temp_agua_c: tempAgua,
        press_oleo_bar: pressaoValida ? pressOleo : null,
        pressao_valida: pressaoValida,
        taxa_oleo_c_min: taxaOleo,
        taxa_agua_c_min: taxaAgua,
        taxa_pressao_bar_min: taxaPressao,
        taxa_rpm_min: taxaRpm,
        redutora: {
            status: "PENDENTE",
            mensagem: "Sem sensor disponível após o remapeamento dos canais. Monitoramento pendente de novo hardware/canal."
        },
        criticos: msgs.criticos,
        atencao_alta: msgs.atencao_alta,
        atencao: msgs.atencao,
        avisos: msgs.avisos,
        informativos: msgs.informativos
    };
}

