/* ============================================================
   NEREUS - GRAVAÇÃO DO HISTÓRICO EM CSV
   Versão v2
   ------------------------------------------------------------
   MUDANÇA: quando o enlace Modbus está em falha, os canais
   continuam com o último valor recebido. Gravar esse valor
   repetido durante horas contamina a base estatística e as
   futuras rotinas de detecção de anomalia. A partir desta
   versão, em falha de comunicação a linha continua sendo
   gravada (para preservar a linha do tempo), porém com os
   campos de medição vazios e a coluna Status_Comunicacao
   indicando a condição.
   ============================================================ */

var separador = ";";

function doisDigitos(n) {
    return n < 10 ? "0" + n : "" + n;
}

var agoraArquivo = new Date();
var anoArq = agoraArquivo.getFullYear();
var mesArq = doisDigitos(agoraArquivo.getMonth() + 1);
var diaArq = doisDigitos(agoraArquivo.getDate());

msg.filename = "C:\\Dados_Motor\\motor_diesel_" + anoArq + "-" + mesArq + "-" + diaArq + ".csv";

function dataHoraAtual() {
    var agora = new Date();
    return agora.getFullYear() + "-" + doisDigitos(agora.getMonth() + 1) + "-" + doisDigitos(agora.getDate()) +
        " " + doisDigitos(agora.getHours()) + ":" + doisDigitos(agora.getMinutes()) + ":" + doisDigitos(agora.getSeconds());
}

function numero(valor, casas) {
    var n = Number(valor);
    if (!isFinite(n)) return "";
    return n.toFixed(casas);
}

function campoTexto(valor) {
    return '"' + String(valor).replace(/"/g, '""') + '"';
}

function juntar(lista) {
    return Array.isArray(lista) ? lista.join(" | ") : "";
}

var com = global.get("status_comunicacao") || {};
var enlaceCaiu = (com.nivel !== undefined && com.nivel >= 2);
