        campoTexto(enlaceCaiu ? "SEM DADOS" : (diagBE.estado || "")), campoTexto(enlaceCaiu ? "" : (diagBE.severidade || "")),
        campoTexto(juntar(diagBE.criticos)), campoTexto(juntar(diagBE.atencao_alta)), campoTexto(juntar(diagBE.atencao)),
        campoTexto(juntar(diagBE.avisos)), campoTexto(juntar(diagBE.informativos)),
        numero(horimetroBB, 2), numero(horimetroBE, 2),
        numero(taxaOleoBB, 2), numero(taxaAguaBB, 2), numero(taxaPressaoBB, 3), numero(taxaRpmBB, 0),
        numero(taxaOleoBE, 2), numero(taxaAguaBE, 2), numero(taxaPressaoBE, 3), numero(taxaRpmBE, 0),
        campoTexto(severidadeGeral), campoTexto(statusCom)
    ])
    .join(separador);

var ultimoArquivo = context.get("ultimoArquivo");
var cabecalhoGravado = context.get("cabecalhoGravado") || false;

if (ultimoArquivo !== msg.filename) {
    cabecalhoGravado = false;
    context.set("ultimoArquivo", msg.filename);
}

if (!cabecalhoGravado) {
    msg.payload = cabecalho + "\r\n" + linha + "\r\n";
    context.set("cabecalhoGravado", true);
} else {
    msg.payload = linha + "\r\n";
}

