/* ---------------- parser CSV com aspas ---------------- */
function parseCsv(txt, sep) {
    let linhas = [];
    let campo = "";
    let linha = [];
    let dentroAspas = false;

    for (let i = 0; i < txt.length; i++) {
        let c = txt[i];
        if (dentroAspas) {
            if (c === '"') {
                if (txt[i + 1] === '"') { campo += '"'; i++; }
                else { dentroAspas = false; }
            } else { campo += c; }
        } else if (c === '"') {
            dentroAspas = true;
        } else if (c === sep) {
            linha.push(campo); campo = "";
        } else if (c === "\n") {
            linha.push(campo); campo = "";
            if (linha.length > 1 || linha[0] !== "") linhas.push(linha);
            linha = [];
        } else if (c !== "\r") {
            campo += c;
        }
    }
    linha.push(campo);
    if (linha.length > 1 || linha[0] !== "") linhas.push(linha);
    return linhas;
}

let linhas = parseCsv(texto, ";");
if (linhas.length < 2) {
    node.warn("NEREUS: CSV de " + msg.dataRef + " sem linhas de dados.");
    return null;
}

let cab = linhas[0];
let idx = {};
cab.forEach(function (nome, i) { idx[nome.trim()] = i; });

function num(linha, coluna) {
    let i = idx[coluna];
    if (i === undefined) return NaN;
    let v = String(linha[i]).trim().replace(",", ".");
    if (v === "") return NaN;
    let n = Number(v);
    return isFinite(n) ? n : NaN;
}
function txt(linha, coluna) {
    let i = idx[coluna];
    return i === undefined ? "" : String(linha[i]).trim();
}
function minutosDoDia(s) {
    let m = /(\d{2}):(\d{2}):(\d{2})/.exec(s);
    if (!m) return NaN;
    return Number(m[1]) * 60 + Number(m[2]) + Number(m[3]) / 60;
}

/* ---------------- carga dos registros ---------------- */
let regs = [];
for (let i = 1; i < linhas.length; i++) {
