/* ---------------- estatística ---------------- */
function estat(valores) {
    let v = valores.filter(function (x) { return isFinite(x); }).sort(function (a, b) { return a - b; });
    if (v.length === 0) return null;
    let soma = v.reduce(function (a, b) { return a + b; }, 0);
    return {
        n: v.length,
        min: v[0],
        max: v[v.length - 1],
        media: soma / v.length,
        p95: v[Math.min(v.length - 1, Math.floor(v.length * 0.95))],
        mediana: v[Math.floor(v.length / 2)]
    };
}

