function delta(lista, campo) {
    let v = lista.map(function (r) { return r[campo]; }).filter(function (x) { return isFinite(x); });
    if (v.length < 2) return 0;
    let d = v[v.length - 1] - v[0];
    return d > 0 ? d : (v[v.length - 1] || 0);
}
