// ocorrências: mensagem -> {n, primeira, ultima}
function coletar(lista, campos) {
    let mapa = {};
    lista.forEach(function (r) {
        campos.forEach(function (c) {
            let bruto = r[c];
            if (!bruto) return;
            bruto.split(" | ").forEach(function (m) {
                let k = m.trim();
                if (!k) return;
                if (!mapa[k]) mapa[k] = { n: 0, primeira: r.hora, ultima: r.hora };
                mapa[k].n++;
                mapa[k].ultima = r.hora;
            });
        });
    });
    return Object.keys(mapa).map(function (k) {
        return { msg: k, n: mapa[k].n, primeira: mapa[k].primeira, ultima: mapa[k].ultima };
    }).sort(function (a, b) { return b.n - a.n; });
}
