function contaEstado(lista, campo) {
    let c = {};
    lista.forEach(function (r) { let k = r[campo] || "—"; c[k] = (c[k] || 0) + 1; });
    return Object.keys(c).map(function (k) { return { estado: k, n: c[k] }; })
        .sort(function (a, b) { return b.n - a.n; });
}

// sensor travado: variação nula em todo o arquivo
function sensorTravado(lista, campo) {
    let v = lista.map(function (r) { return r[campo]; }).filter(function (x) { return isFinite(x); });
    if (v.length < 10) return false;
    let mn = Math.min.apply(null, v), mx = Math.max.apply(null, v);
    return (mx - mn) < 0.01;
}
