/* ---------------- gráficos SVG ---------------- */
function reamostrar(lista, campo) {
    let pts = [];
    let passo = Math.max(1, Math.ceil(lista.length / MAX_PONTOS));
    for (let i = 0; i < lista.length; i += passo) {
        let bloco = lista.slice(i, i + passo).map(function (r) { return r[campo]; })
            .filter(function (x) { return isFinite(x); });
        if (bloco.length === 0) continue;
        let media = bloco.reduce(function (a, b) { return a + b; }, 0) / bloco.length;
        pts.push({ t: lista[i].t, v: media });
    }
    return pts;
}

function esc(s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function grafico(titulo, unidade, series, faixas, yForcado, naoNegativo) {
    const W = 980, H = 300;
    const ML = 62, MR = 18, MT = 34, MB = 40;
    const PW = W - ML - MR, PH = H - MT - MB;

    let todos = [];
    series.forEach(function (s) { s.pts.forEach(function (p) { todos.push(p.v); }); });
    if (todos.length === 0) {
        return '<div class="grafico-vazio">' + esc(titulo) + ': sem dados no período.</div>';
    }

    let ymin = Math.min.apply(null, todos);
    let ymax = Math.max.apply(null, todos);
    if (yForcado) { ymin = Math.min(ymin, yForcado[0]); ymax = Math.max(ymax, yForcado[1]); }
    if (faixas) faixas.forEach(function (f) { ymin = Math.min(ymin, f.de); ymax = Math.max(ymax, f.ate); });
    let span = (ymax - ymin) || 1;
    ymin -= span * 0.08; ymax += span * 0.08;
    if (naoNegativo && ymin < 0) ymin = 0;

    let tmin = 0, tmax = 1440;
    let tsAll = [];
    series.forEach(function (s) { s.pts.forEach(function (p) { tsAll.push(p.t); }); });
    if (tsAll.length > 0) {
        tmin = Math.max(0, Math.min.apply(null, tsAll) - 5);
        tmax = Math.min(1440, Math.max.apply(null, tsAll) + 5);
        if (tmax - tmin < 30) { tmax = tmin + 30; }
    }

    function X(t) { return ML + ((t - tmin) / (tmax - tmin)) * PW; }
    function Y(v) { return MT + PH - ((v - ymin) / (ymax - ymin)) * PH; }

    let svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" width="100%" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg">';
    svg += '<rect x="' + ML + '" y="' + MT + '" width="' + PW + '" height="' + PH + '" fill="#ffffff" stroke="#c9d3de"/>';

    // faixa de referência
    if (faixas) {
        faixas.forEach(function (f) {
            let y1 = Y(Math.min(f.ate, ymax)), y2 = Y(Math.max(f.de, ymin));
            svg += '<rect x="' + ML + '" y="' + y1.toFixed(1) + '" width="' + PW + '" height="' + Math.max(0, y2 - y1).toFixed(1) + '" fill="' + f.cor + '" opacity="0.16"/>';
        });
    }

    // grade e escala Y
    let divisoes = 5;
    for (let g = 0; g <= divisoes; g++) {
        let v = ymin + (ymax - ymin) * (g / divisoes);
        let y = Y(v);
        svg += '<line x1="' + ML + '" y1="' + y.toFixed(1) + '" x2="' + (ML + PW) + '" y2="' + y.toFixed(1) + '" stroke="#e4eaf0"/>';
        svg += '<text x="' + (ML - 8) + '" y="' + (y + 4).toFixed(1) + '" text-anchor="end" font-size="11" fill="#5a6b7c">' + v.toFixed(v > 100 ? 0 : 1) + '</text>';
    }

    // escala X de hora em hora
    let passoH = (tmax - tmin) > 480 ? 120 : ((tmax - tmin) > 180 ? 60 : 30);
    for (let t = Math.ceil(tmin / passoH) * passoH; t <= tmax; t += passoH) {
        let x = X(t);
        svg += '<line x1="' + x.toFixed(1) + '" y1="' + MT + '" x2="' + x.toFixed(1) + '" y2="' + (MT + PH) + '" stroke="#e4eaf0"/>';
        let hh = Math.floor(t / 60), mm = Math.round(t % 60);
        svg += '<text x="' + x.toFixed(1) + '" y="' + (MT + PH + 16) + '" text-anchor="middle" font-size="11" fill="#5a6b7c">' +
            (hh < 10 ? "0" : "") + hh + ":" + (mm < 10 ? "0" : "") + mm + '</text>';
    }

    // séries
    series.forEach(function (s) {
        if (s.pts.length === 0) return;
        let d = "";
        s.pts.forEach(function (p, i) {
            d += (i === 0 ? "M" : "L") + X(p.t).toFixed(1) + " " + Y(p.v).toFixed(1) + " ";
        });
        svg += '<path d="' + d + '" fill="none" stroke="' + s.cor + '" stroke-width="1.6" stroke-linejoin="round"/>';
    });

    // título e legenda
    svg += '<text x="' + ML + '" y="20" font-size="13" font-weight="600" fill="#0d2b45">' + esc(titulo) + ' (' + esc(unidade) + ')</text>';
    let lx = ML + 300;
    series.forEach(function (s) {
        svg += '<rect x="' + lx + '" y="10" width="14" height="4" fill="' + s.cor + '"/>';
        svg += '<text x="' + (lx + 20) + '" y="16" font-size="11" fill="#3c4d5e">' + esc(s.nome) + '</text>';
        lx += 24 + (s.nome.length * 6.4);
    });
    svg += '<text x="' + (ML + PW) + '" y="' + (MT + PH + 32) + '" text-anchor="end" font-size="10" fill="#8595a4">hora local</text>';
    svg += '</svg>';
    return svg;
}

