'<div class="card"><div class="rot">Horímetro MCP BE</div><div class="val">' + fmt(horasBE, 2) + '</div><div class="un">horas no período</div></div>' +
'<div class="card"><div class="rot">Severidade máxima</div><div class="val" style="font-size:13px"><span class="pill p-' + piorSev + '">' + piorSev.replace("_", " ") + '</span></div><div class="un">pior condição registrada</div></div>' +
'</div>' +

blocoQualidade +

'<h2>2. Estatística dos parâmetros com motor em funcionamento</h2>' +
'<p style="margin:0 0 6px 0;color:#4a5c6e">Amostras consideradas: rotação igual ou superior a ' + RPM_MIN_OPERANDO + ' RPM. MCP BB: ' + operBB.length + ' amostras. MCP BE: ' + operBE.length + ' amostras. Linhas destacadas indicam parâmetro que saiu da faixa de referência em algum momento.</p>' +
'<table><thead><tr><th>Motor</th><th>Parâmetro</th><th class="n">Mín</th><th class="n">Média</th><th class="n">P95</th><th class="n">Máx</th><th class="n">Un.</th><th class="n">Referência</th></tr></thead><tbody>' + linhasStats + '</tbody></table>' +

'<h2>3. Comportamento ao longo do dia</h2>' +
'<div class="grafico">' + gTempOleo + '</div>' +
'<div class="grafico">' + gTempAgua + '</div>' +
'<div class="grafico">' + gPressao + '</div>' +
'<div class="grafico">' + gRotacao + '</div>' +

'<div class="quebra"></div>' +
'<h2>4. Distribuição de severidade</h2>' +
'<div class="duas"><div>' + tabelaSev(sevBB, "MCP BB") + '</div><div>' + tabelaSev(sevBE, "MCP BE") + '</div><div>' + tabelaSev(sevGeral, "Geral") + '</div></div>' +

'<h2>5. Estados operacionais</h2>' +
