tabelaOcorr(ocorrBB, "MCP BB") +
tabelaOcorr(ocorrBE, "MCP BE") +

'<div class="nota"><b>Natureza do documento.</b> Este relatório é gerado automaticamente a partir dos registros do NEREUS e tem finalidade de apoio à decisão. Os valores decorrem de instrumentação auxiliar, independente dos circuitos de segurança certificados do motor. Alarmes e tendências aqui apresentados exigem verificação por pessoal habilitado antes de qualquer providência de manutenção ou alteração de regime de operação.</div>' +

'<div class="assin"><div class="linha">Encarregado de Máquinas</div></div>' +

'<footer><span>NEREUS · EDCG Marambaia</span><span>Gerado em ' + geradoEm + '</span></footer>' +
'</body></html>';

msg.payload = html;
msg.filename = msg.arquivoHtml;

node.status({ fill: "green", shape: "dot", text: msg.dataRef + " · " + regs.length + " reg." });

return msg;

/* Monta o comando que converte o HTML em PDF.
   O script gerar_pdf.bat localiza o msedge.exe e faz a impressão
   em modo headless. Nada é instalado: o Edge já vem com o Windows. */

const SCRIPT = "C:\\Dados_Motor\\gerar_pdf.bat";

msg.payload = '"' + SCRIPT + '" "' + msg.arquivoHtml + '" "' + msg.arquivoPdf + '"';

msg.relatorio = {
    data: msg.dataRef,
    html: msg.arquivoHtml,
    pdf: msg.arquivoPdf
};

global.set("ultimo_relatorio", {
    data: msg.dataRef,
    pdf: msg.arquivoPdf,
    gerado_em: new Date().toLocaleString("pt-BR")
});

node.status({ fill: "blue", shape: "dot", text: "convertendo " + msg.dataRef });

return msg;

/* Interpreta o retorno do gerar_pdf.bat e alimenta o card do dashboard. */

let ultimo = global.get("ultimo_relatorio") || {};
let codigo = (msg.payload && msg.payload.code !== undefined) ? msg.payload.code : msg.payload;
let sucesso = (Number(codigo) === 0);

let saida = {
    arquivo: ultimo.pdf || "—",
    gerado_em: new Date().toLocaleString("pt-BR"),
    sucesso: sucesso,
    situacao: sucesso
        ? "PDF gerado com sucesso."
        : "Falha na conversão (código " + codigo + "). Conferir se o Microsoft Edge está instalado e se o gerar_pdf.bat está em C:\\Dados_Motor\\."
};

global.set("ultimo_relatorio_status", saida);

node.status({ fill: sucesso ? "green" : "red", shape: "dot", text: saida.situacao.slice(0, 40) });

msg.payload = saida;
return msg;

/* ============================================================
   NEREUS v6 - AQUISIÇÃO, LINEARIZAÇÃO E FILTRO EMA
   ------------------------------------------------------------
   Mudanças em relação à v5:
   1) Guarda também a tensão bruta de cada canal em janela móvel,
      usada pelo motor de integridade de instrumentação para
      distinguir "sensor em pane" de "condição real do motor".
   2) Conta leituras válidas por hora, base do cálculo honesto de
      disponibilidade do enlace.
   3) Marca o instante da leitura na ENTRADA (mantido da v5).

   MAPEAMENTO DE CANAIS
   CH1 Temp. óleo lubrificante MCP BB   CH5 Temp. óleo lubrificante MCP BE
   CH2 Temp. água doce MCP BB           CH6 Temp. água doce MCP BE
   CH3 Pressão óleo lubrificante MCP BB CH7 Pressão óleo lubrificante MCP BE
   CH4 Rotação MCP BB                   CH8 Rotação MCP BE
   ============================================================ */

var versaoCodigo = "aquisicao_v6";
var AMOSTRAS_MEDIA = 1;
var JANELA_AMOSTRAS = 180;   // 180 x 5 s = 15 min de histórico por canal

var listaCanais = msg.payload;

if (!Array.isArray(listaCanais) || listaCanais.length < 8) {
    global.set("modbus_leituras_invalidas", (global.get("modbus_leituras_invalidas") || 0) + 1);
    return null;
}

// -------- carimbo de comunicação: toda leitura válida do escravo --------
var agoraMs = Date.now();
global.set("ultima_leitura_ms", agoraMs);
global.set("ultima_leitura_valida", new Date().toISOString());
global.set("modbus_leituras_ok", (global.get("modbus_leituras_ok") || 0) + 1);

if (context.get("versaoCodigo") !== versaoCodigo) {
    context.set("amostras", 0);
    context.set("soma", [0, 0, 0, 0, 0, 0, 0, 0]);
    context.set("ema", null);
    context.set("versaoCodigo", versaoCodigo);
}

var canais = [
    { nome: "ch1", descricao: "Temp Óleo Lub. BB",    divisor: 100, x1: 0, y1: 0, x2: 10, y2: 120,  unidade: "°C",  alpha: 0.30, deadband: 0.20 },
    { nome: "ch2", descricao: "Temp Água Doce BB",    divisor: 100, x1: 0, y1: 0, x2: 10, y2: 120,  unidade: "°C",  alpha: 0.30, deadband: 0.20 },
    { nome: "ch3", descricao: "Pressão Óleo Lub. BB", divisor: 100, x1: 0, y1: 0, x2: 10, y2: 10,   unidade: "bar", alpha: 0.40, deadband: 0.03 },
    { nome: "ch4", descricao: "Rotação MCP BB",       divisor: 100, x1: 0, y1: 0, x2: 10, y2: 2000, unidade: "RPM", alpha: 0.55, deadband: 5    },
    { nome: "ch5", descricao: "Temp Óleo Lub. BE",    divisor: 100, x1: 0, y1: 0, x2: 10, y2: 120,  unidade: "°C",  alpha: 0.30, deadband: 0.20 },
    { nome: "ch6", descricao: "Temp Água Doce BE",    divisor: 100, x1: 0, y1: 0, x2: 10, y2: 120,  unidade: "°C",  alpha: 0.30, deadband: 0.20 },
    { nome: "ch7", descricao: "Pressão Óleo Lub. BE", divisor: 100, x1: 0, y1: 0, x2: 10, y2: 10,   unidade: "bar", alpha: 0.40, deadband: 0.03 },
    { nome: "ch8", descricao: "Rotação MCP BE",       divisor: 100, x1: 0, y1: 0, x2: 10, y2: 2000, unidade: "RPM", alpha: 0.55, deadband: 5    }
];

function linearizar(valorLido, cfg) {
    var a = (cfg.y2 - cfg.y1) / (cfg.x2 - cfg.x1);
    var b = cfg.y1 - (a * cfg.x1);
    return (a * valorLido) + b;
}

function limitar(valor, minimo, maximo) {
    if (valor < minimo) return minimo;
    if (valor > maximo) return maximo;
    return valor;
}

var amostras = context.get("amostras") || 0;
var soma = context.get("soma") || [0, 0, 0, 0, 0, 0, 0, 0];
var tensoes = [];

for (var i = 0; i < 8; i++) {
    var cfg = canais[i];

    var bruto = Number(listaCanais[i]) || 0;
    var tensao = bruto / cfg.divisor;

    var valorLinearizado = linearizar(tensao, cfg);
    var valorLimitado = limitar(valorLinearizado, cfg.y1, cfg.y2);

    tensoes.push(Number(tensao.toFixed(3)));

    global.set(cfg.nome + "_bruto", bruto);
    global.set(cfg.nome + "_tensao", Number(tensao.toFixed(2)));
    global.set(cfg.nome + "_sem_filtro", Number(valorLimitado.toFixed(2)));

    soma[i] += valorLimitado;
}

global.set("tensoes_canais", tensoes);

amostras++;

if (amostras < AMOSTRAS_MEDIA) {
    context.set("amostras", amostras);
    context.set("soma", soma);
    return null;
}

var medias = [];
for (var j = 0; j < 8; j++) {
    medias[j] = soma[j] / AMOSTRAS_MEDIA;
}

context.set("amostras", 0);
context.set("soma", [0, 0, 0, 0, 0, 0, 0, 0]);

var ema = context.get("ema");
if (!Array.isArray(ema) || ema.length < 8) {
    ema = medias.slice();
}

var filtrados = [];

for (var k = 0; k < 8; k++) {
    var cfgFiltro = canais[k];

    var valorAtual = medias[k];
    var valorAnterior = ema[k];

    var valorFiltrado = (cfgFiltro.alpha * valorAtual) + ((1 - cfgFiltro.alpha) * valorAnterior);

    if (Math.abs(valorFiltrado - valorAnterior) < cfgFiltro.deadband) {
        valorFiltrado = valorAnterior;
    }

    valorFiltrado = limitar(valorFiltrado, cfgFiltro.y1, cfgFiltro.y2);

    filtrados[k] = Number(valorFiltrado.toFixed(2));
    ema[k] = valorFiltrado;

    global.set("ch" + (k + 1), filtrados[k]);
    global.set("ch" + (k + 1) + "_media", Number(valorAtual.toFixed(2)));
    global.set("ch" + (k + 1) + "_filtrado", filtrados[k]);
}

context.set("ema", ema);

/* -------- janela móvel para o motor de integridade --------
   Guarda o valor sem filtro (não o EMA). O EMA mascara o
   congelamento do canal justamente por ser um filtro. */
var janela = context.get("janela") || [];
janela.push({
    t: agoraMs,
    v: [
        Number(global.get("ch1_sem_filtro")), Number(global.get("ch2_sem_filtro")),
        Number(global.get("ch3_sem_filtro")), Number(global.get("ch4_sem_filtro")),
        Number(global.get("ch5_sem_filtro")), Number(global.get("ch6_sem_filtro")),
        Number(global.get("ch7_sem_filtro")), Number(global.get("ch8_sem_filtro"))
    ],
    u: tensoes
});
while (janela.length > JANELA_AMOSTRAS) janela.shift();
context.set("janela", janela);
global.set("janela_canais", janela);

global.set("ultimo_processamento_ms", agoraMs);

return [
    { payload: filtrados[0] },
    { payload: filtrados[1] },
    { payload: filtrados[2] },
    { payload: filtrados[3] },
    { payload: filtrados[4] },
    { payload: filtrados[5] },
    { payload: filtrados[6] },
    { payload: filtrados[7] }
];

/* ============================================================
   NEREUS v6 - REGISTRO DE ERRO REAL DO MODBUS
   ------------------------------------------------------------
   Alimentado por um nó CATCH ligado aos nós Modbus, que é onde a
   biblioteca reporta falha de verdade. Na v5 esse contador vinha
   da segunda saída do nó de leitura, que dispara também em toda
   leitura bem sucedida — daí o número de erros aparecer igual ao
   número de leituras OK no card do dashboard.
   ============================================================ */

let n = (global.get("modbus_erros") || 0) + 1;
global.set("modbus_erros", n);

let texto = "";
if (msg && msg.error && msg.error.message) {
    texto = String(msg.error.message);
} else if (msg && typeof msg.payload === "string") {
    texto = msg.payload;
} else if (msg && msg.payload) {
    try { texto = JSON.stringify(msg.payload).slice(0, 200); } catch (e) { texto = "erro não serializável"; }
} else {
    texto = "falha sem descrição";
}

let origem = (msg && msg.error && msg.error.source && msg.error.source.name) ? msg.error.source.name : "modbus";

let registro = new Date().toLocaleTimeString("pt-BR") + " · " + origem + " · " + texto;

global.set("modbus_ultimo_erro", registro);
global.set("modbus_ultimo_erro_ms", Date.now());

let historico = global.get("modbus_erros_recentes") || [];
historico.unshift(registro);
while (historico.length > 10) historico.pop();
global.set("modbus_erros_recentes", historico);

node.status({ fill: "red", shape: "ring", text: "erros: " + n });

return null;

/* ============================================================
   NEREUS v6 - SUPERVISÃO DO ENLACE MODBUS
   ------------------------------------------------------------
   CORREÇÃO IMPORTANTE EM RELAÇÃO À v5

   Na v5 a segunda saída do nó "Modbus Read" alimentava o contador
   de erros. Essa saída não é de erro: o nó modbus-read entrega na
   saída 1 o vetor de valores e na saída 2 o mesmo resultado com os
   metadados da resposta. Ou seja, ela dispara em toda leitura bem
   sucedida. Era por isso que o card mostrava "Leituras OK: 265 /
   Erros: 265" — o mesmo número nos dois campos.

   Na v6 os erros vêm de um nó catch ligado aos nós Modbus, que é
   onde a biblioteca realmente reporta falha, e a métrica principal
   passa a ser a DISPONIBILIDADE: leituras recebidas dividido pelas
   leituras esperadas na janela. Essa é a informação que sustenta
   um parecer técnico sobre a confiabilidade do enlace.

   Limiares derivam do período configurado no nó Modbus. Com
   PERIODO_LEITURA_S = 5: normal até 12 s, instável até 22 s,
   falha acima disso. Histerese de dois ciclos.

   Saída 1 : card do dashboard
   Saída 2 : registro de interrupção encerrada (para o CSV)
   Saída 3 : pedido de reconexão automática (watchdog)
   ============================================================ */

const PERIODO_LEITURA_S = 5;
const CICLOS_CONFIRMACAO = 2;

/* Reabertura automática da porta serial. Para desligar, basta
   trocar para false — nada mais no fluxo depende disso. */
const RECONEXAO_AUTOMATICA = true;
const RECONEXAO_APOS_S = 60;      // tenta reabrir a porta após 60 s de silêncio
const RECONEXAO_INTERVALO_S = 90; // não repete a tentativa antes disso

/* Deve espelhar exatamente a configuração do nó modbus-client. */
const PORTA_SERIAL = "COM4";
const BAUDRATE = 9600;

const TOL_NORMAL = (PERIODO_LEITURA_S * 2) + 2;
const TOL_INSTAVEL = (PERIODO_LEITURA_S * 4) + 2;

let ultima = global.get("ultima_leitura_ms");
let agora = Date.now();

let statusBruto = "SEM DADOS";
let nivel = 3;               // 0 normal | 1 instável | 2 falha | 3 sem dados
let segundosSemLeitura = null;

if (ultima !== undefined && ultima !== null) {
    segundosSemLeitura = (agora - ultima) / 1000;

    if (segundosSemLeitura <= TOL_NORMAL) {
        statusBruto = "COMUNICAÇÃO NORMAL";
        nivel = 0;
    } else if (segundosSemLeitura <= TOL_INSTAVEL) {
        statusBruto = "COMUNICAÇÃO INSTÁVEL";
        nivel = 1;
    } else {
        statusBruto = "FALHA DE COMUNICAÇÃO";
        nivel = 2;
    }
}

/* -------- histerese -------- */
let statusConfirmado = context.get("statusConfirmado") || statusBruto;
let nivelConfirmado = context.get("nivelConfirmado");
if (nivelConfirmado === undefined) nivelConfirmado = nivel;

let candidato = context.get("candidato");
let contagem = context.get("contagem") || 0;

if (statusBruto === statusConfirmado) {
    candidato = null;
    contagem = 0;
} else if (statusBruto === candidato) {
    contagem++;
    if (contagem >= CICLOS_CONFIRMACAO) {
        statusConfirmado = statusBruto;
        nivelConfirmado = nivel;
        candidato = null;
        contagem = 0;
    }
} else {
    candidato = statusBruto;
    contagem = 1;
}

context.set("statusConfirmado", statusConfirmado);
context.set("nivelConfirmado", nivelConfirmado);
context.set("candidato", candidato);
context.set("contagem", contagem);

/* -------- disponibilidade honesta --------
   Janela deslizante de 24 h com marcas a cada avaliação. Cada marca
   guarda o total acumulado de leituras OK; a diferença entre a
   primeira e a última marca informa quantas leituras chegaram, e o
   tempo decorrido informa quantas eram esperadas. */
let leiturasOk = global.get("modbus_leituras_ok") || 0;
let marcas = context.get("marcas") || [];
marcas.push({ t: agora, n: leiturasOk });
while (marcas.length > 2 && (agora - marcas[0].t) > 86400000) marcas.shift();
context.set("marcas", marcas);

let disponibilidade = null;
let janelaH = 0;
if (marcas.length > 1) {
    let dt = (agora - marcas[0].t) / 1000;
    janelaH = dt / 3600;
    let recebidas = marcas[marcas.length - 1].n - marcas[0].n;
    let esperadas = dt / PERIODO_LEITURA_S;
    if (esperadas > 0) {
        disponibilidade = Math.max(0, Math.min(100, (recebidas / esperadas) * 100));
    }
}

/* -------- interrupções -------- */
let hojeChave = new Date().toISOString().slice(0, 10);
if (context.get("diaChave") !== hojeChave) {
    context.set("diaChave", hojeChave);
    context.set("interrupcoes", 0);
    context.set("tempoIndisponivelS", 0);
}

let interrupcoes = context.get("interrupcoes") || 0;
let tempoIndisponivelS = context.get("tempoIndisponivelS") || 0;
let inicioFalha = context.get("inicioFalha") || null;
let nivelAnterior = context.get("nivelAnterior");
if (nivelAnterior === undefined) nivelAnterior = nivelConfirmado;

let registroEncerrado = null;

if (nivelConfirmado >= 1 && inicioFalha === null) {
    inicioFalha = agora;
    if (nivelAnterior === 0) interrupcoes++;
} else if (nivelConfirmado === 0 && inicioFalha !== null) {
    let duracao = (agora - inicioFalha) / 1000;
    tempoIndisponivelS += duracao;
    registroEncerrado = {
        inicio: new Date(inicioFalha).toLocaleString("pt-BR"),
        fim: new Date(agora).toLocaleString("pt-BR"),
        duracao_s: Number(duracao.toFixed(0)),
        ultimo_erro: global.get("modbus_ultimo_erro") || "",
        reconexao_automatica: context.get("reconectouNestaFalha") ? "sim" : "nao"
    };
    inicioFalha = null;
    context.set("reconectouNestaFalha", false);
}

context.set("inicioFalha", inicioFalha);
context.set("interrupcoes", interrupcoes);
context.set("tempoIndisponivelS", tempoIndisponivelS);
context.set("nivelAnterior", nivelConfirmado);

/* -------- watchdog de reconexão --------
   Silêncio prolongado costuma significar que a porta serial ficou
   com o descritor preso. Reenviar a configuração ao cliente Modbus
   força fechar e reabrir a COM, o que resolve boa parte dos casos
   sem intervenção física. Não resolve travamento do próprio chip do
   conversor: para esse caso existe o botão de reinício da porta na
   aba Sistema. */
let pedidoReconexao = null;
let ultimaTentativa = context.get("ultimaTentativaReconexao") || 0;

if (RECONEXAO_AUTOMATICA &&
    segundosSemLeitura !== null &&
    segundosSemLeitura >= RECONEXAO_APOS_S &&
    (agora - ultimaTentativa) / 1000 >= RECONEXAO_INTERVALO_S) {

    context.set("ultimaTentativaReconexao", agora);
    context.set("reconectouNestaFalha", true);
    let tentativas = (global.get("modbus_reconexoes") || 0) + 1;
    global.set("modbus_reconexoes", tentativas);
    global.set("modbus_ultima_reconexao", new Date().toLocaleString("pt-BR"));

    pedidoReconexao = {
        payload: {
            connectorType: "SERIAL",
            serialPort: PORTA_SERIAL,
            serialType: "RTU",
            serialBaudrate: BAUDRATE,
            serialDatabits: 8,
            serialStopbits: 1,
            serialParity: "none",
            serialConnectionDelay: 100,
            unit_id: 1,
            commandDelay: 1,
            clientTimeout: 1000,
            reconnectTimeout: 2000
        },
        tentativa: tentativas
    };
    node.warn("NEREUS: enlace mudo há " + segundosSemLeitura.toFixed(0) + " s. Tentativa " + tentativas + " de reabertura da COM4.");
}

let payload = {
    status_comunicacao: statusConfirmado,
    nivel: nivelConfirmado,
    alarme: nivelConfirmado >= 1,
    segundos_sem_leitura: segundosSemLeitura !== null ? Number(segundosSemLeitura.toFixed(1)) : null,
    ultima_leitura: global.get("ultima_leitura_valida") || "—",
    ultima_leitura_hora: ultima ? new Date(ultima).toLocaleTimeString("pt-BR") : "—",
    periodo_esperado_s: PERIODO_LEITURA_S,
    limite_normal_s: TOL_NORMAL,
    limite_instavel_s: TOL_INSTAVEL,
    leituras_ok: leiturasOk,
    leituras_invalidas: global.get("modbus_leituras_invalidas") || 0,
    erros_modbus: global.get("modbus_erros") || 0,
    ultimo_erro: global.get("modbus_ultimo_erro") || "—",
    disponibilidade_pct: disponibilidade === null ? null : Number(disponibilidade.toFixed(1)),
    janela_h: Number(janelaH.toFixed(1)),
    interrupcoes_hoje: interrupcoes,
    indisponivel_total_min: Number((tempoIndisponivelS / 60).toFixed(1)),
    indisponivel_ha_s: inicioFalha ? Number(((agora - inicioFalha) / 1000).toFixed(0)) : 0,
    reconexoes: global.get("modbus_reconexoes") || 0,
    ultima_reconexao: global.get("modbus_ultima_reconexao") || "—",
    reconexao_automatica: RECONEXAO_AUTOMATICA,
    porta: PORTA_SERIAL + " · " + BAUDRATE + " 8N1 · escravo 1"
};

global.set("status_comunicacao", payload);

node.status({
    fill: nivelConfirmado === 0 ? "green" : (nivelConfirmado === 1 ? "yellow" : "red"),
    shape: "dot",
    text: statusConfirmado + (disponibilidade === null ? "" : " · " + disponibilidade.toFixed(1) + "%")
});

msg.payload = payload;

return [msg, registroEncerrado ? { payload: registroEncerrado } : null, pedidoReconexao];

/* ============================================================
   NEREUS v6 - REGISTRO DE INTERRUPÇÕES DO ENLACE
   ------------------------------------------------------------
   Grava uma linha por interrupção encerrada em
   C:\Dados_Motor\enlace_falhas.csv

   Objetivo: transformar a queixa "cai de vez em quando" em dado.
   Com data, hora, duração e o erro reportado, dá para correlacionar
   as quedas com manobra, partida de máquina, ligamento de carga
   elétrica ou simples decurso de tempo — que é o que separa
   problema de EMI de problema de driver USB.
   ============================================================ */

const ARQUIVO = "C:\\Dados_Motor\\enlace_falhas.csv";

let r = msg.payload || {};

function campo(v) {
    return '"' + String(v === undefined || v === null ? "" : v).replace(/"/g, '""') + '"';
}

let cabecalho = "Inicio;Fim;Duracao_s;Duracao_min;Erro_Reportado;Reconexao_Automatica;Leituras_OK_Acumuladas;Erros_Acumulados";

let linha = [
    campo(r.inicio),
    campo(r.fim),
    Number(r.duracao_s || 0).toFixed(0),
    (Number(r.duracao_s || 0) / 60).toFixed(2),
    campo(r.ultimo_erro),
    campo(r.reconexao_automatica),
    String(global.get("modbus_leituras_ok") || 0),
    String(global.get("modbus_erros") || 0)
].join(";");

msg.filename = ARQUIVO;

if (!context.get("cabecalhoGravado")) {
    context.set("cabecalhoGravado", true);
    msg.payload = cabecalho + "\r\n" + linha + "\r\n";
} else {
    msg.payload = linha + "\r\n";
}

node.status({ fill: "yellow", shape: "dot", text: "interrupção de " + Number(r.duracao_s || 0).toFixed(0) + " s registrada" });

return msg;

/* ============================================================
   NEREUS v6 - INTEGRIDADE DA INSTRUMENTAÇÃO
   ------------------------------------------------------------
   Separa "condição anormal do equipamento" de "canal de medição
   em pane". Sem essa separação, um transdutor morto produz alarme
   crítico permanente e o operador para de olhar para o alarme —
   que é exatamente o efeito que o sistema existe para evitar.

   O que é avaliado, por canal, sobre a janela móvel de leituras
   sem filtro produzida pelo nó de aquisição:

   a) FORA DE ESCALA BAIXO  - tensão praticamente nula em toda a
      janela. Típico de circuito aberto, fio partido, transdutor
      sem alimentação ou borne solto.
   b) FORA DE ESCALA ALTO   - tensão saturada no topo. Típico de
      curto para a alimentação ou entrada do módulo danificada.
   c) TRAVADO               - variação menor que a resolução
      esperada durante toda a janela, com o motor girando. Sensor
      bom sempre apresenta ruído de processo; ausência total de
      variação é assinatura de canal morto.
   d) ZERO COM MOTOR GIRANDO - só para pressão. Motor girando com
      pressão nula seria uma pane catastrófica que o operador veria
      pelo manômetro local; na prática significa transdutor aberto.

   Classificação:
      OK          - nada detectado
      SUSPEITO    - detectado, ainda dentro do tempo de confirmação
      INOPERANTE  - detectado e mantido por CONFIRMA_MIN minutos,
                    ou incluído manualmente em SENSORES_MARCADOS

   Canal INOPERANTE não gera alarme de processo. Gera pendência de
   manutenção, no nível AVISO, e entra na lista de recomendações.
   ============================================================ */

/* Canais confirmados em pane por verificação em serviço.
   Retirar da lista assim que o transdutor for substituído. */
const SENSORES_MARCADOS = ["ch7"];

const JANELA_MIN_AVALIACAO = 5;    // min de dados necessários para julgar
const CONFIRMA_MIN = 10;           // min de persistência para declarar INOPERANTE
const RPM_MOTOR_GIRANDO = 200;

const CANAIS = [
    { id: "ch1", rotulo: "Temp. óleo lub. MCP BB",  motor: "MCP BB", rpmIdx: 3, tipo: "temp",  tol: 0.30, un: "°C"  },
    { id: "ch2", rotulo: "Temp. água doce MCP BB",  motor: "MCP BB", rpmIdx: 3, tipo: "temp",  tol: 0.30, un: "°C"  },
    { id: "ch3", rotulo: "Pressão óleo lub. MCP BB", motor: "MCP BB", rpmIdx: 3, tipo: "press", tol: 0.05, un: "bar" },
    { id: "ch4", rotulo: "Rotação MCP BB",          motor: "MCP BB", rpmIdx: 3, tipo: "rpm",   tol: 8,    un: "RPM" },
    { id: "ch5", rotulo: "Temp. óleo lub. MCP BE",  motor: "MCP BE", rpmIdx: 7, tipo: "temp",  tol: 0.30, un: "°C"  },
    { id: "ch6", rotulo: "Temp. água doce MCP BE",  motor: "MCP BE", rpmIdx: 7, tipo: "temp",  tol: 0.30, un: "°C"  },
    { id: "ch7", rotulo: "Pressão óleo lub. MCP BE", motor: "MCP BE", rpmIdx: 7, tipo: "press", tol: 0.05, un: "bar" },
    { id: "ch8", rotulo: "Rotação MCP BE",          motor: "MCP BE", rpmIdx: 7, tipo: "rpm",   tol: 8,    un: "RPM" }
];

let agora = Date.now();
let janela = global.get("janela_canais") || [];
let marcasDesde = context.get("marcasDesde") || {};

let minutosJanela = janela.length > 1 ? (janela[janela.length - 1].t - janela[0].t) / 60000 : 0;
let janelaSuficiente = minutosJanela >= JANELA_MIN_AVALIACAO;

function coluna(idx, campo) {
    let v = [];
    for (let i = 0; i < janela.length; i++) {
        let x = janela[i][campo][idx];
        if (isFinite(x)) v.push(x);
    }
    return v;
}

function amplitude(v) {
    if (v.length < 2) return NaN;
    return Math.max.apply(null, v) - Math.min.apply(null, v);
}

function media(v) {
    if (v.length === 0) return NaN;
    return v.reduce(function (a, b) { return a + b; }, 0) / v.length;
}

let resultado = {};
let inoperantes = [];
let suspeitos = [];

CANAIS.forEach(function (c, idx) {
    let valores = coluna(idx, "v");
    let volts = coluna(idx, "u");
    let rpms = coluna(c.rpmIdx, "v");

    let motorGirando = rpms.length > 0 && media(rpms) >= RPM_MOTOR_GIRANDO;
    let manual = SENSORES_MARCADOS.indexOf(c.id) !== -1;

    let motivo = null;

    if (janelaSuficiente && volts.length > 5) {
        let vMed = media(volts);
        let amp = amplitude(valores);
        let vlMed = media(valores);

        if (vMed < 0.05) {
            motivo = "Sinal praticamente nulo na entrada do módulo (" + vMed.toFixed(2) +
                " V) durante " + minutosJanela.toFixed(0) + " min. Compatível com circuito aberto, transdutor sem alimentação ou borne solto.";
        } else if (vMed > 9.95) {
            motivo = "Sinal saturado no topo da escala (" + vMed.toFixed(2) +
                " V). Compatível com curto para a alimentação ou entrada do módulo danificada.";
        } else if (c.tipo === "press" && motorGirando && vlMed < 0.15) {
            motivo = "Pressão indicando " + vlMed.toFixed(2) + " bar com o motor girando há " +
                minutosJanela.toFixed(0) + " min. Confirmar pelo manômetro local antes de tratar como condição do equipamento.";
        } else if (c.tipo !== "rpm" && motorGirando && isFinite(amp) && amp < c.tol) {
            motivo = "Leitura constante em " + vlMed.toFixed(2) + " " + c.un + " (variação de " +
                amp.toFixed(2) + " " + c.un + ") durante " + minutosJanela.toFixed(0) +
                " min com o motor girando. Sensor íntegro apresenta ruído de processo.";
        }
    }

    let estado = "OK";
    let desde = marcasDesde[c.id] || null;

    if (manual) {
        estado = "INOPERANTE";
        if (!desde) desde = agora;
        if (!motivo) {
            motivo = "Canal declarado em pane por verificação em serviço. Regras de alarme suspensas até a substituição do transdutor.";
        }
    } else if (motivo) {
        if (!desde) desde = agora;
        let minutosDetectado = (agora - desde) / 60000;
        estado = minutosDetectado >= CONFIRMA_MIN ? "INOPERANTE" : "SUSPEITO";
    } else {
        desde = null;
    }

    marcasDesde[c.id] = desde;

    resultado[c.id] = {
        id: c.id,
        rotulo: c.rotulo,
        motor: c.motor,
        tipo: c.tipo,
        estado: estado,
        manual: manual,
        motivo: motivo,
        desde: desde,
        desde_hora: desde ? new Date(desde).toLocaleString("pt-BR") : "—",
        minutos: desde ? Number(((agora - desde) / 60000).toFixed(0)) : 0,
        valor: isFinite(media(valores)) ? Number(media(valores).toFixed(2)) : null,
        tensao: isFinite(media(volts)) ? Number(media(volts).toFixed(2)) : null,
        un: c.un
    };

    if (estado === "INOPERANTE") inoperantes.push(c.id);
    else if (estado === "SUSPEITO") suspeitos.push(c.id);
});

context.set("marcasDesde", marcasDesde);

let payload = {
    timestamp: new Date().toISOString(),
    hora_local: new Date().toLocaleTimeString("pt-BR"),
    janela_min: Number(minutosJanela.toFixed(1)),
    janela_suficiente: janelaSuficiente,
    canais: resultado,
    lista: CANAIS.map(function (c) { return resultado[c.id]; }),
    inoperantes: inoperantes,
    suspeitos: suspeitos,
    marcados_manualmente: SENSORES_MARCADOS,
    ha_pendencia: (inoperantes.length + suspeitos.length) > 0,
    press_be_inoperante: resultado.ch7.estado === "INOPERANTE",
    press_bb_inoperante: resultado.ch3.estado === "INOPERANTE"
};

global.set("qualidade_canais", payload);

node.status({
    fill: inoperantes.length ? "yellow" : (suspeitos.length ? "blue" : "green"),
    shape: "dot",
    text: inoperantes.length + " inoperante(s) · " + suspeitos.length + " suspeito(s)"
});

msg.payload = payload;
return msg;

/* ============================================================
   NEREUS v6 - TAXA DE VARIAÇÃO E TENDÊNCIA
   ------------------------------------------------------------
   Além da taxa instantânea em unidade/min, a v6 calcula:

   - a tendência de 60 min por regressão linear simples sobre a
     janela móvel. A taxa instantânea responde a degraus e a
     ruído; a inclinação da reta de uma hora responde a deriva.
     Para manutenção baseada em condição, a segunda é a que
     importa: rampa contínua e degrau isolado exigem condutas
     diferentes.
   - mínimo, média e máximo da última hora por parâmetro, com
     o motor girando, que alimentam o quadro estatístico da aba
     Diagnóstico e o relatório técnico.
   ============================================================ */

const RPM_MOTOR_GIRANDO = 200;
const JANELA_TENDENCIA_MIN = 60;

let agora = Date.now();

let tempOleoBB = Number(global.get("ch1"));
let tempAguaBB = Number(global.get("ch2"));
let pressaoBB  = Number(global.get("ch3"));
let rpmBB      = Number(global.get("ch4"));

let tempOleoBE = Number(global.get("ch5"));
let tempAguaBE = Number(global.get("ch6"));
let pressaoBE  = Number(global.get("ch7"));
let rpmBE      = Number(global.get("ch8"));

let anterior = context.get("anterior") || {};
let tempoAnterior = context.get("tempoAnterior");

let saida = {
    timestamp: new Date().toISOString(),
    taxa_temp_oleo_bb_c_min: 0,
    taxa_temp_agua_bb_c_min: 0,
    taxa_pressao_oleo_bb_bar_min: 0,
    taxa_rpm_bb_rpm_min: 0,
    taxa_temp_oleo_be_c_min: 0,
    taxa_temp_agua_be_c_min: 0,
    taxa_pressao_oleo_be_bar_min: 0,
    taxa_rpm_be_rpm_min: 0
};

let deltaMin = 0;

function taxa(atual, ant, casas) {
    if (!isFinite(atual) || !isFinite(ant) || !(deltaMin > 0)) return 0;
    return Number(((atual - ant) / deltaMin).toFixed(casas));
}

if (tempoAnterior !== undefined) {
    deltaMin = (agora - tempoAnterior) / 60000;

    if (deltaMin > 0 && deltaMin < 5) {
        saida.taxa_temp_oleo_bb_c_min = taxa(tempOleoBB, anterior.tempOleoBB, 2);
        saida.taxa_temp_agua_bb_c_min = taxa(tempAguaBB, anterior.tempAguaBB, 2);
        saida.taxa_pressao_oleo_bb_bar_min = taxa(pressaoBB, anterior.pressaoBB, 3);
        saida.taxa_rpm_bb_rpm_min = taxa(rpmBB, anterior.rpmBB, 0);
        saida.taxa_temp_oleo_be_c_min = taxa(tempOleoBE, anterior.tempOleoBE, 2);
        saida.taxa_temp_agua_be_c_min = taxa(tempAguaBE, anterior.tempAguaBE, 2);
        saida.taxa_pressao_oleo_be_bar_min = taxa(pressaoBE, anterior.pressaoBE, 3);
        saida.taxa_rpm_be_rpm_min = taxa(rpmBE, anterior.rpmBE, 0);
    }
}

context.set("anterior", {
    tempOleoBB: tempOleoBB, tempAguaBB: tempAguaBB, pressaoBB: pressaoBB, rpmBB: rpmBB,
    tempOleoBE: tempOleoBE, tempAguaBE: tempAguaBE, pressaoBE: pressaoBE, rpmBE: rpmBE
});
context.set("tempoAnterior", agora);

global.set("taxa_temp_oleo_bb_c_min", saida.taxa_temp_oleo_bb_c_min);
global.set("taxa_temp_agua_bb_c_min", saida.taxa_temp_agua_bb_c_min);
global.set("taxa_pressao_oleo_bb_bar_min", saida.taxa_pressao_oleo_bb_bar_min);
global.set("taxa_rpm_bb_rpm_min", saida.taxa_rpm_bb_rpm_min);
global.set("taxa_temp_oleo_be_c_min", saida.taxa_temp_oleo_be_c_min);
global.set("taxa_temp_agua_be_c_min", saida.taxa_temp_agua_be_c_min);
global.set("taxa_pressao_oleo_be_bar_min", saida.taxa_pressao_oleo_be_bar_min);
global.set("taxa_rpm_be_rpm_min", saida.taxa_rpm_be_rpm_min);

/* ---------------- janela de 60 min ---------------- */
let hist = context.get("hist") || [];
hist.push({
    t: agora,
    oleoBB: tempOleoBB, aguaBB: tempAguaBB, pressBB: pressaoBB, rpmBB: rpmBB,
    oleoBE: tempOleoBE, aguaBE: tempAguaBE, pressBE: pressaoBE, rpmBE: rpmBE
});
let corte = agora - JANELA_TENDENCIA_MIN * 60000;
while (hist.length > 0 && hist[0].t < corte) hist.shift();
context.set("hist", hist);

function inclinacao(campo, filtroRpm) {
    let xs = [], ys = [];
    for (let i = 0; i < hist.length; i++) {
        let h = hist[i];
        if (filtroRpm && !(isFinite(h[filtroRpm]) && h[filtroRpm] >= RPM_MOTOR_GIRANDO)) continue;
        if (!isFinite(h[campo])) continue;
        xs.push((h.t - hist[0].t) / 60000);
        ys.push(h[campo]);
    }
    if (xs.length < 6) return null;
    let n = xs.length;
    let mx = xs.reduce(function (a, b) { return a + b; }, 0) / n;
    let my = ys.reduce(function (a, b) { return a + b; }, 0) / n;
    let num = 0, den = 0;
    for (let i = 0; i < n; i++) {
        num += (xs[i] - mx) * (ys[i] - my);
        den += (xs[i] - mx) * (xs[i] - mx);
    }
    if (den === 0) return null;
    return num / den;   // unidade por minuto
}

function faixa(campo, filtroRpm) {
    let v = [];
    for (let i = 0; i < hist.length; i++) {
        let h = hist[i];
        if (filtroRpm && !(isFinite(h[filtroRpm]) && h[filtroRpm] >= RPM_MOTOR_GIRANDO)) continue;
        if (isFinite(h[campo])) v.push(h[campo]);
    }
    if (v.length === 0) return null;
    let soma = v.reduce(function (a, b) { return a + b; }, 0);
    return {
        n: v.length,
        min: Number(Math.min.apply(null, v).toFixed(2)),
        media: Number((soma / v.length).toFixed(2)),
        max: Number(Math.max.apply(null, v).toFixed(2))
    };
}

function seta(valor, limiar) {
    if (valor === null) return { simbolo: "·", texto: "sem base", classe: "t-plano" };
    if (valor > limiar) return { simbolo: "▲", texto: "subindo", classe: "t-sobe" };
    if (valor < -limiar) return { simbolo: "▼", texto: "caindo", classe: "t-desce" };
    return { simbolo: "▬", texto: "estável", classe: "t-plano" };
}

const PARAMETROS = [
    { chave: "oleoBB",  rotulo: "Temp. óleo",    motor: "MCP BB", un: "°C",  rpm: "rpmBB", limiar: 0.05 },
    { chave: "aguaBB",  rotulo: "Temp. água",    motor: "MCP BB", un: "°C",  rpm: "rpmBB", limiar: 0.05 },
    { chave: "pressBB", rotulo: "Pressão óleo",  motor: "MCP BB", un: "bar", rpm: "rpmBB", limiar: 0.005 },
    { chave: "rpmBB",   rotulo: "Rotação",       motor: "MCP BB", un: "RPM", rpm: null,    limiar: 2 },
    { chave: "oleoBE",  rotulo: "Temp. óleo",    motor: "MCP BE", un: "°C",  rpm: "rpmBE", limiar: 0.05 },
    { chave: "aguaBE",  rotulo: "Temp. água",    motor: "MCP BE", un: "°C",  rpm: "rpmBE", limiar: 0.05 },
    { chave: "pressBE", rotulo: "Pressão óleo",  motor: "MCP BE", un: "bar", rpm: "rpmBE", limiar: 0.005 },
    { chave: "rpmBE",   rotulo: "Rotação",       motor: "MCP BE", un: "RPM", rpm: null,    limiar: 2 }
];

let qualidade = global.get("qualidade_canais") || { canais: {} };
const CANAL_DE = {
    oleoBB: "ch1", aguaBB: "ch2", pressBB: "ch3", rpmBB: "ch4",
    oleoBE: "ch5", aguaBE: "ch6", pressBE: "ch7", rpmBE: "ch8"
};

let tendencias = PARAMETROS.map(function (p) {
    let inc = inclinacao(p.chave, p.rpm);
    let f = faixa(p.chave, p.rpm);
    let canal = CANAL_DE[p.chave];
    let est = (qualidade.canais && qualidade.canais[canal]) ? qualidade.canais[canal].estado : "OK";
    return {
        motor: p.motor,
        rotulo: p.rotulo,
        un: p.un,
        canal: canal,
        canal_estado: est,
        inclinacao_min: inc === null ? null : Number(inc.toFixed(p.un === "RPM" ? 1 : 3)),
        inclinacao_hora: inc === null ? null : Number((inc * 60).toFixed(p.un === "RPM" ? 0 : 2)),
        min: f ? f.min : null,
        media: f ? f.media : null,
        max: f ? f.max : null,
        amostras: f ? f.n : 0,
        tendencia: seta(inc, p.limiar)
    };
});

let cobertura = hist.length > 1 ? (hist[hist.length - 1].t - hist[0].t) / 60000 : 0;

saida.tendencias = tendencias;
saida.janela_min = Number(cobertura.toFixed(0));
saida.hora_local = new Date().toLocaleTimeString("pt-BR");

global.set("tendencias_60min", tendencias);

msg.payload = saida;
return msg;

/* ============================================================
   NEREUS — MOTOR DE REGRAS DIRIGIDO POR CONFIGURAÇÃO
   ------------------------------------------------------------
   Substitui o bloco de constantes e a função avaliarMotor do
   n6_fn_diag. Tudo que vem depois (enlace, consolidação de
   recomendações e montagem do payload) permanece idêntico.

   Lê a configuração de global.nereus_config, publicada no
   arranque por n6_fn_le_config:

       { instalacao, perfis: {id: perfil}, regras }

   Sem eval e sem new Function: as condições são estrutura de
   dados, percorridas pelo avaliador abaixo.

   Enquanto a configuração não carregar, cai no conjunto
   embutido de reserva — um navio nunca fica sem diagnóstico
   por causa de um arquivo faltando.
   ============================================================ */

const CFG = global.get("nereus_config");

/* Nos primeiros segundos após o arranque a configuração ainda não chegou:
   o carregador roda em 2 s e este nó é disparado a cada 2 s. Isso é normal
   e não é erro. Só vira erro se persistir, e quem avisa nesse caso é o
   quadro de situação da configuração, não este nó a cada ciclo. */
if (!CFG || !CFG.instalacao || !CFG.regras) {
    node.status({ fill: "grey", shape: "ring", text: "aguardando configuração" });
    return null;
}

const NIVEIS = CFG.regras.niveis;

const ROTULO_SEV = {
    NORMAL: "NORMAL", INFORMATIVO: "INFORMATIVO", AVISO: "AVISO",
    ATENCAO: "ATENÇÃO", ATENCAO_ALTA: "ATENÇÃO ALTA", CRITICO: "CRÍTICO"
};

let qualidade = global.get("qualidade_canais") || { canais: {} };

function estadoCanal(id) {
    let c = qualidade.canais ? qualidade.canais[id] : null;
    return c ? c.estado : "OK";
}

/* ---------------- formatação de números ----------------
   O texto do catálogo usa {param} e {param:N}. Sem N, o número
   sai como está escrito, com vírgula decimal e sem zero à toa.
   Com N, sai com N casas e vírgula. Valores medidos usam
   {valor:papel:N} e mantêm o ponto do toFixed, para não mudar
   nada do que já é gravado no CSV. */
function fmtParam(n, casas) {
    if (casas === undefined) {
        let s = String(n);
        return s.replace(".", ",");
    }
    return n.toFixed(casas).replace(".", ",");
}

/* ---------------- avaliador de condições ---------------- */
function valorDe(medidas, papel) {
    let v = medidas[papel];
    return (v === undefined) ? NaN : v;
}

function compara(a, op, b) {
    switch (op) {
        case "<":  return a < b;
        case "<=": return a <= b;
        case ">":  return a > b;
        case ">=": return a >= b;
        case "==": return a === b;
    }
    return false;
}

function termoVerdadeiro(t, medidas, par) {
    if (t.papel_ausente !== undefined) {
        return !isFinite(valorDe(medidas, t.papel_ausente));
    }

    let a = valorDe(medidas, t.papel);
    if (!isFinite(a)) return false;
    if (t.abs) a = Math.abs(a);

    let b;
    if (t.param !== undefined) {
        if (!par[t.param]) return false;
        b = par[t.param].valor;
    } else if (t.valor !== undefined) {
        b = t.valor;
    } else if (t.papel_b !== undefined) {
        b = valorDe(medidas, t.papel_b);
        if (!isFinite(b)) return false;
    } else {
        return false;
    }

    return compara(a, op0(t), b);
}

function op0(t) { return t.op; }

function condVerdadeira(cond, medidas, par) {
    if (!cond) return false;
    if (cond.senao) return true;
    if (cond.papel_ausente !== undefined) {
        return !isFinite(valorDe(medidas, cond.papel_ausente));
    }
    if (cond.todas) {
        return cond.todas.every(function (t) { return termoVerdadeiro(t, medidas, par); });
    }
    if (cond.alguma) {
        return cond.alguma.some(function (t) { return termoVerdadeiro(t, medidas, par); });
    }
    return false;
}

/* ---------------- substituição de texto ---------------- */
function renderizar(txt, par, medidas, motorNome) {
    if (!txt) return txt;

    // {valor:papel:N} — leitura medida, com ponto, como o toFixed original
    txt = txt.replace(/\{valor:([a-z0-9_]+):(\d)\}/g, function (_, papel, n) {
        let v = valorDe(medidas, papel);
        return isFinite(v) ? v.toFixed(Number(n)) : "";
    });

    // {param:N} — parâmetro do perfil com N casas
    txt = txt.replace(/\{([a-z0-9_]+):(\d)\}/g, function (_, k, n) {
        return par[k] ? fmtParam(par[k].valor, Number(n)) : "";
    });

    // {motor} e {param}
    txt = txt.replace(/\{([a-z0-9_]+)\}/g, function (_, k) {
        if (k === "motor") return motorNome;
        return par[k] ? fmtParam(par[k].valor) : "";
    });

    return txt;
}

/* ---------------- avaliação de um motor ---------------- */
function avaliarMotor(equip, canaisDoEquip, medidasBrutas) {

    const motorNome = equip.nome;
    const perfil = CFG.perfis[equip.perfil];
    const par = perfil.parametros;

    let msgs = { criticos: [], atencao_alta: [], atencao: [], avisos: [], informativos: [] };
    let acoes = [];
    let nivelMax = 0;

    // Canal de cada papel, para consultar integridade por papel.
    let canalDoPapel = {};
    canaisDoEquip.forEach(function (c) { canalDoPapel[c.papel] = c.id; });

    let idPress = canalDoPapel["pressao_oleo_lub"];
    let estPress = idPress ? estadoCanal(idPress) : "OK";
    let pressInoperante = estPress === "INOPERANTE";
    let pressSuspeita = estPress === "SUSPEITO";

    // Cópia de trabalho: canal inoperante deixa de ter leitura.
    let medidas = {};
    Object.keys(medidasBrutas).forEach(function (k) { medidas[k] = medidasBrutas[k]; });

    if (pressInoperante) {
        medidas["pressao_oleo_lub"] = NaN;
        medidas["taxa_pressao_oleo_lub"] = NaN;
    }

    function add(nivel, lista, texto) {
        msgs[lista].push(texto);
        if (nivel > nivelMax) nivelMax = nivel;
    }

    function addComTeto(nivel, lista, texto, canalTeto) {
        let suspeito = false;
        if (canalTeto) {
            let id = canalDoPapel[canalTeto];
            suspeito = id ? (estadoCanal(id) === "SUSPEITO") : false;
        }
        let n = (suspeito && nivel > 3) ? 3 : nivel;
        let alvo = lista;
        if (n !== nivel) {
            alvo = "atencao";
            texto = texto + " Observação: o canal de pressão está sob suspeita de falha, a severidade foi limitada a ATENÇÃO. Confirmar pelo manômetro local.";
        }
        add(n, alvo, texto);
    }

    function acao(prioridade, titulo, detalhe, responsavel) {
        acoes.push({
            motor: motorNome,
            prioridade: prioridade,
            titulo: titulo,
            detalhe: detalhe,
            responsavel: responsavel || "Encarregado de Máquinas"
        });
    }

    /* ---- estado operacional ---- */
    let rpm = valorDe(medidas, "rotacao");
    let rpmValido = isFinite(rpm);
    let motorParado = !rpmValido || (par.rpm_parado && rpm < par.rpm_parado.valor);

    let estado = null;
    for (let i = 0; i < perfil.estados.length; i++) {
        let e = perfil.estados[i];
        if (condVerdadeira(e.quando, medidas, par)) { estado = e; break; }
    }
    if (!estado) estado = perfil.estados[perfil.estados.length - 1];

    /* ---- contexto de aplicação ---- */
    let contexto;
    if (!rpmValido) contexto = "SEM_RPM";
    else if (motorParado) contexto = "MOTOR_PARADO";
    else contexto = "MOTOR_GIRANDO";

    /* ---- regras ---- */
    CFG.regras.regras.forEach(function (r) {
        if (r.aplica_em !== contexto) return;

        // Papel exigido e ausente: regra pulada, sem erro.
        if (r.requer && r.requer.length) {
            let falta = r.requer.some(function (p) { return !isFinite(valorDe(medidas, p)); });
            if (falta) return;
        }

        if (!condVerdadeira(r.condicao, medidas, par)) return;

        let texto = renderizar(r.texto, par, medidas, motorNome);

        if (r.texto_extra && condVerdadeira(r.texto_extra.quando, medidas, par)) {
            texto = texto + renderizar(r.texto_extra.texto, par, medidas, motorNome);
        }

        if (r.teto_por_canal) addComTeto(r.nivel, r.lista, texto, r.teto_por_canal);
        else add(r.nivel, r.lista, texto);

        if (r.acao) {
            acao(r.acao.prioridade,
                 renderizar(r.acao.titulo, par, medidas, motorNome),
                 renderizar(r.acao.detalhe, par, medidas, motorNome),
                 r.acao.responsavel);
        }
    });

    /* ---- pendências de instrumentação (nunca crítico) ---- */
    let pendencias = [];
    ["temp_oleo_lub", "temp_agua_doce", "pressao_oleo_lub", "rotacao"].forEach(function (papel) {
        let id = canalDoPapel[papel];
        if (!id) return;
        let est = estadoCanal(id);
        if (est === "OK") return;
        let q = qualidade.canais[id];
        pendencias.push({ canal: id, rotulo: q.rotulo, estado: est, motivo: q.motivo, desde: q.desde_hora });

        if (est === "INOPERANTE") {
            add(2, "avisos", "INSTRUMENTAÇÃO — " + q.rotulo + ": canal inoperante desde " + q.desde_hora +
                ". Regras de alarme deste canal suspensas. " + (q.motivo || ""));
            acao("ROTINA", "Substituir o transdutor de " + q.rotulo,
                 "Canal fora de serviço. Enquanto não for substituído, acompanhar o parâmetro pelo indicador local e registrar nas rondas. Providenciar sobressalente e registrar a intervenção para excluir o período do histórico estatístico.",
                 "Encarregado de Máquinas / Eletricista de bordo");
        } else {
            add(2, "avisos", "INSTRUMENTAÇÃO — " + q.rotulo + ": leitura sob suspeita há " + q.minutos +
                " min. " + (q.motivo || "") + " Severidade limitada enquanto não houver confirmação.");
            acao("ROTINA", "Conferir " + q.rotulo + " pelo indicador local",
                 "Leitura suspeita de falha de canal. Uma confirmação em serviço resolve a dúvida em menos de cinco minutos e evita tanto alarme falso quanto falha mascarada.");
        }
    });

    let pressOleo = valorDe(medidas, "pressao_oleo_lub");

    return {
        motor: motorNome,
        estado: estado.id,
        estado_texto: estado.texto,
        severidade: NIVEIS[nivelMax],
        severidade_texto: ROTULO_SEV[NIVEIS[nivelMax]] || NIVEIS[nivelMax],
        nivel: nivelMax,
        rpm: rpm,
        temp_oleo_c: valorDe(medidas, "temp_oleo_lub"),
        temp_agua_c: valorDe(medidas, "temp_agua_doce"),
        press_oleo_bar: pressInoperante ? null : pressOleo,
        pressao_valida: !pressInoperante,
        pressao_suspeita: pressSuspeita,
        taxa_oleo_c_min: valorDe(medidas, "taxa_temp_oleo_lub"),
        taxa_agua_c_min: valorDe(medidas, "taxa_temp_agua_doce"),
        taxa_pressao_bar_min: valorDe(medidas, "taxa_pressao_oleo_lub"),
        taxa_rpm_min: valorDe(medidas, "taxa_rotacao"),
        pendencias_instrumentacao: pendencias,
        redutora: {
            status: "PENDENTE",
            mensagem: "Sem sensor disponível após o remapeamento dos canais. Monitoramento pendente de novo hardware/canal."
        },
        criticos: msgs.criticos,
        atencao_alta: msgs.atencao_alta,
        atencao: msgs.atencao,
        avisos: msgs.avisos,
        informativos: msgs.informativos,
        acoes: acoes
    };
}

/* ---------------- montagem das medidas por equipamento ---------------- */
const PAPEL_TAXA_GLOBAL = {
    "MCP_BB": {
        temp_oleo_lub: "taxa_temp_oleo_bb_c_min",
        temp_agua_doce: "taxa_temp_agua_bb_c_min",
        pressao_oleo_lub: "taxa_pressao_oleo_bb_bar_min",
        rotacao: "taxa_rpm_bb_rpm_min"
    },
    "MCP_BE": {
        temp_oleo_lub: "taxa_temp_oleo_be_c_min",
        temp_agua_doce: "taxa_temp_agua_be_c_min",
        pressao_oleo_lub: "taxa_pressao_oleo_be_bar_min",
        rotacao: "taxa_rpm_be_rpm_min"
    }
};

function medidasDe(equipId, canaisDoEquip) {
    let m = {};
    canaisDoEquip.forEach(function (c) {
        m[c.papel] = Number(global.get(c.id));
        let gTaxa = (PAPEL_TAXA_GLOBAL[equipId] || {})[c.papel];
        if (gTaxa) m["taxa_" + c.papel] = Number(global.get(gTaxa));
    });
    return m;
}

let timestamp = new Date().toISOString();

let porEquip = {};
CFG.instalacao.canais.forEach(function (c) {
    if (!porEquip[c.equipamento]) porEquip[c.equipamento] = [];
    porEquip[c.equipamento].push(c);
});

let equipBB = CFG.instalacao.equipamentos.find(function (e) { return e.id === "MCP_BB"; });
let equipBE = CFG.instalacao.equipamentos.find(function (e) { return e.id === "MCP_BE"; });

let diagBB = avaliarMotor(equipBB, porEquip["MCP_BB"] || [], medidasDe("MCP_BB", porEquip["MCP_BB"] || []));
let diagBE = avaliarMotor(equipBE, porEquip["MCP_BE"] || [], medidasDe("MCP_BE", porEquip["MCP_BE"] || []));


function rankOf(label) { return NIVEIS.indexOf(label); }

let rankBB = rankOf(diagBB.severidade);
let rankBE = rankOf(diagBE.severidade);
let rankGeral = Math.max(rankBB, rankBE);

let motoresNoNivel = [];
if (rankBB === rankGeral) motoresNoNivel.push("MCP BB");
if (rankBE === rankGeral) motoresNoNivel.push("MCP BE");

let mensagensGerais = [];
if (NIVEIS[rankGeral] === "CRITICO") {
    if (rankBB === rankGeral) diagBB.criticos.forEach(function (m) { mensagensGerais.push("MCP BB: " + m); });
    if (rankBE === rankGeral) diagBE.criticos.forEach(function (m) { mensagensGerais.push("MCP BE: " + m); });
} else if (NIVEIS[rankGeral] === "ATENCAO_ALTA") {
    if (rankBB === rankGeral) diagBB.atencao_alta.forEach(function (m) { mensagensGerais.push("MCP BB: " + m); });
    if (rankBE === rankGeral) diagBE.atencao_alta.forEach(function (m) { mensagensGerais.push("MCP BE: " + m); });
}

/* ---------------- enlace Modbus ---------------- */
let com = global.get("status_comunicacao") || { nivel: 3, status_comunicacao: "SEM DADOS", alarme: true, segundos_sem_leitura: null };
let dadosObsoletos = (com.nivel === undefined) ? true : com.nivel >= 2;

/* V13.1: SEM DADOS logo após o arranque é informativo. Passada a janela sem
   nenhuma leitura, volta a valer ATENÇÃO (porta serial ocupada, cabo solto). */
const JANELA_ARRANQUE_S = 120;
let t0Arranque = context.get("t0_arranque");
if (t0Arranque === undefined || t0Arranque === null) { t0Arranque = Date.now(); context.set("t0_arranque", t0Arranque); }
const semDadosInicial = (com.status_comunicacao === "SEM DADOS") && ((Date.now() - t0Arranque) < JANELA_ARRANQUE_S * 1000);

let acoesSistema = [];

if (com.nivel >= 1) {
    let texto = semDadosInicial
        ? "Enlace ainda sem dados desde a inicialização. Aguardando a primeira leitura válida; isso, isoladamente, é informativo."
        : ((com.nivel >= 2)
            ? "Enlace Modbus sem resposta há " + (com.segundos_sem_leitura || "?") + " s. Valores exibidos são a última leitura recebida e não representam a condição atual dos motores. Verificar conversor, cabo RS485 e alimentação do módulo."
            : "Enlace Modbus instável. Leituras chegando fora do período esperado. Verificar cabo, terminação e aterramento do barramento.");
    mensagensGerais.unshift("COMUNICAÇÃO: " + texto);

    let rankComunicacao = semDadosInicial
        ? NIVEIS.indexOf("INFORMATIVO")
        : ((com.nivel >= 2) ? NIVEIS.indexOf("ATENCAO") : NIVEIS.indexOf("AVISO"));
    if (rankComunicacao > rankGeral) {
        rankGeral = rankComunicacao;
        motoresNoNivel = ["Sistema"];
    }

    acoesSistema.push({
        motor: "Sistema",
        prioridade: (com.nivel >= 2 && !semDadosInicial) ? "ALTA" : "ROTINA",
        titulo: "Restabelecer o enlace de dados",
        detalhe: "Enlace " + com.status_comunicacao + ". Enquanto não normalizar, os indicadores não refletem a condição atual dos motores. Conferir conversor USB/RS485, cabo, terminação e alimentação do AMVIF08. O botão de reinício da porta na aba Sistema tenta a recuperação sem intervenção física.",
        responsavel: "Operador de serviço"
    });
}

if (com.interrupcoes_hoje && com.interrupcoes_hoje >= 3) {
    acoesSistema.push({
        motor: "Sistema",
        prioridade: "ALTA",
        titulo: "Investigar a recorrência de quedas do enlace",
        detalhe: "Foram registradas " + com.interrupcoes_hoje + " interrupções hoje. Recorrência com necessidade de reconexão física do USB indica conversor sem isolação galvânica, gerenciamento de energia do USB ativo no Windows ou driver instável. O arquivo enlace_falhas.csv traz os horários para correlação.",
        responsavel: "Imediato / Eletricista de bordo"
    });
}

let severidadeGeral = NIVEIS[rankGeral];

/* ---------------- consolidação de recomendações ---------------- */
const ORDEM_PRIORIDADE = { "IMEDIATA": 0, "ALTA": 1, "ROTINA": 2 };

let recomendacoes = []
    .concat(diagBB.acoes, diagBE.acoes, acoesSistema)
    .sort(function (a, b) { return ORDEM_PRIORIDADE[a.prioridade] - ORDEM_PRIORIDADE[b.prioridade]; });

// remove duplicidade exata de título
let vistos = {};
recomendacoes = recomendacoes.filter(function (r) {
    let k = r.prioridade + "|" + r.titulo;
    if (vistos[k]) return false;
    vistos[k] = true;
    return true;
});

if (recomendacoes.length === 0) {
    recomendacoes.push({
        motor: "—",
        prioridade: "ROTINA",
        titulo: "Nenhuma ação pendente",
        detalhe: "Todos os parâmetros monitorados dentro das faixas de referência e instrumentação íntegra. Manter a rotina normal de rondas e o registro no livro de máquinas.",
        responsavel: "Operador de serviço"
    });
}

global.set("recomendacoes", recomendacoes);
global.set("diagnostico_mcp_bb", diagBB);
global.set("diagnostico_mcp_be", diagBE);
global.set("estado_motor_mcp_bb", diagBB.estado);
global.set("estado_motor_mcp_be", diagBE.estado);
global.set("severidade_mcp_bb", diagBB.severidade);
global.set("severidade_mcp_be", diagBE.severidade);
global.set("severidade_geral", severidadeGeral);

msg.payload = {
    timestamp: timestamp,
    hora_local: new Date().toLocaleTimeString("pt-BR"),
    data_local: new Date().toLocaleDateString("pt-BR"),
    bb: diagBB,
    be: diagBE,
    comunicacao: {
        status: com.status_comunicacao,
        nivel: com.nivel === undefined ? 3 : com.nivel,
        alarme: !!com.alarme,
        segundos_sem_leitura: com.segundos_sem_leitura,
        dados_obsoletos: dadosObsoletos
    },
    instrumentacao: {
        inoperantes: qualidade.inoperantes || [],
        suspeitos: qualidade.suspeitos || [],
        ha_pendencia: !!qualidade.ha_pendencia
    },
    recomendacoes: recomendacoes,
    geral: {
        severidade: severidadeGeral,
        severidade_texto: ROTULO_SEV[severidadeGeral] || severidadeGeral,
        motores: motoresNoNivel,
        mensagens: mensagensGerais,
        dados_obsoletos: dadosObsoletos
    }
};

node.status({ fill: rankGeral >= 5 ? "red" : (rankGeral >= 3 ? "yellow" : "green"), shape: "dot", text: severidadeGeral });

return msg;

/* ============================================================
   NEREUS v12 - HORÍMETRO MCP BB e MCP BE
   ------------------------------------------------------------
   O QUE MUDOU E POR QUÊ

   Até a v6 este nó era a fonte da verdade do horímetro: contava
   segundos em memória enquanto a rotação estivesse acima de 200 RPM.
   Contexto em memória zera a cada deploy — e no dia 18/08/2026 houve
   dezesseis deploys. O relatório daquele dia publicou 0,27 h de
   operação para um dia com 9,45 h de motor girando.

   Agora a fonte da verdade é o registro em disco. O script
   C:\Dados_Motor\nereus_horimetro.js apura, de cada CSV diário,
   quantas horas cada motor girou, integrando o tempo real entre
   amostras, e grava o resultado em nereus_estado.json. O fluxo de
   consolidação roda esse script a cada 15 minutos e devolve o estado
   para cá pelo tópico "estado".

   Este nó passou a fazer só duas coisas:
     1. somar os segundos decorridos desde a última consolidação, para
        que o painel não fique parado entre uma apuração e outra;
     2. publicar o conjunto (acumulado + dia + parcial) para o painel,
        para o CSV e para os relatórios.

   Consequência prática: um deploy no meio do dia custa, no máximo, os
   minutos desde a última consolidação — e mesmo esses voltam na
   apuração seguinte, porque saem do próprio CSV.
   ============================================================ */

const RPM_PARADO = 200;

/* ---- entrada de estado, vinda do fluxo de consolidação ---- */
if (msg.topic === "estado") {
    let e = msg.payload;
    if (e && e.acumulado) {
        context.set("estado", e);
        context.set("estadoEm", Date.now());
        /* O estado recém-apurado já cobre tudo o que está no CSV, então
           a contagem parcial recomeça do zero. É isso que impede a
           soma em dobro entre o script e este contador. */
        context.set("parcialBB", 0);
        context.set("parcialBE", 0);
        node.status({ fill: "green", shape: "dot", text: "estado " + (e.acumulado.bb_h) + " / " + (e.acumulado.be_h) + " h" });
    }
    return null;
}

/* ---- pulso periódico ---- */
let rpmBB = Number(global.get("ch4"));
let rpmBE = Number(global.get("ch8"));

let com = global.get("status_comunicacao") || {};
let enlaceCaiu = (com.nivel !== undefined && com.nivel >= 2);

let motorBBLigado = !enlaceCaiu && isFinite(rpmBB) && rpmBB >= RPM_PARADO;
let motorBELigado = !enlaceCaiu && isFinite(rpmBE) && rpmBE >= RPM_PARADO;

let agora = Date.now();
let ultimoTempo = context.get("ultimoTempo");
let parcialBB = Number(context.get("parcialBB")) || 0;
let parcialBE = Number(context.get("parcialBE")) || 0;

if (ultimoTempo !== undefined) {
    let dt = (agora - ultimoTempo) / 1000;
    if (dt > 0 && dt < 60) {
        if (motorBBLigado) parcialBB += dt;
        if (motorBELigado) parcialBE += dt;
    }
}
context.set("ultimoTempo", agora);
context.set("parcialBB", parcialBB);
context.set("parcialBE", parcialBE);

let estado = context.get("estado") || null;
let estadoEm = context.get("estadoEm") || null;
let hoje = new Date().toISOString().slice(0, 10);

function h(x) { return Number((x).toFixed(2)); }

let apuradoBB = 0, apuradoBE = 0, diaApuradoBB = 0, diaApuradoBE = 0;
if (estado) {
    apuradoBB = Number(estado.acumulado.bb_h) || 0;
    apuradoBE = Number(estado.acumulado.be_h) || 0;
    let d = (estado.dias || {})[hoje];
    if (d) { diaApuradoBB = Number(d.horas_bb) || 0; diaApuradoBE = Number(d.horas_be) || 0; }
}

let saida = {
    /* horímetro de vida do motor */
    bb_total_h: h(apuradoBB + parcialBB / 3600),
    be_total_h: h(apuradoBE + parcialBE / 3600),
    /* horas do dia corrente */
    bb_dia_h: h(diaApuradoBB + parcialBB / 3600),
    be_dia_h: h(diaApuradoBE + parcialBE / 3600),
    /* parcela ainda não consolidada, útil para diagnóstico */
    bb_parcial_min: h(parcialBB / 60),
    be_parcial_min: h(parcialBE / 60),
    bb_ligado: motorBBLigado,
    be_ligado: motorBELigado,
    base: estado ? estado.base : null,
    apurado_em: estadoEm ? new Date(estadoEm).toLocaleTimeString("pt-BR") : null,
    calibrado: !!(estado && estado.base && estado.base.data),
    consolidado: !!estado,
    enlace: com.status_comunicacao || "SEM DADOS",
    disponibilidade_pct: com.disponibilidade_pct === undefined ? null : com.disponibilidade_pct,
    interrupcoes_hoje: com.interrupcoes_hoje || 0,
    indisponivel_total_min: com.indisponivel_total_min || 0,
    hora_local: new Date().toLocaleTimeString("pt-BR")
};

/* Compatibilidade: o nó de gravação do CSV e os relatórios continuam
   lendo estas chaves. O que mudou é o significado — passaram a ser o
   horímetro de vida, não mais o contador da sessão. */
global.set("horimetro_mcp_bb_h", saida.bb_total_h);
global.set("horimetro_mcp_be_h", saida.be_total_h);
global.set("horimetro_dia_mcp_bb_h", saida.bb_dia_h);
global.set("horimetro_dia_mcp_be_h", saida.be_dia_h);
global.set("horimetro", saida);

if (!estado) {
    node.status({ fill: "yellow", shape: "ring", text: "sem consolidação — rodar nereus_horimetro.js" });
}

msg.payload = saida;
msg.topic = "Horímetro MCP BB / MCP BE";
return msg;

/* Alimenta os gráficos de tendência.
   Saída 1: temperaturas | Saída 2: pressões | Saída 3: rotações
   Canal classificado como inoperante não alimenta o gráfico: linha reta
   sobre valor morto polui a leitura da tendência do canal íntegro. */

let q = global.get("qualidade_canais") || { canais: {} };
function vivo(id) {
    return !(q.canais && q.canais[id] && q.canais[id].estado === "INOPERANTE");
}
function ponto(topico, id) {
    if (!vivo(id)) return null;
    let v = Number(global.get(id));
    if (!isFinite(v)) return null;
    return { topic: topico, payload: v };
}

let temperaturas = [
    ponto("Óleo BB", "ch1"), ponto("Água BB", "ch2"),
    ponto("Óleo BE", "ch5"), ponto("Água BE", "ch6")
].filter(Boolean);

let pressoes = [ponto("Pressão BB", "ch3"), ponto("Pressão BE", "ch7")].filter(Boolean);
let rotacoes = [ponto("RPM BB", "ch4"), ponto("RPM BE", "ch8")].filter(Boolean);

return [temperaturas, pressoes, rotacoes];

/* ============================================================
   NEREUS v6 - GRAVAÇÃO DO HISTÓRICO EM CSV
   ------------------------------------------------------------
   Regras mantidas da v5:
   - em falha de enlace a linha continua sendo gravada, para
     preservar a linha do tempo, mas com os campos de medição
     vazios. Gravar valor congelado por horas contamina média,
     desvio e qualquer detector de anomalia treinado depois.

   Acréscimos da v6:
   - colunas de integridade da instrumentação. Assim o relatório
     sabe, por linha, quais canais estavam fora de serviço, e o
     período correspondente pode ser excluído da estatística sem
     depender da memória de quem operou.
   - coluna de disponibilidade do enlace.
   - canal inoperante grava campo vazio em vez de zero. Zero é um
     valor; vazio é ausência de medição. A diferença importa.
   ============================================================ */

var separador = ";";

function doisDigitos(n) {
    return n < 10 ? "0" + n : "" + n;
}

var agoraArquivo = new Date();
var anoArq = agoraArquivo.getFullYear();
var mesArq = doisDigitos(agoraArquivo.getMonth() + 1);
var diaArq = doisDigitos(agoraArquivo.getDate());

msg.filename = "C:\\Dados_Motor\\motor_diesel_" + anoArq + "-" + mesArq + "-" + diaArq + ".csv";

function dataHoraAtual() {
    var agora = new Date();
    return agora.getFullYear() + "-" + doisDigitos(agora.getMonth() + 1) + "-" + doisDigitos(agora.getDate()) +
        " " + doisDigitos(agora.getHours()) + ":" + doisDigitos(agora.getMinutes()) + ":" + doisDigitos(agora.getSeconds());
}

function numero(valor, casas) {
    var n = Number(valor);
    if (!isFinite(n)) return "";
    return n.toFixed(casas);
}

function campoTexto(valor) {
    return '"' + String(valor === undefined || valor === null ? "" : valor).replace(/"/g, '""') + '"';
}

function juntar(lista) {
    return Array.isArray(lista) ? lista.join(" | ") : "";
}

var com = global.get("status_comunicacao") || {};
var enlaceCaiu = (com.nivel !== undefined && com.nivel >= 2);
var statusCom = com.status_comunicacao || "SEM DADOS";

var qual = global.get("qualidade_canais") || { canais: {}, inoperantes: [], suspeitos: [] };
function canalMorto(id) {
    return qual.canais && qual.canais[id] && qual.canais[id].estado === "INOPERANTE";
}

var valores = {
    ch1: global.get("ch1"), ch2: global.get("ch2"), ch3: global.get("ch3"), ch4: global.get("ch4"),
    ch5: global.get("ch5"), ch6: global.get("ch6"), ch7: global.get("ch7"), ch8: global.get("ch8")
};

if (valores.ch1 === undefined && valores.ch2 === undefined && valores.ch3 === undefined && valores.ch4 === undefined &&
    valores.ch5 === undefined && valores.ch6 === undefined && valores.ch7 === undefined && valores.ch8 === undefined) {
    return null;
}

var diagBB = global.get("diagnostico_mcp_bb") || {};
var diagBE = global.get("diagnostico_mcp_be") || {};
var severidadeGeral = global.get("severidade_geral") || "";

var horimetroBB = global.get("horimetro_mcp_bb_h");
var horimetroBE = global.get("horimetro_mcp_be_h");

var recomendacoes = global.get("recomendacoes") || [];
var recomendacaoTopo = recomendacoes.length ? (recomendacoes[0].prioridade + ": " + recomendacoes[0].titulo) : "";

var cabecalho = [
    "DataHora",
    "Temp_OL_BB_C", "Temp_Agua_BB_C", "Pressao_OL_BB_bar", "Rotacao_MCP_BB_RPM",
    "Temp_OL_BE_C", "Temp_Agua_BE_C", "Pressao_OL_BE_bar", "Rotacao_MCP_BE_RPM",
    "Estado_BB", "Severidade_BB", "Criticos_BB", "Atencao_Alta_BB", "Atencao_BB", "Avisos_BB", "Informativos_BB",
    "Estado_BE", "Severidade_BE", "Criticos_BE", "Atencao_Alta_BE", "Atencao_BE", "Avisos_BE", "Informativos_BE",
    "Horimetro_BB_h", "Horimetro_BE_h",
    "Taxa_Temp_OL_BB_C_min", "Taxa_Temp_Agua_BB_C_min", "Taxa_Pressao_OL_BB_bar_min", "Taxa_RPM_BB_rpm_min",
    "Taxa_Temp_OL_BE_C_min", "Taxa_Temp_Agua_BE_C_min", "Taxa_Pressao_OL_BE_bar_min", "Taxa_RPM_BE_rpm_min",
    "Severidade_Geral", "Status_Comunicacao",
    "Canais_Inoperantes", "Canais_Suspeitos", "Disponibilidade_Enlace_pct", "Recomendacao_Prioritaria"
].join(separador);

var ordem = ["ch1", "ch2", "ch3", "ch4", "ch5", "ch6", "ch7", "ch8"];
var casas = [2, 2, 2, 0, 2, 2, 2, 0];

var medicoes = ordem.map(function (id, i) {
    if (enlaceCaiu) return "";
    if (canalMorto(id)) return "";
    return numero(valores[id], casas[i]);
});

var linha = [campoTexto(dataHoraAtual())]
    .concat(medicoes)
    .concat([
        campoTexto(enlaceCaiu ? "SEM DADOS" : (diagBB.estado || "")), campoTexto(enlaceCaiu ? "" : (diagBB.severidade || "")),
        campoTexto(juntar(diagBB.criticos)), campoTexto(juntar(diagBB.atencao_alta)), campoTexto(juntar(diagBB.atencao)),
        campoTexto(juntar(diagBB.avisos)), campoTexto(juntar(diagBB.informativos)),
        campoTexto(enlaceCaiu ? "SEM DADOS" : (diagBE.estado || "")), campoTexto(enlaceCaiu ? "" : (diagBE.severidade || "")),
        campoTexto(juntar(diagBE.criticos)), campoTexto(juntar(diagBE.atencao_alta)), campoTexto(juntar(diagBE.atencao)),
        campoTexto(juntar(diagBE.avisos)), campoTexto(juntar(diagBE.informativos)),
        numero(horimetroBB, 2), numero(horimetroBE, 2),
        numero(global.get("taxa_temp_oleo_bb_c_min"), 2), numero(global.get("taxa_temp_agua_bb_c_min"), 2),
        numero(global.get("taxa_pressao_oleo_bb_bar_min"), 3), numero(global.get("taxa_rpm_bb_rpm_min"), 0),
        numero(global.get("taxa_temp_oleo_be_c_min"), 2), numero(global.get("taxa_temp_agua_be_c_min"), 2),
        numero(global.get("taxa_pressao_oleo_be_bar_min"), 3), numero(global.get("taxa_rpm_be_rpm_min"), 0),
        campoTexto(severidadeGeral), campoTexto(statusCom),
        campoTexto(juntar(qual.inoperantes)), campoTexto(juntar(qual.suspeitos)),
        numero(com.disponibilidade_pct, 1), campoTexto(recomendacaoTopo)
    ])
    .join(separador);

var ultimoArquivo = context.get("ultimoArquivo");
var cabecalhoGravado = context.get("cabecalhoGravado") || false;

if (ultimoArquivo !== msg.filename) {
    cabecalhoGravado = false;
    context.set("ultimoArquivo", msg.filename);
}

if (!cabecalhoGravado) {
    msg.payload = cabecalho + "\r\n" + linha + "\r\n";
    context.set("cabecalhoGravado", true);
} else {
    msg.payload = linha + "\r\n";
}

return msg;

/* ============================================================
   NEREUS v6 - PREPARAÇÃO DO RELATÓRIO
   ------------------------------------------------------------
   Define o CSV de origem e o tipo de documento a ser produzido.

   Entrada aceita:
     msg.payload = "hoje" | "ontem" | "AAAA-MM-DD"
     msg.payload = { tipo: "tecnico"|"comando", dia: "hoje"|"ontem"|"AAAA-MM-DD" }
     msg.tipoRelatorio = "tecnico" | "comando"

   tecnico : relatório completo, destinado ao Chefe de Máquinas
   comando : sumário executivo de uma página, destinado ao Comandante
   ============================================================ */

const PASTA = "C:\\Dados_Motor\\";

function dois(n) { return n < 10 ? "0" + n : "" + n; }

let p = msg.payload;
let tipo = msg.tipoRelatorio || "tecnico";
let pedido = "hoje";

if (p && typeof p === "object") {
    if (p.tipo) tipo = String(p.tipo);
    if (p.dia) pedido = String(p.dia);
} else if (p !== undefined && p !== null && String(p).trim() !== "") {
    pedido = String(p).trim();
}

if (tipo !== "comando") tipo = "tecnico";

let alvo = new Date();
if (pedido === "ontem") {
    alvo = new Date(alvo.getTime() - 86400000);
} else if (/^\d{4}-\d{2}-\d{2}$/.test(pedido)) {
    let d = pedido.split("-");
    alvo = new Date(Number(d[0]), Number(d[1]) - 1, Number(d[2]), 12, 0, 0);
}

let dataRef = alvo.getFullYear() + "-" + dois(alvo.getMonth() + 1) + "-" + dois(alvo.getDate());
let base = (tipo === "comando" ? "NEREUS_sumario_comando_" : "NEREUS_relatorio_tecnico_") + dataRef;

msg.tipoRelatorio = tipo;
msg.dataRef = dataRef;
msg.arquivoCsv = PASTA + "motor_diesel_" + dataRef + ".csv";
msg.arquivoHtml = PASTA + base + ".html";
msg.arquivoPdf = PASTA + base + ".pdf";
global.set("relatorio_em_andamento", { tipo: tipo, data: dataRef, html: msg.arquivoHtml, pdf: msg.arquivoPdf });
msg.filename = msg.arquivoCsv;

node.status({ fill: "blue", shape: "dot", text: tipo + " · " + dataRef });

return msg;

/* ============================================================
   NEREUS v6 - MONTAGEM DOS RELATÓRIOS EM HTML
   ------------------------------------------------------------
   Entrada : msg.payload      conteúdo do CSV do dia (texto)
             msg.dataRef      AAAA-MM-DD
             msg.tipoRelatorio "tecnico" | "comando"
             msg.arquivoHtml  caminho de saída
   Saída   : msg.payload = HTML pronto, msg.filename = arquivoHtml

   tecnico : documento completo para o Chefe de Máquinas, com
             estatística, gráficos, integridade da instrumentação,
             disponibilidade do enlace e ocorrências.
   comando : uma página para o Comandante, com semáforo, números
             do dia, pendências e recomendações.

   Os gráficos são SVG desenhados aqui. Nenhuma biblioteca externa,
   nenhuma dependência de internet.
   ============================================================ */

const MAX_PONTOS = 400;
const LOGO = "";
const RPM_MIN_OPERANDO = 200;
const ORDEM_SEV = ["NORMAL", "INFORMATIVO", "AVISO", "ATENCAO", "ATENCAO_ALTA", "CRITICO"];
const ROTULO_SEV = {
    NORMAL: "NORMAL", INFORMATIVO: "INFORMATIVO", AVISO: "AVISO",
    ATENCAO: "ATENÇÃO", ATENCAO_ALTA: "ATENÇÃO ALTA", CRITICO: "CRÍTICO"
};
const ROTULO_ESTADO = {
    "SEM DADOS": "Sem dados", PARADO: "Parado",
    AQUECIMENTO_INICIAL: "Aquecimento inicial",
    AQUECIMENTO_PROGRESSIVO: "Aquecimento progressivo",
    PRONTO_PARA_CARGA: "Pronto para carga",
    REGIME_NORMAL: "Regime normal",
    EM_FUNCIONAMENTO: "Em funcionamento"
};
function rotSev(s) { return ROTULO_SEV[s] || String(s || "—"); }
function rotEstado(s) { return ROTULO_ESTADO[s] || String(s || "—"); }
/* Número em português: vírgula decimal. */
function dec(v, casas) { return isFinite(v) ? Number(v).toFixed(casas).replace(".", ",") : "—"; }

let tipo = msg.tipoRelatorio === "comando" ? "comando" : "tecnico";

const ocorrenciasHistoricas = Array.isArray(msg.payload) ? msg.payload : [];
let texto = msg.csvRelatorio;
if (Buffer.isBuffer(texto)) texto = texto.toString("utf8");
if (typeof texto !== "string" || texto.trim().length === 0) {
    node.status({ fill: "yellow", shape: "ring", text: "CSV vazio: " + msg.dataRef });
    msg.reportError = "O CSV diário está vazio ou não pôde ser lido para " + msg.dataRef + ".";
    return [null, msg];
}

/* ---------------- parser CSV com aspas ---------------- */
function parseCsv(txt, sep) {
    let linhas = [];
    let campo = "";
    let linha = [];
    let dentroAspas = false;

    for (let i = 0; i < txt.length; i++) {
        let c = txt[i];
        if (dentroAspas) {
            if (c === '"') {
                if (txt[i + 1] === '"') { campo += '"'; i++; }
                else { dentroAspas = false; }
            } else { campo += c; }
        } else if (c === '"') {
            dentroAspas = true;
        } else if (c === sep) {
            linha.push(campo); campo = "";
        } else if (c === "\n") {
            linha.push(campo); campo = "";
            if (linha.length > 1 || linha[0] !== "") linhas.push(linha);
            linha = [];
        } else if (c !== "\r") {
            campo += c;
        }
    }
    linha.push(campo);
    if (linha.length > 1 || linha[0] !== "") linhas.push(linha);
    return linhas;
}

let linhas = parseCsv(texto, ";");
if (linhas.length < 2) {
    node.warn("NEREUS: CSV de " + msg.dataRef + " sem linhas de dados.");
    msg.reportError = "O CSV diário de " + msg.dataRef + " não contém linhas de dados.";
    return [null, msg];
}

let cab = linhas[0];
let idx = {};
cab.forEach(function (nome, i) { idx[nome.trim()] = i; });

function num(linha, coluna) {
    let i = idx[coluna];
    if (i === undefined) return NaN;
    let v = String(linha[i]).trim().replace(",", ".");
    if (v === "") return NaN;
    let n = Number(v);
    return isFinite(n) ? n : NaN;
}
function txt(linha, coluna) {
    let i = idx[coluna];
    return i === undefined ? "" : String(linha[i]).trim();
}
function minutosDoDia(s) {
    let m = /(\d{2}):(\d{2}):(\d{2})/.exec(s);
    if (!m) return NaN;
    return Number(m[1]) * 60 + Number(m[2]) + Number(m[3]) / 60;
}

/* ---------------- carga dos registros ---------------- */
let regs = [];
for (let i = 1; i < linhas.length; i++) {
    let L = linhas[i];
    if (L.length < 5) continue;
    let t = minutosDoDia(txt(L, "DataHora"));
    if (!isFinite(t)) continue;

    regs.push({
        t: t,
        hora: txt(L, "DataHora").slice(11, 19),
        oleoBB: num(L, "Temp_OL_BB_C"),
        aguaBB: num(L, "Temp_Agua_BB_C"),
        pressBB: num(L, "Pressao_OL_BB_bar"),
        rpmBB: num(L, "Rotacao_MCP_BB_RPM"),
        oleoBE: num(L, "Temp_OL_BE_C"),
        aguaBE: num(L, "Temp_Agua_BE_C"),
        pressBE: num(L, "Pressao_OL_BE_bar"),
        rpmBE: num(L, "Rotacao_MCP_BE_RPM"),
        estadoBB: txt(L, "Estado_BB"),
        estadoBE: txt(L, "Estado_BE"),
        sevBB: txt(L, "Severidade_BB"),
        sevBE: txt(L, "Severidade_BE"),
        sevGeral: txt(L, "Severidade_Geral"),
        critBB: txt(L, "Criticos_BB"),
        critBE: txt(L, "Criticos_BE"),
        aaBB: txt(L, "Atencao_Alta_BB"),
        aaBE: txt(L, "Atencao_Alta_BE"),
        atBB: txt(L, "Atencao_BB"),
        atBE: txt(L, "Atencao_BE"),
        horBB: num(L, "Horimetro_BB_h"),
        horBE: num(L, "Horimetro_BE_h"),
        com: txt(L, "Status_Comunicacao"),
        inop: txt(L, "Canais_Inoperantes"),
        susp: txt(L, "Canais_Suspeitos")
    });
}

if (regs.length === 0) {
    node.warn("NEREUS: nenhum registro válido em " + msg.dataRef);
    msg.reportError = "O CSV diário de " + msg.dataRef + " não contém amostras válidas; não foi possível montar o relatório.";
    return [null, msg];
}

/* ---------------- base de tempo real (v12) ----------------
   Antes desta versão o tempo de cada condição era estimado por
   "número de amostras x intervalo nominal", e o intervalo nominal era o
   período total dividido pelo número de amostras. Isso errava por dois
   motivos: um deploy redispara o inject e grava duas amostras no mesmo
   segundo, e toda parada do Node-RED entrava na conta como se fosse
   intervalo de amostragem.

   Agora: amostra duplicada é descartada e cada amostra recebe o intervalo
   real até a seguinte, limitado a LACUNA_MAX_S. Intervalo maior que isso
   é período sem supervisão e não é creditado a nenhuma condição nem a
   nenhum motor. */
const LACUNA_MAX_S = 60;

regs.sort(function (a, b) { return a.t - b.t; });
let regsUnicos = [];
for (let i = 0; i < regs.length; i++) {
    /* De um par gravado no mesmo segundo fica a ÚLTIMA linha: no
       instante do deploy a primeira ainda sai com o valor anterior do
       canal, e é a segunda que carrega a leitura fresca. É também o
       critério usado por nereus_horimetro.js, para que os dois cheguem
       ao mesmo número sobre o mesmo arquivo. */
    if (i < regs.length - 1 && Math.abs(regs[i + 1].t - regs[i].t) < 1e-9) continue;
    regsUnicos.push(regs[i]);
}
let amostrasDuplicadas = regs.length - regsUnicos.length;
regs = regsUnicos;

let listaDt = [];
for (let i = 0; i < regs.length - 1; i++) {
    let d = (regs[i + 1].t - regs[i].t) * 60;
    regs[i].dt = (d > 0 && d <= LACUNA_MAX_S) ? d : 0;
    if (regs[i].dt > 0) listaDt.push(regs[i].dt);
}
listaDt.sort(function (a, b) { return a - b; });
let intervaloMediano = listaDt.length ? listaDt[Math.floor(listaDt.length / 2)] : 10;
regs[regs.length - 1].dt = intervaloMediano;

let somaDt = regs.reduce(function (a, r) { return a + (r.dt || 0); }, 0);

/* ---------------- estatística ---------------- */
function estat(valores) {
    let v = valores.filter(function (x) { return isFinite(x); }).sort(function (a, b) { return a - b; });
    if (v.length === 0) return null;
    let soma = v.reduce(function (a, b) { return a + b; }, 0);
    return {
        n: v.length,
        min: v[0],
        max: v[v.length - 1],
        media: soma / v.length,
        p95: v[Math.min(v.length - 1, Math.floor(v.length * 0.95))],
        mediana: v[Math.floor(v.length / 2)]
    };
}

let operBB = regs.filter(function (r) { return isFinite(r.rpmBB) && r.rpmBB >= RPM_MIN_OPERANDO; });
let operBE = regs.filter(function (r) { return isFinite(r.rpmBE) && r.rpmBE >= RPM_MIN_OPERANDO; });

function serie(lista, campo) { return lista.map(function (r) { return r[campo]; }); }

let stats = [
    { grupo: "MCP BB", param: "Temperatura do óleo", un: "°C", ref: "66 a 76", campo: "oleoBB", e: estat(serie(operBB, "oleoBB")), lim: [66, 76] },
    { grupo: "MCP BB", param: "Temperatura da água doce", un: "°C", ref: "65 a 75", campo: "aguaBB", e: estat(serie(operBB, "aguaBB")), lim: [65, 75] },
    { grupo: "MCP BB", param: "Pressão do óleo", un: "bar", ref: "≥ 4,2", campo: "pressBB", e: estat(serie(operBB, "pressBB")), lim: [4.2, 99] },
    { grupo: "MCP BB", param: "Rotação", un: "RPM", ref: "—", campo: "rpmBB", e: estat(serie(operBB, "rpmBB")), lim: null },
    { grupo: "MCP BE", param: "Temperatura do óleo", un: "°C", ref: "66 a 76", campo: "oleoBE", e: estat(serie(operBE, "oleoBE")), lim: [66, 76] },
    { grupo: "MCP BE", param: "Temperatura da água doce", un: "°C", ref: "65 a 75", campo: "aguaBE", e: estat(serie(operBE, "aguaBE")), lim: [65, 75] },
    { grupo: "MCP BE", param: "Pressão do óleo", un: "bar", ref: "≥ 4,2", campo: "pressBE", e: estat(serie(operBE, "pressBE")), lim: [4.2, 99] },
    { grupo: "MCP BE", param: "Rotação", un: "RPM", ref: "—", campo: "rpmBE", e: estat(serie(operBE, "rpmBE")), lim: null }
];

/* ---------------- horímetro do período (v12) ----------------
   ERRO CORRIGIDO: até a v6 as horas do período saíam da coluna
   Horimetro_BB_h do CSV, pela diferença entre o último e o primeiro
   valor, e quando essa diferença dava zero ou negativa a função
   devolvia o ÚLTIMO valor do contador. Como o contador vivia em
   memória e zerava a cada deploy, o relatório de 18/08/2026 publicou
   0,27 h de operação para um dia com 9,45 h de motor girando — e o
   sumário, gerado dois minutos depois, publicou 18 min, porque leu o
   mesmo contador dois minutos mais tarde.

   O contador deixou de ser fonte da verdade. As horas do período são
   apuradas aqui, integrando o tempo real entre amostras com rotação
   igual ou acima de RPM_MIN_OPERANDO. O mesmo cálculo, sobre o mesmo
   arquivo, é feito por C:\\Dados_Motor\\nereus_horimetro.js, o que
   permite conferir o número do relatório fora do Node-RED. */
function horasOperando(campoRpm) {
    let s = 0;
    regs.forEach(function (r) {
        if (isFinite(r[campoRpm]) && r[campoRpm] >= RPM_MIN_OPERANDO) s += (r.dt || 0);
    });
    return s / 3600;
}
let horasBB = horasOperando("rpmBB");
let horasBE = horasOperando("rpmBE");

/* Intervalo médio efetivo: a soma dos pesos de todas as amostras é
   exatamente o tempo coberto pelo registro, então contagem x intervalo
   volta a ser uma estimativa consistente de tempo. */
let intervaloS = regs.length ? (somaDt / regs.length) : 0;
function tempoMin(qtdAmostras) { return (qtdAmostras * intervaloS) / 60; }

/* Horímetro acumulado do motor (vida). Vem do estado apurado por
   nereus_horimetro.js e publicado em global pelo fluxo de consolidação.
   Sem esse estado, cai para o último valor da coluna do CSV, que ao
   menos indica ordem de grandeza, e a origem é declarada no documento. */
function ultimoFinito(campo) {
    for (let i = regs.length - 1; i >= 0; i--) {
        if (isFinite(regs[i][campo])) return regs[i][campo];
    }
    return null;
}
let estadoHor = global.get("nereus_estado") || null;
let acumuladoBB = estadoHor && estadoHor.acumulado ? estadoHor.acumulado.bb_h : ultimoFinito("horBB");
let acumuladoBE = estadoHor && estadoHor.acumulado ? estadoHor.acumulado.be_h : ultimoFinito("horBE");
let acumuladoOrigem = estadoHor && estadoHor.acumulado
    ? ("apurado dos registros diários" + (estadoHor.base && estadoHor.base.data ? ", calibrado em " + estadoHor.base.data.split("-").reverse().join("/") : ""))
    : "contador do fluxo, sem calibração";
let manut = global.get("nereus_manutencao") || null;

function contaSev(lista, campo) {
    let c = {};
    ORDEM_SEV.forEach(function (s) { c[s] = 0; });
    lista.forEach(function (r) { if (c[r[campo]] !== undefined) c[r[campo]]++; });
    return c;
}
let sevBB = contaSev(regs, "sevBB");
let sevBE = contaSev(regs, "sevBE");
let sevGeral = contaSev(regs, "sevGeral");

let piorSev = "NORMAL";
regs.forEach(function (r) {
    if (ORDEM_SEV.indexOf(r.sevGeral) > ORDEM_SEV.indexOf(piorSev)) piorSev = r.sevGeral;
});

function coletar(lista, campos) {
    let mapa = {};
    lista.forEach(function (r) {
        campos.forEach(function (c) {
            let bruto = r[c];
            if (!bruto) return;
            bruto.split(" | ").forEach(function (m) {
                let k = m.trim();
                if (!k) return;
                if (!mapa[k]) mapa[k] = { n: 0, primeira: r.hora, ultima: r.hora };
                mapa[k].n++;
                mapa[k].ultima = r.hora;
            });
        });
    });
    return Object.keys(mapa).map(function (k) {
        return { msg: k, n: mapa[k].n, primeira: mapa[k].primeira, ultima: mapa[k].ultima };
    }).sort(function (a, b) { return b.n - a.n; });
}
let ocorrBB = coletar(regs, ["critBB", "aaBB", "atBB"]);
let ocorrBE = coletar(regs, ["critBE", "aaBE", "atBE"]);

function contaEstado(lista, campo) {
    let c = {};
    lista.forEach(function (r) { let k = r[campo] || "—"; c[k] = (c[k] || 0) + 1; });
    return Object.keys(c).map(function (k) { return { estado: k, n: c[k] }; })
        .sort(function (a, b) { return b.n - a.n; });
}

/* ---------------- integridade da instrumentação ---------------- */
const ROTULO_CANAL = {
    ch1: "Temperatura do óleo MCP BB", ch2: "Temperatura da água MCP BB",
    ch3: "Pressão do óleo MCP BB", ch4: "Rotação MCP BB",
    ch5: "Temperatura do óleo MCP BE", ch6: "Temperatura da água MCP BE",
    ch7: "Pressão do óleo MCP BE", ch8: "Rotação MCP BE"
};
const CAMPO_CANAL = {
    ch1: "oleoBB", ch2: "aguaBB", ch3: "pressBB", ch4: "rpmBB",
    ch5: "oleoBE", ch6: "aguaBE", ch7: "pressBE", ch8: "rpmBE"
};

let marcados = {};
regs.forEach(function (r) {
    [["inop", "INOPERANTE"], ["susp", "SUSPEITO"]].forEach(function (par) {
        let campo = r[par[0]];
        if (!campo) return;
        campo.split(" | ").forEach(function (c) {
            let k = c.trim();
            if (!k) return;
            if (!marcados[k]) marcados[k] = { estado: par[1], n: 0, primeira: r.hora, ultima: r.hora };
            if (par[1] === "INOPERANTE") marcados[k].estado = "INOPERANTE";
            marcados[k].n++;
            marcados[k].ultima = r.hora;
        });
    });
});

// heurística de reserva, para arquivos gravados antes da v6
function sensorTravado(lista, campo) {
    let v = lista.map(function (r) { return r[campo]; }).filter(function (x) { return isFinite(x); });
    if (v.length < 10) return null;
    let mn = Math.min.apply(null, v), mx = Math.max.apply(null, v);
    return (mx - mn) < 0.01 ? v[0] : null;
}

let instrumentacao = [];
Object.keys(ROTULO_CANAL).forEach(function (id) {
    let m = marcados[id];
    let travado = sensorTravado(regs, CAMPO_CANAL[id]);
    if (m) {
        instrumentacao.push({
            canal: id, rotulo: ROTULO_CANAL[id], estado: m.estado,
            tempo: tempoMin(m.n), primeira: m.primeira, ultima: m.ultima,
            nota: m.estado === "INOPERANTE"
                ? "Canal fora de serviço. Regras de alarme suspensas no período; medições não gravadas."
                : "Leitura sob suspeita. Severidade limitada a ATENÇÃO no período."
        });
    } else if (travado !== null) {
        instrumentacao.push({
            canal: id, rotulo: ROTULO_CANAL[id], estado: "SUSPEITO",
            tempo: tempoMin(regs.length), primeira: regs[0].hora, ultima: regs[regs.length - 1].hora,
            nota: "Leitura constante em " + dec(travado, 2) + " durante todo o período. Indício de canal em falha, não de condição do equipamento."
        });
    }
});

/* ---------------- disponibilidade do enlace ---------------- */
let nominalS = intervaloMediano > 0 ? intervaloMediano : 10;
let lacunas = [];
for (let i = 1; i < regs.length; i++) {
    let dtS = (regs[i].t - regs[i - 1].t) * 60;
    if (dtS > nominalS * 3 && dtS > 30) {
        lacunas.push({ de: regs[i - 1].hora, ate: regs[i].hora, s: dtS });
    }
}
let regsSemCom = regs.filter(function (r) { return r.com && r.com !== "COMUNICAÇÃO NORMAL"; });
let tempoSemComMin = tempoMin(regsSemCom.length);
let tempoLacunasMin = lacunas.reduce(function (a, b) { return a + b.s; }, 0) / 60;
let interrupcoes = lacunas.length + (regsSemCom.length > 0 ? 1 : 0);
let cobertoMin = (regs[regs.length - 1].t - regs[0].t);
let indisponivelMin = tempoSemComMin + tempoLacunasMin;
let disponibilidade = cobertoMin > 0 ? Math.max(0, Math.min(100, 100 * (1 - indisponivelMin / cobertoMin))) : 100;

/* ---------------- recomendações do período ---------------- */
let recomendacoes = [];
function rec(prioridade, titulo, detalhe) {
    if (recomendacoes.some(function (r) { return r.titulo === titulo; })) return;
    recomendacoes.push({ prioridade: prioridade, titulo: titulo, detalhe: detalhe });
}

if (sevGeral.CRITICO > 0) {
    rec("IMEDIATA", "Apurar as condições críticas registradas",
        "O sistema permaneceu " + dec(tempoMin(sevGeral.CRITICO), 0) + " min em severidade CRÍTICA. Confrontar as ocorrências desta seção com o livro de máquinas e registrar a providência adotada.");
}
if (sevGeral.ATENCAO_ALTA > 0) {
    rec("ALTA", "Acompanhar as condições de atenção alta",
        "Registrados " + dec(tempoMin(sevGeral.ATENCAO_ALTA), 0) + " min em ATENÇÃO ALTA. Verificar se houve correlação com regime de carga ou manobra.");
}
instrumentacao.forEach(function (i) {
    if (i.estado === "INOPERANTE") {
        rec("ALTA", "Substituir o transdutor: " + i.rotulo,
            "Canal fora de serviço no período. Enquanto não for substituído, o parâmetro deve ser acompanhado pelo indicador local e registrado nas rondas. Registrar a data da substituição para excluir o período anterior do histórico estatístico.");
    } else {
        rec("ROTINA", "Confirmar em serviço: " + i.rotulo,
            "Leitura com assinatura de falha de canal. Uma conferência pelo indicador local resolve a dúvida e evita tanto alarme falso quanto falha mascarada.");
    }
});
if (interrupcoes >= 3 || disponibilidade < 98) {
    rec("ALTA", "Tratar a estabilidade do enlace de dados",
        "Disponibilidade de " + dec(disponibilidade, 1) + "% com " + interrupcoes + " interrupção(ões) e " +
        dec(indisponivelMin, 0) + " min sem aquisição. Período sem dados é período sem supervisão. Ver o arquivo enlace_falhas.csv para os horários e a seção de manutenção do sistema.");
}
stats.forEach(function (s) {
    if (!s.e || !s.lim) return;
    if (s.e.max > s.lim[1] && s.lim[1] < 90) {
        rec("ALTA", s.param + " acima da referência no " + s.grupo,
            "Máximo de " + dec(s.e.max, 2) + " " + s.un + " contra referência de " + s.ref + " " + s.un + ". Verificar o sistema correspondente e o regime aplicado.");
    }
    if (s.lim[1] === 99 && s.e.min < s.lim[0]) {
        rec("ALTA", s.param + " abaixo da referência no " + s.grupo,
            "Mínimo de " + dec(s.e.min, 2) + " " + s.un + " contra referência de " + s.ref + " " + s.un + ".");
    }
});
if (recomendacoes.length === 0) {
    rec("ROTINA", "Manter a rotina normal",
        "Todos os parâmetros permaneceram nas faixas de referência, instrumentação íntegra e enlace estável no período. Nenhuma ação corretiva decorre deste relatório.");
}
const ORDEM_PRIO = { IMEDIATA: 0, ALTA: 1, ROTINA: 2 };
/* Manutenção programada: rotinas vencidas, rotinas próximas do
   vencimento e rotinas cujo efeito não apareceu nos parâmetros entram
   na mesma lista de recomendações, com a mesma escala de prioridade. */
if (manut && Array.isArray(manut.recomendacoes)) {
    manut.recomendacoes.forEach(function (r) {
        rec(r.prioridade === "IMEDIATA" ? "IMEDIATA" : (r.prioridade === "ALTA" ? "ALTA" : "ROTINA"),
            r.titulo, r.detalhe);
    });
}

recomendacoes.sort(function (a, b) { return ORDEM_PRIO[a.prioridade] - ORDEM_PRIO[b.prioridade]; });

/* ---------------- gráficos SVG ---------------- */
function reamostrar(lista, campo) {
    let pts = [];
    let passo = Math.max(1, Math.ceil(lista.length / MAX_PONTOS));
    for (let i = 0; i < lista.length; i += passo) {
        let bloco = lista.slice(i, i + passo).map(function (r) { return r[campo]; })
            .filter(function (x) { return isFinite(x); });
        if (bloco.length === 0) continue;
        let media = bloco.reduce(function (a, b) { return a + b; }, 0) / bloco.length;
        pts.push({ t: lista[i].t, v: media });
    }
    return pts;
}

function esc(s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function grafico(titulo, unidade, series, faixas, yForcado, naoNegativo, altura) {
    const W = 980, H = altura || 300;
    const ML = 62, MR = 18, MT = 34, MB = 40;
    const PW = W - ML - MR, PH = H - MT - MB;

    let todos = [];
    series.forEach(function (s) { s.pts.forEach(function (p) { todos.push(p.v); }); });
    if (todos.length === 0) {
        return '<div class="grafico-vazio">' + esc(titulo) + ': sem dados no período.</div>';
    }

    let ymin = Math.min.apply(null, todos);
    let ymax = Math.max.apply(null, todos);
    if (yForcado) { ymin = Math.min(ymin, yForcado[0]); ymax = Math.max(ymax, yForcado[1]); }
    if (faixas) faixas.forEach(function (f) { ymin = Math.min(ymin, f.de); ymax = Math.max(ymax, f.ate); });
    let span = (ymax - ymin) || 1;
    ymin -= span * 0.08; ymax += span * 0.08;
    if (naoNegativo && ymin < 0) ymin = 0;

    let tmin = 0, tmax = 1440;
    let tsAll = [];
    series.forEach(function (s) { s.pts.forEach(function (p) { tsAll.push(p.t); }); });
    if (tsAll.length > 0) {
        tmin = Math.max(0, Math.min.apply(null, tsAll) - 5);
        tmax = Math.min(1440, Math.max.apply(null, tsAll) + 5);
        if (tmax - tmin < 30) { tmax = tmin + 30; }
    }

    function X(t) { return ML + ((t - tmin) / (tmax - tmin)) * PW; }
    function Y(v) { return MT + PH - ((v - ymin) / (ymax - ymin)) * PH; }

    let svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" width="100%" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg">';
    svg += '<rect x="' + ML + '" y="' + MT + '" width="' + PW + '" height="' + PH + '" fill="#ffffff" stroke="#c9d3de"/>';

    if (faixas) {
        faixas.forEach(function (f) {
            let y1 = Y(Math.min(f.ate, ymax)), y2 = Y(Math.max(f.de, ymin));
            svg += '<rect x="' + ML + '" y="' + y1.toFixed(1) + '" width="' + PW + '" height="' + Math.max(0, y2 - y1).toFixed(1) + '" fill="' + f.cor + '" opacity="0.16"/>';
        });
    }

    let divisoes = 5;
    for (let g = 0; g <= divisoes; g++) {
        let v = ymin + (ymax - ymin) * (g / divisoes);
        let y = Y(v);
        svg += '<line x1="' + ML + '" y1="' + y.toFixed(1) + '" x2="' + (ML + PW) + '" y2="' + y.toFixed(1) + '" stroke="#e4eaf0"/>';
        svg += '<text x="' + (ML - 8) + '" y="' + (y + 4).toFixed(1) + '" text-anchor="end" font-size="11" fill="#5a6b7c">' + v.toFixed(v > 100 ? 0 : 1) + '</text>';
    }

    let passoH = (tmax - tmin) > 480 ? 120 : ((tmax - tmin) > 180 ? 60 : 30);
    for (let t = Math.ceil(tmin / passoH) * passoH; t <= tmax; t += passoH) {
        let x = X(t);
        svg += '<line x1="' + x.toFixed(1) + '" y1="' + MT + '" x2="' + x.toFixed(1) + '" y2="' + (MT + PH) + '" stroke="#e4eaf0"/>';
        let hh = Math.floor(t / 60), mm = Math.round(t % 60);
        svg += '<text x="' + x.toFixed(1) + '" y="' + (MT + PH + 16) + '" text-anchor="middle" font-size="11" fill="#5a6b7c">' +
            (hh < 10 ? "0" : "") + hh + ":" + (mm < 10 ? "0" : "") + mm + '</text>';
    }

    series.forEach(function (s) {
        if (s.pts.length === 0) return;
        let d = "";
        s.pts.forEach(function (p, i) {
            d += (i === 0 ? "M" : "L") + X(p.t).toFixed(1) + " " + Y(p.v).toFixed(1) + " ";
        });
        svg += '<path d="' + d + '" fill="none" stroke="' + s.cor + '" stroke-width="1.6" stroke-linejoin="round"/>';
    });

    svg += '<text x="' + ML + '" y="20" font-size="13" font-weight="600" fill="#0d2b45">' + esc(titulo) + ' (' + esc(unidade) + ')</text>';
    let lx = ML + 300;
    series.forEach(function (s) {
        svg += '<rect x="' + lx + '" y="10" width="14" height="4" fill="' + s.cor + '"/>';
        svg += '<text x="' + (lx + 20) + '" y="16" font-size="11" fill="#3c4d5e">' + esc(s.nome) + '</text>';
        lx += 24 + (s.nome.length * 6.4);
    });
    svg += '<text x="' + (ML + PW) + '" y="' + (MT + PH + 32) + '" text-anchor="end" font-size="10" fill="#8595a4">hora local</text>';
    svg += '</svg>';
    return svg;
}

