/* ---------------- utilidades de texto ---------------- */
function fmt(v, casas) { return isFinite(v) ? v.toFixed(casas).replace(".", ",") : "—"; }
function foraDeFaixa(e, lim) {
    if (!e || !lim) return false;
    /* lim[1] === 99 marca parâmetro com limite de MÍNIMO (pressão).
       Nos demais o que interessa é o excesso: temperatura baixa no
       aquecimento é condição esperada, não desvio. */
    if (lim[1] === 99) return e.min < lim[0];
    return e.max > lim[1];
}
function horasTexto(h) {
    if (!isFinite(h) || h <= 0) return "não operou";
    let hh = Math.floor(h);
    let mm = Math.round((h - hh) * 60);
    return hh + " h " + (mm < 10 ? "0" : "") + mm + " min";
}

