/* Quadro completo de manutenção programada, para o relatório técnico. */
function tabelaManutencao() {
    if (!manut || !Array.isArray(manut.itens) || manut.itens.length === 0) {
        return '<p class="ok">Catálogo de rotinas ainda não cadastrado. Preencher ' +
            'C:\\Dados_Motor\\manutencao_rotinas.csv para que esta seção passe a ser emitida.</p>';
    }
    let pill = { "VENCIDA": "p-CRITICO", "PROXIMA": "p-ATENCAO", "EM_DIA": "p-NORMAL",
                 "SEM_REGISTRO": "p-AVISO", "CARTAO": "p-INFORMATIVO" };
    let linhas = manut.itens.map(function (i) {
        let destaque = (i.situacao === "VENCIDA") ? ' class="fora"' : '';
        let falta = i.horas_faltam_h === null ? "—" :
            (i.horas_faltam_h <= 0 ? "vencida há " + dec(Math.abs(i.horas_faltam_h), 1) + " h" : dec(i.horas_faltam_h, 1) + " h");
        let prev = i.previsao_dias === null ? "—" : "≈ " + i.previsao_dias + " dia(s)";
        return '<tr' + destaque + '><td>' + esc(i.id) + '</td><td>' + esc(i.rotina) + '</td>' +
            '<td>' + esc(i.motor) + '</td>' +
            '<td class="n">' + (i.periodicidade_h ? dec(i.periodicidade_h, 0) + " h" : (i.periodicidade_dias ? i.periodicidade_dias + " d" : "—")) + '</td>' +
            '<td class="n">' + (i.ultima_execucao || "sem registro") + '</td>' +
            '<td class="n">' + (i.ultimo_horimetro_h === null ? "—" : dec(i.ultimo_horimetro_h, 1)) + '</td>' +
            '<td class="n">' + (i.horas_desde_h === null ? "—" : dec(i.horas_desde_h, 1)) + '</td>' +
            '<td class="n">' + falta + '</td><td class="n">' + prev + '</td>' +
            '<td class="n"><span class="pill ' + (pill[i.situacao] || "p-AVISO") + '">' + (i.situacao_texto || i.situacao) + '</span></td></tr>';
    }).join("");
    return '<table><thead><tr><th>ID</th><th>Rotina</th><th>Motor</th><th class="n">Periodicidade</th>' +
        '<th class="n">Última</th><th class="n">Horímetro</th><th class="n">Desde</th>' +
        '<th class="n">Falta</th><th class="n">Previsão</th><th class="n">Situação</th></tr></thead><tbody>' +
        linhas + '</tbody></table>';
}

/* Efeito medido das rotinas executadas sobre os parâmetros do motor. */
function tabelaEfeitos() {
    if (!manut || !Array.isArray(manut.efeitos) || manut.efeitos.length === 0) return "";
    let linhas = manut.efeitos.map(function (f) {
        let cor = f.conclusao === "MELHOROU" ? "p-NORMAL" :
            (f.conclusao === "PIOROU" ? "p-CRITICO" : (f.conclusao === "SEM_MUDANCA" ? "p-AVISO" : "p-INFORMATIVO"));
        return '<tr><td class="n">' + (f.data || "—").split("-").reverse().join("/") + '</td><td>' + esc(f.id_rotina) + '</td>' +
            '<td>MCP ' + esc(f.motor) + '</td><td>' + esc(f.rotulo) + '</td>' +
            '<td class="n">' + (f.antes === undefined ? "—" : dec(f.antes, 2)) + '</td>' +
            '<td class="n">' + (f.depois === undefined ? "—" : dec(f.depois, 2)) + '</td>' +
            '<td class="n">' + (f.delta === undefined ? "—" : dec(f.delta, 2)) + '</td>' +
            '<td class="n"><span class="pill ' + cor + '">' + (f.conclusao_texto || f.conclusao) + '</span></td></tr>';
    }).join("");
    return '<h3>Efeito das rotinas executadas</h3>' +
        '<p style="margin:0 0 5px 0;color:#4a5c6e">Mediana de cada parâmetro em regime de carga (rotação igual ou acima de 700 RPM) nos três dias anteriores e nos três dias posteriores à execução. Diferença abaixo do ruído próprio do canal é declarada como sem mudança mensurável: o sistema não afirma melhora que os dados não sustentam.</p>' +
        '<table><thead><tr><th class="n">Data</th><th>Rotina</th><th>Motor</th><th>Parâmetro</th>' +
        '<th class="n">Antes</th><th class="n">Depois</th><th class="n">Δ</th><th class="n">Conclusão</th></tr></thead><tbody>' +
        linhas + '</tbody></table>';
}

/* Resumo de uma linha, para o sumário ao Comando. */
function resumoManutencao() {
    if (!manut || !manut.resumo) return "";
    let r = manut.resumo;
    let criticos = manut.itens.filter(function (i) { return i.situacao === "VENCIDA" || i.situacao === "PROXIMA"; }).slice(0, 4);
    let linhas = criticos.map(function (i) {
        return '<tr><td>' + esc(i.rotina) + '</td><td>MCP ' + esc(i.motor) + '</td>' +
            '<td class="n">' + (i.horas_faltam_h === null ? "—" :
                (i.horas_faltam_h <= 0 ? "vencida" : dec(i.horas_faltam_h, 0) + " h")) + '</td>' +
            '<td class="n">' + (i.previsao_dias === null ? "—" : "≈ " + i.previsao_dias + " dia(s)") + '</td>' +
            '<td class="n"><span class="pill ' + (i.situacao === "VENCIDA" ? "p-CRITICO" : "p-ATENCAO") + '">' + i.situacao + '</span></td></tr>';
    }).join("");
    if (!linhas) {
        return '<h2>Manutenção programada</h2><p class="ok">Nenhuma rotina vencida ou próxima do vencimento. ' +
            r.em_dia + ' rotina(s) em dia' + (r.sem_registro ? ', ' + r.sem_registro + ' sem registro de execução' : '') + '.</p>';
    }
    return '<h2>Manutenção programada</h2>' +
        '<table><thead><tr><th>Rotina</th><th>Motor</th><th class="n">Falta</th><th class="n">Previsão</th><th class="n">Situação</th></tr></thead><tbody>' +
        linhas + '</tbody></table>';
}

function blocoAcoes(lista, limite) {
    let itens = lista.slice(0, limite || lista.length).map(function (r) {
        return '<li class="prioridade-' + r.prioridade + '"><span class="prio prio-' + r.prioridade + '">' + r.prioridade + '</span>' +
            '<b>' + esc(r.titulo) + '</b>' + esc(r.detalhe) + '</li>';
    }).join("");
    return '<ul class="acoes">' + itens + '</ul>';
}

let html;

/* Ocorrências cadastradas manualmente no Registro Histórico do NEREUS. */
function renderHistoricoDetalhado() {
    if (!ocorrenciasHistoricas.length) {
        return '<h2>10. Registro histórico de ocorrências e anomalias</h2><p class="ok">Nenhuma ocorrência histórica cadastrada para esta data.</p>';
    }
    let cards = ocorrenciasHistoricas.map(function (r) {
        let descricao = esc(String(r.descricao || 'Sem descrição registrada.')).replace(/\r?\n/g, '<br>');
        return '<div class="hist-card" style="border:1px solid #cbd6df;border-radius:5px;padding:9px 11px;margin:7px 0;page-break-inside:avoid">' +
            '<h3 style="margin:0 0 7px 0">' + esc(r.titulo || 'Ocorrência sem título') + ' <span style="font-size:9px;color:#607583">(ID ' + esc(r.id) + ')</span></h3>' +
            '<table class="mini"><tbody>' +
            '<tr><th style="width:22%">Equipamento</th><td>' + esc(r.equipamento || '—') + '</td><th style="width:15%">Data/hora</th><td>' + esc(r.data_hora || '—') + '</td></tr>' +
            '<tr><th>Status</th><td>' + esc(r.status || 'Pendente') + '</td><th>Autor</th><td>' + esc(r.autor || '—') + '</td></tr>' +
            '<tr><th>Descrição completa</th><td colspan="3">' + descricao + '</td></tr>' +
            '<tr><th>Última atualização</th><td colspan="3">' + esc(r.data_atualizacao || '—') + '</td></tr>' +
            '</tbody></table></div>';
    }).join('');
    return '<h2>10. Registro histórico de ocorrências e anomalias (' + ocorrenciasHistoricas.length + ')</h2>' + cards;
}

function renderHistoricoCompacto() {
    if (!ocorrenciasHistoricas.length) {
        return '<h2>Ocorrências históricas</h2><p class="ok">Nenhuma ocorrência histórica registrada nesta data.</p>';
    }
    let linhas = ocorrenciasHistoricas.map(function (r) {
        return '<tr><td>' + esc(r.titulo || '—') + '</td><td class="n">' + esc(r.data_hora || '—') + '</td><td>' + esc(r.equipamento || '—') + '</td></tr>';
    }).join('');
    return '<h2>Ocorrências históricas (' + ocorrenciasHistoricas.length + ')</h2>' +
        '<table class="hist-compact" style="font-size:8px;width:100%;border-collapse:collapse"><thead><tr><th>Título da ocorrência</th><th>Data/hora</th><th>Equipamento</th></tr></thead><tbody>' + linhas + '</tbody></table>';
}

/* ============================================================
   SUMÁRIO EXECUTIVO — COMANDANTE
   ============================================================ */
if (tipo === "comando") {

    let gResumo = grafico("Temperatura do óleo lubrificante", "°C",
        [{ nome: "MCP BB", cor: AZUL, pts: reamostrar(regs, "oleoBB") },
         { nome: "MCP BE", cor: LARANJA, pts: reamostrar(regs, "oleoBE") }],
        [{ de: 66, ate: 76, cor: VERDE }], null, false, 190);

    let frases = [];
    if (horasBB <= 0 && horasBE <= 0) {
        frases.push("Nenhum dos motores principais operou no período coberto pelo registro.");
    } else {
        frases.push("O MCP BB operou " + horasTexto(horasBB) + " e o MCP BE operou " + horasTexto(horasBE) + " no período de " + periodo + ".");
    }

    if (piorSev === "NORMAL" || piorSev === "INFORMATIVO") {
        frases.push("Todos os parâmetros monitorados permaneceram dentro das faixas de referência.");
    } else if (piorSev === "AVISO") {
        frases.push("A condição mais severa registrada foi de AVISO, sem exigência de providência imediata.");
    } else {
        frases.push("A condição mais severa registrada foi " + rotSev(piorSev) +
            ", acumulando " + fmt(tempoMin((sevGeral[piorSev] || 0)), 0) + " min nesse nível.");
    }

    if (instrumentacao.length > 0) {
        frases.push("Há " + instrumentacao.length + " canal(is) de medição com pendência de manutenção, listados abaixo. " +
            "A pendência é do instrumento, não do equipamento, e os parâmetros correspondentes seguem sendo acompanhados pelos indicadores locais.");
    }

    if (manut && manut.resumo && (manut.resumo.vencidas > 0 || manut.resumo.proximas > 0)) {
        frases.push("Da manutenção programada, " + manut.resumo.vencidas + " rotina(s) estão vencidas e " +
            manut.resumo.proximas + " se aproximam do vencimento, considerando o horímetro acumulado de " +
            dec(acumuladoBB, 0) + " h no MCP BB e " + dec(acumuladoBE, 0) + " h no MCP BE.");
    }

    if (disponibilidade < 99) {
        frases.push("O enlace de aquisição de dados esteve disponível " + dec(disponibilidade, 1) +
            "% do período, com " + interrupcoes + " interrupção(ões). Intervalos sem aquisição correspondem a intervalos sem registro automático, e não a anormalidade dos motores.");
    } else {
        frases.push("O sistema de aquisição operou de forma contínua, com disponibilidade de " + dec(disponibilidade, 1) + "%.");
    }

    let linhasResumo = stats.filter(function (s) {
        return s.e && s.lim;
    }).map(function (s) {
        let e = s.e;
        let alerta = foraDeFaixa(e, s.lim);
        let casas = s.un === "RPM" ? 0 : 2;
        let situacao = alerta ? '<span class="pill p-ATENCAO">fora da faixa</span>' : '<span class="pill p-NORMAL">na faixa</span>';
        let extremo = (s.lim[1] === 99) ? fmt(e.min, casas) + " (mínimo)" : fmt(e.max, casas) + " (máximo)";
        return '<tr' + (alerta ? ' class="fora"' : '') + '><td>' + s.grupo + '</td><td>' + s.param + '</td>' +
            '<td class="n">' + fmt(e.media, casas) + '</td><td class="n">' + extremo + '</td>' +
            '<td class="n">' + s.ref + ' ' + s.un + '</td><td class="n">' + situacao + '</td></tr>';
    }).join("");

    let blocoPendencias = instrumentacao.length === 0
        ? '<p class="ok">Nenhuma pendência de instrumentação no período.</p>'
        : '<table><thead><tr><th>Canal</th><th>Situação</th><th>Consequência prática</th></tr></thead><tbody>' +
          instrumentacao.map(function (i) {
              return '<tr><td>' + esc(i.rotulo) + '</td><td><span class="pill p-' +
                  (i.estado === "INOPERANTE" ? "ATENCAO" : "AVISO") + '">' + i.estado + '</span></td><td>' + esc(i.nota) + '</td></tr>';
          }).join("") + '</tbody></table>';

    html = '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8">' +
        '<title>NEREUS · Sumário ao Comando ' + dataBr + '</title><style>' + CSS_COMUM +
        '.semaforo { display:flex; align-items:center; gap:12px; border:1px solid #d4dde6; border-radius:8px; padding:7px 12px; margin-bottom:7px; background:#f7fafc; }' +
        '.semaforo .bola { width:24px; height:24px; border-radius:50%; flex:0 0 24px; }' +
        '.semaforo .txt b { font-size:13px; display:block; }' +
        /* Compactação para o documento fechar em uma página A4. */
        'body { font-size:10.5px; }' +
        'header { padding-bottom:6px; margin-bottom:9px; }' +
        'h2 { margin:11px 0 5px 0; }' +
        '.card { padding:5px 9px; }' +
        '.card .val { font-size:15px; }' +
        'td, th { padding:3px 7px; }' +
        '.grafico { padding:3px; margin-bottom:6px; }' +
        'ul.acoes li { padding:5px 9px; margin-bottom:5px; }' +
        '.nota { margin-top:9px; padding:6px 10px; font-size:9px; }' +
        '.assin { margin-top:14px; }' +
        '.assin .linha { margin-top:22px; }' +
        'footer { margin-top:9px; padding-top:4px; }' +
        '</style></head><body>' +

        cabecalhoDoc("Sumário Diário de Supervisão de Máquinas",
            "Documento de apoio à decisão · Destinatário: Comandante") +

        '<div class="semaforo">' +
        '<div class="bola" style="background:' +
            (piorSev === "CRITICO" ? "#c62828" : (piorSev === "ATENCAO_ALTA" ? "#d84315" :
             (piorSev === "ATENCAO" ? "#ef6c00" : (piorSev === "AVISO" ? "#b58900" : "#2e7d32")))) + '"></div>' +
        '<div class="txt"><b>Situação do período: ' + rotSev(piorSev) + '</b>' +
        '<span>' + periodo + ' · ' + regs.length + ' registros automáticos</span></div></div>' +

        '<div class="cards">' +
        '<div class="card"><div class="rot">MCP Bombordo</div><div class="val" style="font-size:13px">' + horasTexto(horasBB) + '</div><div class="un">no período · ' + horasFmt(acumuladoBB) + ' acumuladas</div></div>' +
        '<div class="card"><div class="rot">MCP Boreste</div><div class="val" style="font-size:13px">' + horasTexto(horasBE) + '</div><div class="un">no período · ' + horasFmt(acumuladoBE) + ' acumuladas</div></div>' +
        '<div class="card"><div class="rot">Disponibilidade do sistema</div><div class="val">' + fmt(disponibilidade, 1) + '%</div><div class="un">' + interrupcoes + ' interrupção(ões)</div></div>' +
        '<div class="card"><div class="rot">Pendências abertas</div><div class="val">' + instrumentacao.length + '</div><div class="un">canais de medição</div></div>' +
        '</div>' +

        '<h2>Situação</h2>' +
        '<p style="margin:0 0 6px 0; text-align: justify;">' + frases.map(esc).join(" ") + '</p>' +

        '<h2>Parâmetros do período</h2>' +
        '<table><thead><tr><th>Motor</th><th>Parâmetro</th><th class="n">Média</th><th class="n">Extremo</th><th class="n">Referência</th><th class="n">Situação</th></tr></thead><tbody>' +
        linhasResumo + '</tbody></table>' +

        '<h2>Pendências</h2>' + blocoPendencias +

        renderHistoricoCompacto() +

        resumoManutencao() +

        '<h2>Recomendações</h2>' + blocoAcoes(recomendacoes, 3) +

        '<div class="grafico">' + gResumo + '</div>' +

        '<div class="nota"><b>Natureza do documento.</b> Sumário gerado automaticamente pelo NEREUS a partir da instrumentação auxiliar de bordo, independente dos circuitos de segurança certificados dos motores. Destina-se ao acompanhamento gerencial da condição das máquinas. O detalhamento técnico consta do relatório completo do mesmo dia, à disposição do Chefe de Máquinas.</div>' +

        '<div class="assin"><div class="linha">Chefe de Máquinas</div><div class="linha">Imediato</div></div>' +

        '<footer><span>NEREUS · EDCG Marambaia · Divisão de Máquinas</span><span>Gerado em ' + geradoEm + '</span></footer>' +
        '</body></html>';

/* ============================================================
   RELATÓRIO TÉCNICO — CHEFE DE MÁQUINAS
   ============================================================ */
} else {

    let gTempOleo = grafico("Temperatura do óleo lubrificante", "°C",
        [{ nome: "MCP BB", cor: AZUL, pts: reamostrar(regs, "oleoBB") },
         { nome: "MCP BE", cor: LARANJA, pts: reamostrar(regs, "oleoBE") }],
        [{ de: 66, ate: 76, cor: VERDE }]);

    let gTempAgua = grafico("Temperatura da água doce", "°C",
        [{ nome: "MCP BB", cor: AZUL, pts: reamostrar(regs, "aguaBB") },
         { nome: "MCP BE", cor: LARANJA, pts: reamostrar(regs, "aguaBE") }],
        [{ de: 65, ate: 75, cor: VERDE }]);

    let gPressao = grafico("Pressão do óleo lubrificante", "bar",
        [{ nome: "MCP BB", cor: AZUL, pts: reamostrar(regs, "pressBB") },
         { nome: "MCP BE", cor: LARANJA, pts: reamostrar(regs, "pressBE") }],
        [{ de: 0, ate: 3.0, cor: VERMELHO }], [0, 6], true);

    let gRotacao = grafico("Rotação dos motores", "RPM",
        [{ nome: "MCP BB", cor: AZUL, pts: reamostrar(regs, "rpmBB") },
         { nome: "MCP BE", cor: LARANJA, pts: reamostrar(regs, "rpmBE") }],
        null, [0, 0], true);

    let linhasStats = stats.map(function (s) {
        let e = s.e;
        let alerta = foraDeFaixa(e, s.lim);
        let casas = s.un === "RPM" ? 0 : 2;
        return '<tr' + (alerta ? ' class="fora"' : '') + '>' +
            '<td>' + s.grupo + '</td><td>' + s.param + '</td>' +
            '<td class="n">' + (e ? fmt(e.min, casas) : "—") + '</td>' +
            '<td class="n">' + (e ? fmt(e.media, casas) : "—") + '</td>' +
            '<td class="n">' + (e ? fmt(e.p95, casas) : "—") + '</td>' +
            '<td class="n">' + (e ? fmt(e.max, casas) : "—") + '</td>' +
            '<td class="n">' + s.un + '</td><td class="n">' + s.ref + '</td></tr>';
    }).join("");

    function tabelaSev(c, titulo) {
        let linhasT = ORDEM_SEV.filter(function (s) { return c[s] > 0; }).map(function (s) {
            return '<tr><td><span class="pill p-' + s + '">' + rotSev(s) + '</span></td>' +
                '<td class="n">' + c[s] + '</td><td class="n">' + fmt(tempoMin(c[s]), 0) + ' min</td></tr>';
        }).join("");
        if (!linhasT) linhasT = '<tr><td colspan="3">Sem registros.</td></tr>';
        return '<table class="mini"><thead><tr><th>' + titulo + '</th><th class="n">Amostras</th><th class="n">Tempo</th></tr></thead><tbody>' + linhasT + '</tbody></table>';
    }

    function tabelaOcorr(lista, titulo) {
        if (lista.length === 0) {
            return '<h3>' + titulo + '</h3><p class="ok">Nenhuma ocorrência de atenção ou crítico no período.</p>';
        }
        let linhasT = lista.slice(0, 12).map(function (o) {
            return '<tr><td>' + esc(o.msg) + '</td><td class="n">' + o.n + '</td><td class="n">' +
                fmt(tempoMin(o.n), 0) + ' min</td><td class="n">' + o.primeira + '</td><td class="n">' + o.ultima + '</td></tr>';
        }).join("");
        return '<h3>' + titulo + '</h3><table><thead><tr><th>Mensagem</th><th class="n">Amostras</th><th class="n">Tempo</th><th class="n">1ª</th><th class="n">Última</th></tr></thead><tbody>' + linhasT + '</tbody></table>';
    }

    let estadosBB = contaEstado(regs, "estadoBB").map(function (x) {
        return '<tr><td>' + esc(rotEstado(x.estado)) + '</td><td class="n">' + fmt(tempoMin(x.n), 0) + ' min</td></tr>';
    }).join("");
    let estadosBE = contaEstado(regs, "estadoBE").map(function (x) {
        return '<tr><td>' + esc(rotEstado(x.estado)) + '</td><td class="n">' + fmt(tempoMin(x.n), 0) + ' min</td></tr>';
    }).join("");

    let blocoInstrumentacao = instrumentacao.length === 0
        ? '<p class="ok">Nenhum canal apresentou assinatura de falha de instrumentação no período.</p>'
        : '<div class="aviso"><b>Leia antes da estatística.</b> Os canais abaixo não representam a condição do equipamento no período indicado. Alarmes associados a eles devem ser tratados como pendência de manutenção do sistema de medição, e as amostras correspondentes devem ser excluídas de qualquer análise estatística ou de tendência.</div>' +
          '<table><thead><tr><th>Canal</th><th>Situação</th><th class="n">Tempo</th><th class="n">1ª</th><th class="n">Última</th><th>Observação</th></tr></thead><tbody>' +
          instrumentacao.map(function (i) {
              return '<tr class="fora"><td>' + esc(i.rotulo) + ' <span style="color:#6a7c8e">(' + i.canal + ')</span></td>' +
                  '<td><span class="pill p-' + (i.estado === "INOPERANTE" ? "ATENCAO" : "AVISO") + '">' + i.estado + '</span></td>' +
                  '<td class="n">' + fmt(i.tempo, 0) + ' min</td><td class="n">' + i.primeira + '</td><td class="n">' + i.ultima + '</td>' +
                  '<td>' + esc(i.nota) + '</td></tr>';
          }).join("") + '</tbody></table>';

    let linhasLacunas = lacunas.length === 0
        ? '<tr><td colspan="3">Nenhuma lacuna de aquisição superior a ' + dec(nominalS * 3, 0) + ' s.</td></tr>'
        : lacunas.slice(0, 15).map(function (l) {
            return '<tr><td class="n">' + l.de + '</td><td class="n">' + l.ate + '</td><td class="n">' +
                (l.s < 120 ? dec(l.s, 0) + " s" : dec(l.s / 60, 1) + " min") + '</td></tr>';
        }).join("");

    html = '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8">' +
        '<title>NEREUS · Relatório Técnico ' + dataBr + '</title><style>' + CSS_COMUM + '</style></head><body>' +

        cabecalhoDoc("Relatório Técnico Diário de Supervisão de Máquinas",
            "Motores de propulsão MCP BB e MCP BE · Destinatário: Chefe de Máquinas") +

