   headless. Nada é instalado: o Edge já vem com o Windows. */

const SCRIPT = "C:\\Dados_Motor\\gerar_pdf.bat";

if (!msg.arquivoHtml || !msg.arquivoPdf) {
    msg.reportError = "Caminhos do relatório não foram definidos.";
    return [null, msg];
}

msg.payload = '"' + SCRIPT + '" "' + msg.arquivoHtml + '" "' + msg.arquivoPdf + '"';

msg.relatorio = {
