});

node.status({ fill: "blue", shape: "dot", text: "convertendo " + msg.tipoRelatorio + " " + msg.dataRef });

return [msg, null];

/* Interpreta o retorno do gerar_pdf.bat e alimenta o card da aba Sistema. */

let ultimo = global.get("ultimo_relatorio") || {};
let p = msg.payload;
let codigo;
if (p && typeof p === "object" && p.code !== undefined) codigo = Number(p.code);
else if (typeof p === "number") codigo = p;
else if (msg.rc !== undefined) codigo = Number(msg.rc);
else if (msg.code !== undefined) codigo = Number(msg.code);
else codigo = NaN;
let sucesso = (Number(codigo) === 0);

const EXPLICACAO = {
    "2": "Caminho de entrada ou de saída não informado ao script.",
    "3": "O arquivo HTML não foi encontrado. Verifique se a pasta C:\\Dados_Motor existe e se o Node-RED tem permissão de escrita.",
    "4": "O Microsoft Edge não foi encontrado nos caminhos padrão. Ajuste o caminho dentro do gerar_pdf.bat.",
    "5": "O navegador não produziu o PDF. Feche o arquivo caso esteja aberto no leitor de PDF e tente novamente."
};

let historico = global.get("historico_relatorios") || [];

let saida = {
    tipo: ultimo.tipo || "—",
    data: ultimo.data || "—",
