    gerado_em: new Date().toLocaleString("pt-BR"),
    sucesso: sucesso,
    situacao: sucesso
        ? "PDF gerado com sucesso."
        : ("Falha na conversão (código " + codigo + "). " + (EXPLICACAO[String(codigo)] || "Conferir o painel de debug para a mensagem completa."))
};

historico.unshift({
    tipo: saida.tipo, data: saida.data, quando: saida.gerado_em,
    sucesso: sucesso, arquivo: saida.arquivo
});
while (historico.length > 6) historico.pop();
global.set("historico_relatorios", historico);

saida.historico = historico;
global.set("ultimo_relatorio_status", saida);

node.status({ fill: sucesso ? "green" : "red", shape: "dot", text: saida.situacao.slice(0, 45) });

msg.payload = saida;
return msg;

/* Reúne a situação do sistema para o card da aba Sistema. */

msg.payload = {
    enlace: global.get("status_comunicacao") || {
        porta: "—", status_comunicacao: "SEM DADOS", disponibilidade_pct: null,
        leituras_ok: 0, erros_modbus: 0, interrupcoes_hoje: 0, reconexoes: 0
    },
