      params: [agora, 'Encerrado pelo reinício do sistema'] },
    { tag: 's1',
      sql: "UPDATE passagem_sistema SET boot_ms=$p1, ultimo_sinal=$p2 WHERE id=1;",
      params: [bootOk ? boot : 0, agora] }
);
return msg;

/* ============================================================
   NEREUS v13.1 - PASSAGEM DE SERVIÇO: DETECTOR DE ALARMES
   ------------------------------------------------------------
   Roda a cada 5 s, só LÊ o que o diagnóstico publicou em global e
   grava no SQLite um registro por alarme: início, fim e pico de
   severidade. É isso que permite à aba contar o que aconteceu no
   serviço anterior, algo que o banner (que guarda a ocorrência só
   no navegador) não consegue.

   Critério igual ao do banner:
     - motor: ATENÇÃO ou superior (AVISO e INFORMATIVO não contam);
     - enlace: falha real (nível 2 ou "FALHA DE COMUNICAÇÃO"); o
       "SEM DADOS" da partida não conta.
   Debounce de 30 s: oscilação rápida vira um só registro.
   ============================================================ */
if (!flow.get('pas_pronto')) return null;

var bb = global.get('diagnostico_mcp_bb');
var be = global.get('diagnostico_mcp_be');
var com = global.get('status_comunicacao');
if (!bb && !be && !com) return null;

var agoraMs = Date.now();
var DEBOUNCE_MS = 30000;
var ep = flow.get('pas_ep') || {};
var passos = [];

function iso(ms) { return new Date(ms).toISOString(); }
function norm(t) { return String(t).replace(/[0-9]+([.,][0-9]+)?/g, '#').replace(/\s+/g, ' ').trim().slice(0, 160); }

function considerar(chave, equip, ativo, nivel, sev, msgs) {
    var st = ep[chave];
    if (ativo) {
        if (!st) {
            st = ep[chave] = { nivelMax: nivel, ult: agoraMs, vistos: {}, det: msgs.slice(0, 6) };
            msgs.forEach(function (m) { st.vistos[norm(m)] = 1; });
            passos.push({ tag: 'e_' + chave,
                sql: "INSERT INTO passagem_eventos (chave, equipamento, inicio, nivel_max, severidade_max, resumo, detalhes) VALUES ($p1,$p2,$p3,$p4,$p5,$p6,$p7);",
                params: [chave, equip, iso(agoraMs), nivel, sev, msgs[0] || '', JSON.stringify(st.det)] });
        } else {
            st.ult = agoraMs;
            var mudou = false;
            if (nivel > st.nivelMax) { st.nivelMax = nivel; st.sevMax = sev; mudou = true; }
            msgs.forEach(function (m) {
                var k = norm(m);
                if (!st.vistos[k] && st.det.length < 8) { st.vistos[k] = 1; st.det.push(m); mudou = true; }
            });
            if (mudou) {
                passos.push({ tag: 'u_' + chave,
                    sql: "UPDATE passagem_eventos SET nivel_max=$p1, severidade_max=$p2, resumo=$p3, detalhes=$p4 WHERE chave=$p5 AND fim IS NULL;",
                    params: [st.nivelMax, st.sevMax || sev, (nivel >= st.nivelMax && msgs[0]) ? msgs[0] : (st.det[0] || ''), JSON.stringify(st.det), chave] });
            }
        }
    } else if (st && (agoraMs - st.ult) >= DEBOUNCE_MS) {
        passos.push({ tag: 'f_' + chave,
            sql: "UPDATE passagem_eventos SET fim=$p1 WHERE chave=$p2 AND fim IS NULL;",
            params: [iso(st.ult), chave] });
        delete ep[chave];
    }
}

function motor(chave, equip, d) {
    if (!d) return;
    var nivel = d.nivel || 0;
    var msgs = [].concat(d.criticos || [], d.atencao_alta || [], d.atencao || []);
    considerar(chave, equip, nivel >= 3, nivel, d.severidade || 'ATENCAO', msgs);
}
motor('MCP_BB', 'MCP BB', bb);
motor('MCP_BE', 'MCP BE', be);

if (com) {
    var falha = (Number(com.nivel) === 2) || com.status_comunicacao === 'FALHA DE COMUNICAÇÃO';
    var m = ['Enlace de dados: ' + (com.status_comunicacao || 'falha') + (com.ultimo_erro && com.ultimo_erro !== '—' ? ' · último erro: ' + com.ultimo_erro : '')];
    considerar('ENLACE', 'Enlace de dados', falha, 2, 'FALHA DE COMUNICAÇÃO', m);
}

flow.set('pas_ep', ep);
if (!passos.length) return null;
msg.pasModo = 'silencioso';
msg.pasSteps = passos;
return msg;

/* ============================================================
   NEREUS v13.2 - PASSAGEM DE SERVIÇO: SINAL DE VIDA
   ------------------------------------------------------------
   A cada 30 s grava, em passagem_sistema, o instante atual. No
   próximo arranque, o serviço que ficou aberto é encerrado com
   este instante como hora de fim (ver pas_fn_ddl).

   Escolhido no lugar do evento de fechamento do Node-RED porque
   este não é garantido em queda de energia nem em encerramento
   forçado. O sinal de vida cobre todos os casos, com erro máximo
   de 30 s na hora de fim registrada.
   ============================================================ */
if (!flow.get('pas_pronto')) return null;
msg.pasModo = 'silencioso';
msg.pasSteps = [
    { tag: 'hb', sql: "UPDATE passagem_sistema SET ultimo_sinal=$p1 WHERE id=1;", params: [new Date().toISOString()] }
];
return msg;

/* ============================================================
   NEREUS v13.1 - PASSAGEM DE SERVIÇO: RETRATO AO VIVO
   ------------------------------------------------------------
   Só LÊ o que o diagnóstico, o horímetro e o apurador de manutenção
   já publicaram em global. Não altera nenhum deles, por isso o hash
   do n6_fn_diag e a bancada 48/0 continuam valendo.

   Entrega à aba: situação geral, cartão dos dois motores com os
   quatro parâmetros principais, alertas ativos, enlace, pendências
   de instrumentação, ações recomendadas e rotinas de manutenção.
   ============================================================ */
var CFG = global.get('nereus_config');
var bb = global.get('diagnostico_mcp_bb');
var be = global.get('diagnostico_mcp_be');
var com = global.get('status_comunicacao') || {};
var qual = global.get('qualidade_canais') || {};
var hor = global.get('horimetro') || {};
var man = global.get('nereus_manutencao');
var tend = global.get('tendencias_60min') || [];
var recs = global.get('recomendacoes') || [];
var sevGeral = global.get('severidade_geral') || 'NORMAL';

var ROT_SEV = { NORMAL: 'NORMAL', INFORMATIVO: 'INFORMATIVO', AVISO: 'AVISO', ATENCAO: 'ATENÇÃO', ATENCAO_ALTA: 'ATENÇÃO ALTA', CRITICO: 'CRÍTICO' };
var NIVEL = { NORMAL: 0, INFORMATIVO: 1, AVISO: 2, ATENCAO: 3, ATENCAO_ALTA: 4, CRITICO: 5 };

function num(v, c) {
    if (v === null || v === undefined || !isFinite(v)) return '—';
    return Number(v).toFixed(c).replace('.', ',');
}
function seta(t, limiar, c, un) {
    if (t === null || t === undefined || !isFinite(t) || Math.abs(t) < limiar) return '';
    return (t > 0 ? '▲ ' : '▼ ') + num(Math.abs(t), c) + ' ' + un;
}

/* Rótulos dos canais, vindos da configuração da instalação. */
var rotuloCanal = {};
if (CFG && CFG.instalacao && CFG.instalacao.canais) {
    CFG.instalacao.canais.forEach(function (c) { rotuloCanal[c.id] = c.rotulo || c.id; });
}

function parametrosDe(equipId) {
    if (!CFG || !CFG.instalacao || !CFG.perfis) return {};
    var eq = (CFG.instalacao.equipamentos || []).filter(function (e) { return e.id === equipId; })[0];
    var perfil = eq && CFG.perfis[eq.perfil];
    return (perfil && perfil.parametros) || {};
}
function PV(par, k) { return par[k] ? par[k].valor : null; }
function R(par, k) { return par[k] ? String(par[k].valor).replace('.', ',') : ''; }

function faixa1h(nomeMotor, prefixo) {
    var t = tend.filter(function (x) { return x.motor === nomeMotor && String(x.rotulo).indexOf(prefixo) === 0; })[0];
    if (!t || t.min === null || t.min === undefined) return '';
    return num(t.min, prefixo === 'Rotação' ? 0 : (prefixo === 'Pressão' ? 2 : 1)) + ' a ' +
           num(t.max, prefixo === 'Rotação' ? 0 : (prefixo === 'Pressão' ? 2 : 1));
}

function cartao(equipId, nome, d, lado) {
    var par = parametrosDe(equipId);
    var h = {
        dia: lado === 'bb' ? hor.bb_dia_h : hor.be_dia_h,
        total: lado === 'bb' ? hor.bb_total_h : hor.be_total_h,
        ligado: lado === 'bb' ? hor.bb_ligado : hor.be_ligado
    };
    if (!d) return { nome: nome, lado: lado, sem_dados: true, sev: 'NORMAL', sevTxt: '—', estado: 'sem diagnóstico', linhas: [], alertas: [] };
    var linhas = [
        { rot: 'Temp. óleo lub.', valor: num(d.temp_oleo_c, 1), un: '°C',
          taxa: seta(d.taxa_oleo_c_min, 0.3, 2, '°C/min'),
          ref: PV(par, 'temp_oleo_normal_min') !== null ? 'normal ' + R(par, 'temp_oleo_normal_min') + ' a ' + R(par, 'temp_oleo_normal_max') + ' °C · crítico ' + R(par, 'temp_oleo_critico') + ' °C' : '',
          faixa: faixa1h(nome, 'Temp. óleo'), valido: true, nota: '' },
        { rot: 'Temp. água doce', valor: num(d.temp_agua_c, 1), un: '°C',
          taxa: seta(d.taxa_agua_c_min, 0.3, 2, '°C/min'),
          ref: PV(par, 'temp_agua_normal_min') !== null ? 'normal ' + R(par, 'temp_agua_normal_min') + ' a ' + R(par, 'temp_agua_normal_max') + ' °C · crítico ' + R(par, 'temp_agua_critico') + ' °C' : '',
          faixa: faixa1h(nome, 'Temp. água'), valido: true, nota: '' },
        { rot: 'Pressão óleo lub.', valor: d.pressao_valida === false ? '—' : num(d.press_oleo_bar, 2), un: 'bar',
          taxa: d.pressao_valida === false ? '' : seta(d.taxa_pressao_bar_min, 0.05, 2, 'bar/min'),
          ref: PV(par, 'pressao_min_operacao') !== null ? 'mínimo ' + R(par, 'pressao_min_operacao') + ' bar · crítico ' + R(par, 'pressao_critica') + ' bar' : '',
          faixa: d.pressao_valida === false ? '' : faixa1h(nome, 'Pressão'),
          valido: d.pressao_valida !== false,
          nota: d.pressao_valida === false ? 'canal fora de serviço' : (d.pressao_suspeita ? 'canal sob suspeita' : '') },
        { rot: 'Rotação', valor: num(d.rpm, 0), un: 'RPM',
          taxa: seta(d.taxa_rpm_min, 20, 0, 'RPM/min'),
          ref: PV(par, 'rpm_regime_estavel') !== null ? 'regime a partir de ' + R(par, 'rpm_regime_estavel') + ' RPM' : '',
          faixa: faixa1h(nome, 'Rotação'), valido: true, nota: '' }
    ];
    var alertas = []
        .concat((d.criticos || []).map(function (t) { return { n: 'CRITICO', t: t }; }))
        .concat((d.atencao_alta || []).map(function (t) { return { n: 'ATENCAO_ALTA', t: t }; }))
        .concat((d.atencao || []).map(function (t) { return { n: 'ATENCAO', t: t }; }))
        .concat((d.avisos || []).map(function (t) { return { n: 'AVISO', t: t }; }));
    return {
        nome: nome, lado: lado, estado: d.estado_texto || '—',
        sev: d.severidade || 'NORMAL', sevTxt: ROT_SEV[d.severidade] || d.severidade_texto || 'NORMAL',
        nivel: d.nivel || 0, linhas: linhas, alertas: alertas,
        horas_dia: num(h.dia, 1), horas_total: num(h.total, 1), ligado: !!h.ligado
    };
}

var motores = [cartao('MCP_BB', 'MCP BB', bb, 'bb'), cartao('MCP_BE', 'MCP BE', be, 'be')];

var pend = [];
(qual.inoperantes || []).forEach(function (c) { pend.push({ rotulo: rotuloCanal[c] || c, estado: 'INOPERANTE' }); });
(qual.suspeitos || []).forEach(function (c) { pend.push({ rotulo: rotuloCanal[c] || c, estado: 'SUSPEITO' }); });

var urgentes = recs.filter(function (r) { return r && (r.prioridade === 'IMEDIATA' || r.prioridade === 'ALTA'); });
var rotina = recs.filter(function (r) { return r && r.prioridade === 'ROTINA' && r.titulo !== 'Nenhuma ação pendente'; });

var manut = null;
if (man && man.resumo) {
    manut = {
        vencidas: man.resumo.vencidas || 0,
        proximas: man.resumo.proximas || 0,
        sem_registro: man.resumo.sem_registro || 0,
        itens: (man.itens || []).filter(function (i) { return i.situacao === 'VENCIDA' || i.situacao === 'PROXIMA'; }).slice(0, 8).map(function (i) {
            return { id: i.id, rotina: i.rotina, motor: i.motor, situacao: i.situacao, situacao_texto: i.situacao_texto || i.situacao,
                     horas_faltam_h: i.horas_faltam_h, dias_faltam: i.dias_faltam };
        })
    };
}

var comFalha = (Number(com.nivel) === 2) || com.status_comunicacao === 'FALHA DE COMUNICAÇÃO';
var alarmeAtivo = comFalha || motores.some(function (m) { return (m.nivel || 0) >= 3; });

var agora = new Date();
var semDiag = !bb && !be;
var vivo = {
    agora_iso: agora.toISOString(),
    hora_local: agora.toLocaleTimeString('pt-BR'),
    data_local: agora.toLocaleDateString('pt-BR'),
    sem_diagnostico: semDiag,
    alarme_ativo: alarmeAtivo,
    geral: { sev: sevGeral, sevTxt: ROT_SEV[sevGeral] || sevGeral, nivel: NIVEL[sevGeral] || 0 },
    motores: motores,
    enlace: {
        status: com.status_comunicacao || 'SEM DADOS',
        nivel: com.nivel === undefined ? 3 : com.nivel,
        falha: comFalha,
        interrupcoes_hoje: com.interrupcoes_hoje || 0,
        disponibilidade_pct: com.disponibilidade_pct === undefined || com.disponibilidade_pct === null ? null : num(com.disponibilidade_pct, 1),
        segundos_sem_leitura: com.segundos_sem_leitura,
        ultima_leitura_hora: com.ultima_leitura_hora || '—'
    },
    instrumentacao: pend,
    recomendacoes: urgentes.slice(0, 8).map(function (r) {
        return { motor: r.motor, prioridade: r.prioridade, titulo: r.titulo, detalhe: r.detalhe, responsavel: r.responsavel };
    }),
    recomendacoes_rotina: rotina.length,
    manutencao: manut
};

flow.set('pas_vivo', vivo);
node.status({ fill: alarmeAtivo ? 'red' : 'green', shape: 'dot', text: vivo.geral.sevTxt });
return { nrsKind: 'pas_vivo', topic: 'pas', payload: vivo };

/* ============================================================
   NEREUS v13.2 - PASSAGEM DE SERVIÇO: AÇÕES DA TELA
   ------------------------------------------------------------
   Recebe as ações da aba e monta a sequência de instruções SQL.

     pas_vivo     -> saída 2 (pede o retrato atual, sem banco)
     pas_get      -> lê serviço atual, histórico, alarmes, ocorrências
     pas_assumir  -> grava o novo serviço e fecha o anterior
     pas_nota     -> grava a anotação do serviço em curso
     pas_desfazer -> desfaz a última passagem (janela de 150 s)

   Regras que valem no servidor, não só na tela:
     - nome entre 3 e 60 caracteres;
     - ciência marcada;
     - o nome não pode ser o do militar que já está de serviço;
     - o serviço novo é gravado ANTES de o anterior ser fechado: se
       algo falhar no meio, nunca fica sem militar de serviço.
   ============================================================ */
var p = msg.payload || {};
var a = p.action;
var agora = new Date();
function isoMenos(ms) { return new Date(agora.getTime() - ms).toISOString(); }
var ID_SERVICO_ATUAL = "(SELECT inicio FROM passagem_servico WHERE fim IS NULL ORDER BY id DESC LIMIT 1)";

function leitura() {
    var fallback = isoMenos(12 * 3600 * 1000);
    return [
        { tag: 'cur', sql: "SELECT id, militar, inicio, anterior, notas FROM passagem_servico WHERE fim IS NULL ORDER BY id DESC LIMIT 1;", params: [] },
        { tag: 'hist',
          sql: "SELECT s.id, s.militar, s.inicio, s.fim, s.rendido_por, s.anterior, s.notas, s.snapshot, " +
               "(SELECT COUNT(*) FROM passagem_eventos e WHERE e.inicio < COALESCE(s.fim,'9999') AND COALESCE(e.fim,'9999') >= s.inicio) AS n_alarmes, " +
               "(SELECT MAX(e.nivel_max) FROM passagem_eventos e WHERE e.chave <> 'ENLACE' AND e.inicio < COALESCE(s.fim,'9999') AND COALESCE(e.fim,'9999') >= s.inicio) AS pico " +
               "FROM passagem_servico s ORDER BY s.id DESC LIMIT 12;", params: [] },
        { tag: 'eventos',
          sql: "SELECT id, chave, equipamento, inicio, fim, nivel_max, severidade_max, resumo, detalhes, obs FROM passagem_eventos " +
               "WHERE COALESCE(fim,'9999') >= COALESCE(" + ID_SERVICO_ATUAL + ", $p1) ORDER BY inicio DESC LIMIT 100;",
          params: [fallback] },
        { tag: 'ocorr',
          sql: "SELECT id, titulo, equipamento, data_hora, descricao, autor, status FROM manutencao_historico " +
               "WHERE COALESCE(status,'') NOT IN ('Concluído','Resolvido') " +
               "OR data_atualizacao >= datetime(COALESCE(" + ID_SERVICO_ATUAL + ", $p1), 'localtime') ORDER BY id DESC LIMIT 20;",
          params: [fallback] },
        { tag: 'nomes', sql: "SELECT militar, MAX(inicio) AS ultimo FROM passagem_servico GROUP BY militar ORDER BY ultimo DESC LIMIT 15;", params: [] },
        // v13.2: último serviço encerrado, base do atalho "Retomar" da janela do primeiro militar.
        { tag: 'ult', sql: "SELECT id, militar, inicio, fim, rendido_por FROM passagem_servico WHERE fim IS NOT NULL ORDER BY id DESC LIMIT 1;", params: [] }
    ];
}

function recusar(acao, texto) {
    return [null, null, { nrsKind: 'pas_estado', topic: 'pas', payload: { resultado: { acao: acao, ok: false, texto: texto } } }];
}

if (a === 'pas_vivo') return [null, msg, null];

msg.pasModo = 'ui';
msg.pasT0 = agora.toISOString();

if (a === 'pas_get') {
    msg.pasAcao = 'get';
    msg.pasSteps = leitura();
    return [msg, null, null];
}

if (a === 'pas_nota') {
    var texto = String(p.texto == null ? '' : p.texto).replace(/\r/g, '').slice(0, 2000);
    msg.pasAcao = 'nota';
    msg.pasSteps = [
        { tag: 'w1', crit: true,
          sql: "UPDATE passagem_servico SET notas=$p1 WHERE id=(SELECT MAX(id) FROM passagem_servico WHERE fim IS NULL);",
          params: [texto] }
    ].concat(leitura());
    return [msg, null, null];
}

if (a === 'pas_assumir') {
    var nome = String(p.nome == null ? '' : p.nome).replace(/\s+/g, ' ').trim();
    if (nome.length < 3 || nome.length > 60) return recusar('assumir', 'Informe o posto/graduação e o nome (de 3 a 60 caracteres).');
    if (p.ciencia !== true) return recusar('assumir', 'Marque a ciência das condições para assumir o serviço.');

    // Retrato das condições que o militar viu ao assumir (último ciclo de 5 s da tela).
    var vivo = flow.get('pas_vivo') || null;
    var snap = null;
    if (vivo) {
        snap = {
            em: vivo.agora_iso,
            severidade: vivo.geral ? vivo.geral.sev : null,
            motores: (vivo.motores || []).map(function (m) {
                return { nome: m.nome, estado: m.estado, sev: m.sev, alertas: (m.alertas || []).map(function (x) { return x.t; }),
                         leituras: (m.linhas || []).map(function (l) { return l.rot + ': ' + l.valor + ' ' + l.un; }) };
            }),
            enlace: vivo.enlace ? vivo.enlace.status : null,
            instrumentacao: (vivo.instrumentacao || []).map(function (i) { return i.rotulo + ' (' + i.estado + ')'; }),
            acoes: (vivo.recomendacoes || []).map(function (r) { return r.prioridade + ': ' + r.titulo; }),
            manutencao: vivo.manutencao ? { vencidas: vivo.manutencao.vencidas, proximas: vivo.manutencao.proximas } : null
        };
    }
    msg.pasAcao = 'assumir';
    msg.pasNome = nome;
    // Anotação digitada e ainda não salva pelo militar que está passando o serviço: grava na linha dele, antes da troca.
    var passosNota = [];
    if (p.notas !== undefined && p.notas !== null) {
        passosNota.push({ tag: 'w0',
            sql: "UPDATE passagem_servico SET notas=$p1 WHERE id=(SELECT MAX(id) FROM passagem_servico WHERE fim IS NULL);",
            params: [String(p.notas).replace(/\r/g, '').slice(0, 2000)] });
    }
    msg.pasSteps = passosNota.concat([
        { tag: 'w1', crit: true,
          sql: "INSERT INTO passagem_servico (militar, inicio, anterior, snapshot, ciencia) " +
               "SELECT $p1, $p2, (SELECT militar FROM passagem_servico WHERE fim IS NULL ORDER BY id DESC LIMIT 1), $p3, 1 " +
               "WHERE NOT EXISTS (SELECT 1 FROM passagem_servico WHERE fim IS NULL AND lower(militar)=lower($p4));",
          params: [nome, msg.pasT0, JSON.stringify(snap), nome] },
        { tag: 'w2', crit: true,
          sql: "UPDATE passagem_servico SET fim=$p1, rendido_por=$p2 WHERE fim IS NULL AND id < (SELECT MAX(id) FROM passagem_servico);",
          params: [msg.pasT0, nome] }
    ]).concat(leitura());
    return [msg, null, null];
}

if (a === 'pas_desfazer') {
    var id = Number(p.id);
    if (!isFinite(id)) return recusar('desfazer', 'Passagem não identificada.');
    msg.pasAcao = 'desfazer';
    msg.pasId = id;
    msg.pasSteps = [
        { tag: 'w1', crit: true,
          sql: "DELETE FROM passagem_servico WHERE id=$p1 AND id=(SELECT MAX(id) FROM passagem_servico) AND inicio >= $p2;",
          params: [id, isoMenos(150 * 1000)] },
        { tag: 'w2', crit: true,
          sql: "UPDATE passagem_servico SET fim=NULL, rendido_por=NULL WHERE id=(SELECT MAX(id) FROM passagem_servico) " +
               "AND fim IS NOT NULL AND NOT EXISTS (SELECT 1 FROM passagem_servico WHERE fim IS NULL);",
          params: [] }
    ].concat(leitura());
    return [msg, null, null];
}

return [null, null, null];

/* ============================================================
   NEREUS v13.1 - PASSAGEM DE SERVIÇO: EXECUTOR DE PASSOS
   ------------------------------------------------------------
   O nó sqlite executa uma instrução por mensagem. Este nó recebe
   uma mensagem com msg.pasSteps (lista de {tag, sql, params, crit})
   e a devolve ao nó sqlite passo a passo, na ordem, guardando o
   resultado de cada um em msg.pasRes[tag].

   Saída 1 : próximo passo, para o nó sqlite.
   Saída 2 : lista esgotada, para o formatador.

   O nó sqlite só usa os parâmetros se a quantidade de "$" no SQL for
   igual à de parâmetros. Por isso cada marcador tem nome próprio
   ($p1, $p2...) e cada um aparece uma única vez. A conferência abaixo
   evita o caso silencioso em que o nó roda a consulta sem parâmetro.
   ============================================================ */
if (msg.pasRodando) {
    msg.pasRes = msg.pasRes || {};
    msg.pasRes[msg.pasTag] = msg.payload;
}
var s = msg.pasSteps;
if (s && s.length) {
    var st = s.shift();
    var params = st.params || [];
    var n = (st.sql.match(/\$/g) || []).length;
    if (n !== params.length) {
        node.error("Passagem de serviço: o passo '" + st.tag + "' tem " + n + " marcador(es) e " + params.length + " parâmetro(s).", msg);
        return [null, null];
    }
    msg.pasTag = st.tag;
    msg.pasCrit = !!st.crit;
    msg.pasRodando = true;
    msg.topic = st.sql;
    msg.payload = params;
    return [msg, null];
}
return [null, msg];

/* ============================================================
   NEREUS v13.2 - PASSAGEM DE SERVIÇO: MONTAGEM DA RESPOSTA
   ------------------------------------------------------------
   Junta os resultados dos passos e entrega à tela uma única
   mensagem (nrsKind 'pas_estado'). O resultado de uma ação
   (assumir, anotar, desfazer) é conferido no próprio banco:
   a tela só mostra sucesso se o registro realmente existe.
   ============================================================ */
if (msg.pasModo === 'ddl') {
    flow.set('pas_pronto', true);
    node.status({ fill: 'green', shape: 'dot', text: 'tabelas prontas' });
    return null;
}
if (msg.pasModo !== 'ui') return null;

function pj(v, def) { try { var x = JSON.parse(v); return x == null ? def : x; } catch (e) { return def; } }

var R = msg.pasRes || {};
var cur = (R.cur && R.cur[0]) || null;
flow.set('pas_atual', cur ? cur.militar : null);

var est = {
    cur: cur,
    hist: (R.hist || []).map(function (h) { h.snapshot = pj(h.snapshot, null); return h; }),
    eventos: (R.eventos || []).map(function (e) {
        e.detalhes = pj(e.detalhes, []);
        return e;
    }),
    ocorr: R.ocorr || [],
    nomes: (R.nomes || []).map(function (n) { return n.militar; }),
    ultimo: (R.ult && R.ult[0]) || null,
    falhas: msg.pasFalhas || [],
    carregado_em: new Date().toISOString()
};

if (msg.pasAcao === 'assumir') {
    var ok = !!(cur && String(cur.militar).toLowerCase() === String(msg.pasNome).toLowerCase() && cur.inicio >= msg.pasT0);
    est.resultado = {
        acao: 'assumir', ok: ok,
        texto: ok ? 'Serviço assumido por ' + cur.militar + '.'
                  : 'Passagem não registrada: este nome já consta como militar de serviço.'
    };
} else if (msg.pasAcao === 'desfazer') {
    var desfeito = !cur || cur.id !== msg.pasId;
    est.resultado = {
        acao: 'desfazer', ok: desfeito,
        texto: desfeito ? 'Passagem desfeita. Voltou a constar o militar anterior.'
                        : 'Não foi possível desfazer: o prazo de 2 minutos terminou ou já há outra passagem.'
    };
} else if (msg.pasAcao === 'nota') {
    est.resultado = { acao: 'nota', ok: true, texto: 'Anotação salva.' };
}

return { nrsKind: 'pas_estado', topic: 'pas', payload: est };

/* ============================================================
   NEREUS v13.1 - PASSAGEM DE SERVIÇO: FALHA NO BANCO
   ------------------------------------------------------------
   Recebe o erro do nó sqlite (via catch).
   - Rotina interna (detector, arranque): só registra no depurador.
   - Leitura da tela: o passo que falhou fica vazio e a sequência
     continua, para a tela receber o que for possível.
   - Gravação (passo crítico): interrompe e avisa a tela.
   ============================================================ */
var texto = (msg.error && msg.error.message) ? String(msg.error.message) : "erro desconhecido";
if (msg.pasModo === 'silencioso' || msg.pasModo === 'ddl') {
    node.warn("Passagem de serviço (" + msg.pasModo + ", passo " + msg.pasTag + "): " + texto);
    return [null, null];
}
if (!msg.pasCrit && msg.pasRodando) {
    msg.pasRes = msg.pasRes || {};
    msg.pasRes[msg.pasTag] = null;
    msg.pasFalhas = (msg.pasFalhas || []).concat(msg.pasTag);
    msg.payload = [];
    delete msg.error;
    return [msg, null];
}
return [null, {
    nrsKind: 'pas_estado',
    topic: 'pas',
    payload: { resultado: { acao: msg.pasAcao || '', ok: false, texto: "Não foi possível gravar: " + texto } }
}];
